local config = {
  ui_story_5046_50460101_1_dialog_content = "PlayerName!",
  ui_story_5046_50460101_2_dialog_content = "It is so wonderful to have you here for the completion ceremony of the Umbraton Orphanage!",
  ui_story_5046_50460101_3_dialog_content = "It's been a while, Bethel.",
  ui_story_5046_50460101_4_dialog_content = "I wouldn't miss it for the world even without an invitation from the Shadowlord.",
  ui_story_5046_50460101_5_dialog_content = "After all, we're old friends.",
  ui_story_5046_50460101_6_dialog_content = "To be honest, I was stunned by how fancy the invitation was.",
  ui_story_5046_50460101_7_dialog_content = "Of course! We can't skip protocol just because we're good friends.",
  ui_story_5046_50460101_8_dialog_content = "Not to mention many nobles from Lumopolis are also attending, and you know how much etiquette means to them.",
  ui_story_5046_50460101_9_dialog_content = "They would've raised a ruckus if they found out you never got an invitation from the Shadowlord.",
  ui_story_5046_50460101_10_dialog_content = "Never underestimate the power of gossip.",
  ui_story_5046_50460101_11_dialog_content = "That's so true...",
  ui_story_5046_50460101_12_dialog_content = "There's a rumor going around that I'm a monster with multiple heads, claws, and fangs.",
  ui_story_5046_50460101_13_dialog_content = "I mean, how could that even be possible?!",
  ui_story_5046_50460101_14_dialog_content = "That's practically slander, PlayerName. Haven't you considered legal options?",
  ui_story_5046_50460101_15_dialog_content = "W-Well, I just admonished those guys a bit and that was it.",
  ui_story_5046_50460101_16_dialog_content = "No way! You let them off the hook too easily.",
  ui_story_5046_50460101_17_dialog_content = "You have to punish them or such lies will only further damage your reputation.",
  ui_story_5046_50460101_18_dialog_content = "Not everyone values getting to know someone through direct contact over gossip.",
  ui_story_5046_50460101_19_dialog_content = "You're right...",
  ui_story_5046_50460101_20_dialog_content = "By the way, where are Vice and Carleen? Are they not with you?",
  ui_story_5046_50460101_21_dialog_content = "They're too busy with their own things to be here today.",
  ui_story_5046_50460101_22_dialog_content = "They did ask me to apologize on their behalf.",
  ui_story_5046_50460101_23_dialog_content = "It's okay, it happens... I'm just happy you made it.",
  ui_story_5046_50460101_24_dialog_content = "I'm curious, though, why invite me?",
  ui_story_5046_50460101_25_dialog_content = "I have nothing to do with the orphanage in Umbraton, isn't it awkward for me to attend the ceremony?",
  ui_story_5046_50460101_26_dialog_content = "Don't worry about it.",
  ui_story_5046_50460101_27_dialog_content = "We sent invitations to many luminaries and we welcome all who are willing to come.",
  ui_story_5046_50460101_28_dialog_content = "The ceremony is not simply a way to show gratitude to those who helped us, but it's also so we can promote the facility to the community and secure additional funding.",
  ui_story_5046_50460101_29_dialog_content = "Having the foresight to plan ahead like that sounds just like you, Bethel!",
  ui_story_5046_50460101_30_dialog_content = "The ceremony is a very important event, so to make sure it goes without a hitch, we're having a rehearsal today.",
  ui_story_5046_50460101_31_dialog_content = "Would you like to join and familiarize yourself with the process?",
  ui_story_5046_50460101_32_dialog_content = "Sure, no problem!",
  ui_story_5046_50460101_33_dialog_content = "Follow me, then.",
  ui_story_5046_50460101_34_dialog_content = "<color=#e8d9bb>Umbraton Orphanage Completion Ceremony Rehearsal</color>",
  ui_story_5046_50460101_35_dialog_content = "Security is in place, Miss Bethel.",
  ui_story_5046_50460101_36_dialog_content = "Well done, thank you.",
  ui_story_5046_50460101_37_dialog_content = "Let me introduce you, PlayerName.",
  ui_story_5046_50460101_38_dialog_content = "This is Zenas, in charge of security for the rehearsal and also the captain of the security squad.",
  ui_story_5046_50460101_39_dialog_content = "Your reputation proceeds you, Caelestite.",
  ui_story_5046_50460101_40_dialog_content = "I'm flattered.",
  ui_story_5046_50460101_41_dialog_content = "(These two seem to be from Lumopolis with how they're dressed and are probably high in standing too.)",
  ui_story_5046_50460101_42_dialog_content = "(Why are they working security?)",
  ui_story_5046_50460101_43_dialog_content = "And this is probationary judge Kristen from the Lumo Hall of Justice, who will be helping Zenas with the security detail.",
  ui_story_5046_50460101_44_dialog_content = "Hello, I'm Kristen.",
  ui_story_5046_50460101_45_dialog_content = "Judge Irridon and others have mentioned you a lot and praised your resourcefulness and courage.",
  ui_story_5046_50460101_46_dialog_content = "Hehe, you flatter me...",
  ui_story_5046_50460101_47_dialog_content = "Mr. Hamell!",
  ui_story_5046_50460101_48_dialog_content = "Miss Bethel!",
  ui_story_5046_50460101_49_dialog_content = "I didn't expect you'd be here, Mr. Hamell. It's just a rehearsal today.",
  ui_story_5046_50460101_50_dialog_content = "I had nothing to do anyway, so I figured I'd come check it out.",
  ui_story_5046_50460101_51_dialog_content = "I greatly appreciate the effort you and the Shadowlord put into rebuilding the orphanage, Miss Bethel.",
  ui_story_5046_50460101_52_dialog_content = "I should be the one thanking you on behalf of the children for leading the charge to rebuild it.",
  ui_story_5046_50460101_53_dialog_content = "Oh, forgive my rudeness. Let me introduce you to PlayerName, the Caelestite.",
  ui_story_5046_50460101_54_dialog_content = "PlayerName, this is Mr. Hamell, the soon-to-be director of the orphanage and a well-known antique dealer in Umbraton.",
  ui_story_5046_50460101_55_dialog_content = "You look much younger in person, Caelestite, and to be so accomplished already at such an age.",
  ui_story_5046_50460101_56_dialog_content = "Roaming Astra on your Colossus, working often with the famous Cloudrover Guild.",
  ui_story_5046_50460101_57_dialog_content = "You're a rare talent!",
  ui_story_5046_50460101_58_dialog_content = "I-I managed that only through the help of others.",
  ui_story_5046_50460101_59_dialog_content = "Relationships are a vital part of business too!",
  ui_story_5046_50460101_60_dialog_content = "It's not easy to build and maintain connections like you have!",
  ui_story_5046_50460101_61_dialog_content = "I'm glad that even in my old age, I get to meet someone like you...",
  ui_story_5046_50460101_62_dialog_content = "You're overstating it, sir. I'm just a normal person...",
  ui_story_5046_50460101_63_dialog_content = "Word is that you're quite wealthy.",
  ui_story_5046_50460101_64_dialog_content = "What? Where did you hear that?",
  ui_story_5046_50460101_65_dialog_content = "The expenses to upkeep such a huge Colossus must be enormous.",
  ui_story_5046_50460101_66_dialog_content = "That's true, but that doesn't mean I'm rich...",
  ui_story_5046_50460101_67_dialog_content = "Humble, I see!",
  ui_story_5046_50460101_68_dialog_content = "Rich folks who are well-connected and as humble as you are few and far between in Astra.",
  ui_story_5046_50460101_69_dialog_content = "Let's not even bring up compassion!",
  ui_story_5046_50460101_70_dialog_content = "Would you be interested in sponsoring the orphanage long-term?",
  ui_story_5046_50460101_71_dialog_content = "Uh...",
  ui_story_5046_50460101_72_dialog_content = "Ahem.",
  ui_story_5046_50460101_73_dialog_content = "Please don't put our guest on the spot, Mr. Hamell.",
  ui_story_5046_50460101_74_dialog_content = "Any long-term partnership should be built on mutual respect and trust.",
  ui_story_5046_50460101_75_dialog_content = "Oh, yes, right...",
  ui_story_5046_50460101_76_dialog_content = "I jumped the gun.",
  ui_story_5046_50460101_77_dialog_content = "It's quite all right. I know you're just looking out for the children.",
  ui_story_5046_50460101_78_dialog_content = "Anyway, today's just a rehearsal, so everyone can get to know one another.",
  ui_story_5046_50460101_79_dialog_content = "We can talk about partnerships later.",
  ui_story_5046_50460101_80_dialog_content = "You're right.",
  ui_story_5046_50460101_81_dialog_content = "Excuse me, I must go tend to details for the official event.",
  ui_story_5046_50460101_82_dialog_content = "I have to take my leave, but feel free to talk among yourselves.",
  ui_story_5046_50460101_83_dialog_content = "Bethel sure has a lot on her plate.",
  ui_story_5046_50460101_84_dialog_content = "By the way, I've been wondering...",
  ui_story_5046_50460101_85_option_content = "Why is Lumopolis handling security for an event in Umbraton?",
  ui_story_5046_50460101_86_dialog_content = "As you can see, the guests for this event include high nobles from Lumopolis.",
  ui_story_5046_50460101_87_dialog_content = "They don't trust the mercenaries in Umbraton, so they requested their own people for protection.",
  ui_story_5046_50460101_88_dialog_content = "And given the recent unrest in Umbraton from the arson spree, the nobles are taking extra precautions.",
  ui_story_5046_50460101_89_dialog_content = "That's why Lumopolis sent me and Miss Kristen to keep the peace here.",
  ui_story_5046_50460101_90_dialog_content = "Arson? You know, I did see wanted posters when I came into town.",
  ui_story_5046_50460101_91_dialog_content = "Though it was too crowded for me to get close and make out the details...",
  ui_story_5046_50460101_92_dialog_content = "Luckily, I happen to have a copy for you to take a look at.",
  ui_story_5046_50460101_93_dialog_content = "\"Wanted:\"",
  ui_story_5046_50460101_94_dialog_content = "\"Suspect guilty of committing multiple arsons in Umbraton, which resulted in three deaths and many injured.\"",
  ui_story_5046_50460101_95_dialog_content = "\"200,000 Nightium reward for any information leading to an arrest.\"",
  ui_story_5046_50460101_96_dialog_content = "\"Suspect Traits: Extremely strong, fast, and savage as a beast.\"",
  ui_story_5046_50460101_97_dialog_content = "\"Suspect Alias: Dark Slayer.\"",
  ui_story_5046_50460101_98_dialog_content = "200,000 Nightium? That's a lot! If only I could nab this Dark Slayer...",
  ui_story_5046_50460101_99_dialog_content = "But that moniker sounds horrifying enough for me not to risk it.",
  ui_story_5046_50460101_100_dialog_content = "And the image on the poster is too blurry to be of any practical use...",
  ui_story_5046_50460101_101_dialog_content = "Unfortunately, no one has yet to get a clear look at the suspect.",
  ui_story_5046_50460101_102_dialog_content = "Some Umbraton residents got a glimpse of a beast-like figure leaving the scene in the first arson, but that's it.",
  ui_story_5046_50460101_103_dialog_content = "So the suspect is likely a demi-human.",
  ui_story_5046_50460101_104_dialog_content = "Please notify Captain Zenas or me if you spot anyone resembling the image at the earliest opportunity.",
  ui_story_5046_50460101_105_dialog_content = "The suspect is very brutal, so please avoid confrontation even if the reward money sounds enticing. Protect your own safety first.",
  ui_story_5046_50460101_106_dialog_content = "G-Got it...",
  ui_story_5046_50460101_107_dialog_content = "Any other questions?",
  ui_story_5046_50460101_108_option_content = "Was there a fire in the old orphanage?",
  ui_story_5046_50460101_109_dialog_content = "It was accidentally set ablaze years ago, burning the building to the ground. Fortunately, no child was hurt.",
  ui_story_5046_50460101_110_dialog_content = "Thankfully, the kind Shadowlord opened up one of his houses and let the poor children live there.",
  ui_story_5046_50460101_111_dialog_content = "And they've been there all these years.",
  ui_story_5046_50460101_112_dialog_content = "But it's not a long-term solution, not to mention many homeless kids are still wandering the street.",
  ui_story_5046_50460101_113_dialog_content = "I made some money dealing in antiques in recent years, so it's my hope to rebuild the orphanage and give them a home.",
  ui_story_5046_50460101_114_dialog_content = "Despite losing their parents, they can still grow up in the company of peers and kind-hearted people.",
  ui_story_5046_50460101_115_dialog_content = "You're very admirable, Mr. Hamell.",
  ui_story_5046_50460101_116_dialog_content = "That is incredibly noble of you, Mr. Hamell.",
  ui_story_5046_50460101_117_dialog_content = "I'm just trying to do what little I can for the kids.",
  ui_story_5046_50460101_118_dialog_content = "Let's hope the new facility will stay safe and sound.",
  ui_story_5046_50460101_119_dialog_content = "Any other questions?",
  ui_story_5046_50460101_120_option_content = "Nothing else.",
  ui_story_5046_50460101_121_dialog_content = "It's getting late, sir. We must start making our rounds.",
  ui_story_5046_50460101_122_dialog_content = "Pardon me for keeping you from your job!",
  ui_story_5046_50460101_123_dialog_content = "You're fine. Ensuring the safety of the guests is a part of our duty.",
  ui_story_5046_50460101_124_dialog_content = "<color=#e8d9bb>Clang—</color>",
  ui_story_5046_50460101_125_dialog_content = "Hm? Mr. Zenas, you dropped something.",
  ui_story_5046_50460101_126_dialog_content = "(Such a delicate pendant, and there's this cute pony on it too.)",
  ui_story_5046_50460101_127_dialog_content = "Here you go.",
  ui_story_5046_50460101_128_dialog_content = "Thanks.",
  ui_story_5046_50460101_129_dialog_content = "It's getting late, my lady. We should begin our rounds.",
  ui_story_5046_50460101_130_dialog_content = "Yes, sir—",
  ui_story_5046_50460101_131_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5046_50460101_132_dialog_content = "What's happening?!",
  ui_story_5046_50460101_133_dialog_content = "Fire! Fire!",
  ui_story_5046_50460101_134_dialog_content = "How did the fire just come out of nowhere?",
  ui_story_5046_50460101_135_dialog_content = "It's the Dark Slayer's handiwork if you ask me!",
  ui_story_5046_50460101_136_dialog_content = "That barbaric Dark Slayer is here?!",
  ui_story_5046_50460101_137_dialog_content = "Don't panic. Looks like the fire started at the orphanage.",
  ui_story_5046_50460101_138_dialog_content = "Let's go take a look, miss.",
  ui_story_5046_50460101_139_dialog_content = "Yes, sir!",
  ui_story_5046_50460101_140_dialog_content = "<color=#e8d9bb>Nearby</color>",
  ui_story_5046_50460101_141_dialog_content = "...",
  ui_story_5046_50460201_1_dialog_content = "PlayerName, Mr. Hamell.",
  ui_story_5046_50460201_2_dialog_content = "Please stay put. Lumopolis guards will arrive shortly for your protection.",
  ui_story_5046_50460201_3_dialog_content = "I want to go with you! I can pinpoint people with my psychic abilities!",
  ui_story_5046_50460201_4_dialog_content = "Me too. I want to know how the fire got started!",
  ui_story_5046_50460201_5_dialog_content = "All right. It's urgent, so please follow me closely. I'll do my best to make sure you're safe!",
  ui_story_5046_50460201_6_dialog_content = "*Coughs* There's so much smoke here, I can't see anything. We've got to put the fire out right now...",
  ui_story_5046_50460201_7_dialog_content = "Radial Currents!",
  ui_story_5046_50460201_8_dialog_content = "Wait, Kristen!",
  ui_story_5046_50460201_9_dialog_content = "<color=#e8d9bb>BOOM!</color>",
  ui_story_5046_50460201_10_dialog_content = "Watch out!",
  ui_story_5046_50460201_11_dialog_content = "Oh no! Are you okay, sir?",
  ui_story_5046_50460201_12_dialog_content = "*Coughs*... I'm fine.",
  ui_story_5046_50460201_13_dialog_content = "The fire is spreading along the oil on the ground. This flammable liquid will just float on top of the water and keep burning, so you cannot extinguish it with water.",
  ui_story_5046_50460201_14_dialog_content = "Sorry, sir, for getting you hurt again...",
  ui_story_5046_50460201_15_dialog_content = "Now is not the time to go into that.",
  ui_story_5046_50460201_16_dialog_content = "PlayerName, please use your psychic abilities to scan for survivors or even signs of the Dark Slayer!",
  ui_story_5046_50460201_17_dialog_content = "You got it!",
  ui_story_5046_50460201_18_option_content = "Force Boost!",
  ui_story_5046_50460201_19_dialog_content = "*Sobbing* Help...",
  ui_story_5046_50460201_20_dialog_content = "There's a child trapped in this direction!",
  ui_story_5046_50460201_21_dialog_content = "...",
  ui_story_5046_50460201_22_dialog_content = "Mom...",
  ui_story_5046_50460201_23_dialog_content = "*Coughing* My throat, it hurts...",
  ui_story_5046_50460201_24_dialog_content = "She can't hold on much longer. We have to save her!",
  ui_story_5046_50460201_25_dialog_content = "There's too much smoke, PlayerName. I can't see you!",
  ui_story_5046_50460201_26_dialog_content = "Don't go in there! The fire is intense, it's too dangerous!",
  ui_story_5046_50460201_27_dialog_content = "Don't worry, I'm here to get you out!",
  ui_story_5046_50460201_28_dialog_content = "Cough, cough... I'm over here!",
  ui_story_5046_50460201_29_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5046_50460201_30_dialog_content = "Oh no, the house is starting to collapse from the fire.",
  ui_story_5046_50460201_31_dialog_content = "I must find a way out, but the thick smoke is making it impossible!",
  ui_story_5046_50460201_32_dialog_content = "I'm scared... *Sobbing*",
  ui_story_5046_50460201_33_dialog_content = "It's okay, we'll find a way out!",
  ui_story_5046_50460201_34_dialog_content = "<color=#e8d9bb>Crush!</color>",
  ui_story_5046_50460201_35_dialog_content = "The room is collapsing—!",
  ui_story_5046_50460201_36_dialog_content = "Arghhh—!",
  ui_story_5046_50460201_37_dialog_content = "Open your eyes, you're not dead yet.",
  ui_story_5046_50460201_38_dialog_content = "Who's speaking?",
  ui_story_5046_50460201_39_dialog_content = "Since you're still alive, get up and go.",
  ui_story_5046_50460201_40_dialog_content = "Doggy! *Splutters and coughs*",
  ui_story_5046_50460201_41_dialog_content = "A big doggy saved us!",
  ui_story_5046_50460201_42_dialog_content = "B-Big dude...?",
  ui_story_5046_50460201_43_dialog_content = "I think it's a girl... despite her masculine presence.",
  ui_story_5046_50460201_44_dialog_content = "Doggy! Cough, cough... A dog! A cute, fluffy dog!",
  ui_story_5046_50460201_45_dialog_content = "Just like... cough, cough... the kind that saves people in stories...",
  ui_story_5046_50460201_46_dialog_content = "Quiet and kind-hearted... cough, cough... big doggy!",
  ui_story_5046_50460201_47_dialog_content = "How long are you going to keep yapping? I'm leaving if you wanna get burned to a crisp.",
  ui_story_5046_50460201_48_dialog_content = "H-How come the flames aren't burning you?",
  ui_story_5046_50460201_49_dialog_content = "These flames? They can't hurt me.",
  ui_story_5046_50460201_50_dialog_content = "W-Wait! Where have I seen you before...",
  ui_story_5046_50460201_51_dialog_content = "Y-You, you're the Dark Slayer!",
  ui_story_5046_50460201_52_dialog_content = "Dark Slayer? You got the wrong person.",
  ui_story_5046_50460201_53_dialog_content = "My name is Hati.",
  ui_story_5046_50460201_54_dialog_content = "Oh, and since you look so scared of me, how about letting go of my hand?",
  ui_story_5046_50460201_55_dialog_content = "Where are you, PlayerName?",
  ui_story_5046_50460201_56_dialog_content = "*Coughing* I brought help, and the fire out there is almost gone!",
  ui_story_5046_50460201_57_dialog_content = "I think there's someone with PlayerName!",
  ui_story_5046_50460201_58_dialog_content = "It looks like... the Dark Slayer!",
  ui_story_5046_50460201_59_dialog_content = "The Dark Slayer?!",
  ui_story_5046_50460201_60_dialog_content = "Arson suspect Dark Slayer, I order you to release the hostage at once!",
  ui_story_5046_50460201_61_dialog_content = "Like I said, I'm not the Dark Slayer. My name is Hati.",
  ui_story_5046_50460201_62_dialog_content = "And what do you mean by hostage?",
  ui_story_5046_50460201_63_dialog_content = "We're open to any terms as long as you let PlayerName go!",
  ui_story_5046_50460201_64_dialog_content = "Terms? Like trading one thing for another?",
  ui_story_5046_50460201_65_dialog_content = "I guess PlayerName is precious to you. Are you PlayerName?",
  ui_story_5046_50460201_66_dialog_content = "Y-Yes, that's me. I'll be your hostage, just let the girl go.",
  ui_story_5046_50460201_67_dialog_content = "Don't do anything stupid, Dark Slayer!",
  ui_story_5046_50460201_68_dialog_content = "Again with that? How irritating!",
  ui_story_5046_50460201_69_dialog_content = "The big doggy is mean...",
  ui_story_5046_50460201_70_dialog_content = "Ugh—!",
  ui_story_5046_50460201_71_dialog_content = "Dark Slayer has PlayerName!",
  ui_story_5046_50460201_72_dialog_content = "Come any closer and I'll kill him.",
  ui_story_5046_50460201_73_dialog_content = "Since this one seems so important to you, let me keep him for a while.",
  ui_story_5046_50460201_74_dialog_content = "Hey, where are you taking me? Let go of me!",
  ui_story_5046_50460201_75_dialog_content = "Help!",
  ui_story_5046_50460201_76_dialog_content = "Stop them, guards!",
  ui_story_5046_50460201_77_dialog_content = "Do not let Dark Slayer get away with PlayerName!",
  ui_story_5046_50460202_1_dialog_content = "The guards have lost the Dark Slayer.",
  ui_story_5046_50460202_2_dialog_content = "Sorry, sir...",
  ui_story_5046_50460202_3_dialog_content = "It's not your fault. The Dark Slayer can control fire, that gives her an advantage.",
  ui_story_5046_50460202_4_dialog_content = "Also, she moves a lot quicker than ordinary people.",
  ui_story_5046_50460202_5_dialog_content = "It's not a surprise you couldn't keep up with her.",
  ui_story_5046_50460202_6_dialog_content = "Well, your contingency plan came in handy.",
  ui_story_5046_50460202_7_dialog_content = "It's still chaotic, but at least the guests were evacuated safely.",
  ui_story_5046_50460202_8_dialog_content = "But could you please explain to me how PlayerName was taken hostage by the Dark Slayer?",
  ui_story_5046_50460202_9_dialog_content = "Sorry, we failed to carry out our duty.",
  ui_story_5046_50460202_10_dialog_content = "No, it's my fault that PlayerName was abducted...",
  ui_story_5046_50460202_11_dialog_content = "We've identified the suspect, Miss Bethel.",
  ui_story_5046_50460202_12_dialog_content = "All right, well done.",
  ui_story_5046_50460202_13_dialog_content = "\"Hati, female, age 18, birthplace unknown.\"",
  ui_story_5046_50460202_14_dialog_content = "\"Had a short stay in the Umbraton Orphanage. The Shadowlord took her in after she caused a fire that burned down the orphanage.\"",
  ui_story_5046_50460202_15_dialog_content = "(Father...? It was Father's idea?)",
  ui_story_5046_50460202_16_dialog_content = "Caused a fire that burned down the orphanage? Sounds like a repeat offender.",
  ui_story_5046_50460202_17_dialog_content = "\"Hati turned 18 two months ago and left the estate after a successful evaluation.\"",
  ui_story_5046_50460202_18_dialog_content = "(It's better to let Father know about this.)",
  ui_story_5046_50460202_19_dialog_content = "How could a known arsonist like that be released...?",
  ui_story_5046_50460202_20_dialog_content = "Anyway, I'll relay this to the Shadowlord and inform every faction in Umbraton to seek PlayerName's whereabouts.",
  ui_story_5046_50460202_21_dialog_content = "But that will make it public...",
  ui_story_5046_50460202_22_dialog_content = "I'm concerned about the backlash on the orphanage when word gets out that a VIP was kidnapped during the rehearsal.",
  ui_story_5046_50460202_23_dialog_content = "But we don't even know if PlayerName is alive right now!",
  ui_story_5046_50460202_24_dialog_content = "Sigh...",
  ui_story_5046_50460202_25_dialog_content = "Miss Bethel, Mr. Hamell.",
  ui_story_5046_50460202_26_dialog_content = "If you're willing to trust me, please keep PlayerName's abduction under wraps for now.",
  ui_story_5046_50460202_27_dialog_content = "If we publicize it, the Dark Slayer might threaten PlayerName's life.",
  ui_story_5046_50460202_28_dialog_content = "I'll locate the Dark Slayer and free PlayerName as soon as possible.",
  ui_story_5046_50460202_29_dialog_content = "...",
  ui_story_5046_50460202_30_dialog_content = "Please forgive me for not having confidence in you.",
  ui_story_5046_50460202_31_dialog_content = "If you cannot trust our abilities...",
  ui_story_5046_50460202_32_dialog_content = "I am willing to vouch for my instructor, Knight Zenas, on the Ivan name.",
  ui_story_5046_50460202_33_dialog_content = "You don't have to do this, my lady...",
  ui_story_5046_50460202_34_dialog_content = "Please give us another chance to make up for our mistake, Miss Bethel.",
  ui_story_5046_50460202_35_dialog_content = "I've heard stories about you.",
  ui_story_5046_50460202_36_dialog_content = "Very impressive to climb your way up from a down-and-out noble family to where you are now.",
  ui_story_5046_50460202_37_dialog_content = "All right, given the Ivans are behind you, I'll trust you for the time being.",
  ui_story_5046_50460202_38_dialog_content = "But be aware that the Shadowlord will hear about this eventually.",
  ui_story_5046_50460202_39_dialog_content = "You have three days.",
  ui_story_5046_50460202_40_dialog_content = "I want PlayerName at the ceremony, unscathed, three days later.",
  ui_story_5046_50460202_41_dialog_content = "If you cannot do that, I'll handle it the Umbraton way.",
  ui_story_5046_50460202_42_dialog_content = "My gratitude.",
  ui_story_5046_50460202_43_dialog_content = "Mine, as well.",
  ui_story_5046_50460202_44_dialog_content = "Okay, that's how we'll deal with PlayerName's abduction for now.",
  ui_story_5046_50460202_45_dialog_content = "In the meantime, we'll need your help to calm the guests down, Mr. Hamell.",
  ui_story_5046_50460202_46_dialog_content = "Of course, of course!",
  ui_story_5046_50460202_47_dialog_content = "This way, Mr. Hamell.",
  ui_story_5046_50460202_48_dialog_content = "Please let me help you track the Dark Slayer, sir.",
  ui_story_5046_50460202_49_dialog_content = "I've spent a lot of effort learning Luminatics and combat skills over the years just so I could protect you one day.",
  ui_story_5046_50460202_50_dialog_content = "Please give me a chance!",
  ui_story_5046_50460202_51_dialog_content = "No.",
  ui_story_5046_50460202_52_dialog_content = "Do you not trust me because of what happened in that fire?",
  ui_story_5046_50460202_53_dialog_content = "It's all my fault. And you had to save me from another fire.",
  ui_story_5046_50460202_54_dialog_content = "Oh, why do I always put you in predicaments...?",
  ui_story_5046_50460202_55_dialog_content = "Stop blaming yourself, my lady.",
  ui_story_5046_50460202_56_dialog_content = "I will always rescue you from the flames, in the past, present, and future.",
  ui_story_5046_50460202_57_dialog_content = "So why...",
  ui_story_5046_50460202_58_dialog_content = "You're capable of discerning vital clues from crime reports and associated documents.",
  ui_story_5046_50460202_59_dialog_content = "So compared to chasing the culprit out in the field, I think investigating the crime scene and probing documents are better suited for you.",
  ui_story_5046_50460202_60_dialog_content = "I would rather not see you forcing yourself to do something you're not good at.",
  ui_story_5046_50460202_61_dialog_content = "I'd call it something I don't often do rather than something I'm not good at...",
  ui_story_5046_50460202_62_dialog_content = "My lady?",
  ui_story_5046_50460202_63_dialog_content = "N-Nothing.",
  ui_story_5046_50460202_64_dialog_content = "So please stay behind and examine the arson site. I'm sure you'll find valuable leads.",
  ui_story_5046_50460202_65_dialog_content = "Okay, got it!",
  ui_story_5046_50460202_66_dialog_content = "I'll leave no stone unturned!",
  ui_story_5046_50460202_67_dialog_content = "Father, that's what happened.",
  ui_story_5046_50460202_68_dialog_content = "What should we do next?",
  ui_story_5046_50460202_69_dialog_content = "Hmm...",
  ui_story_5046_50460202_70_dialog_content = "Not a thing right now.",
  ui_story_5046_50460202_71_dialog_content = "But what about PlayerName...",
  ui_story_5046_50460202_72_dialog_content = "Not to worry, someone will keep tabs on PlayerName.",
  ui_story_5046_50460202_73_dialog_content = "Yes, my lord.",
  ui_story_5046_50460301_1_dialog_content = "<color=#e8d9bb>Firefly Bar in Umbraton</color>",
  ui_story_5046_50460301_2_dialog_content = "You're back.",
  ui_story_5046_50460301_3_dialog_content = "(Where has Dark Slayer taken me?)",
  ui_story_5046_50460301_4_dialog_content = "I thought you went to the rehearsal today? And what's with the stray cat you brought back?",
  ui_story_5046_50460301_5_dialog_content = "(It seems I'm in a bar. I should probably pretend I'm still out and listen to what they say...)",
  ui_story_5046_50460301_6_dialog_content = "It's the cocklebur that sticks to you.",
  ui_story_5046_50460301_7_dialog_content = "Haha, you mean the seed with sharp prickles that get on your clothes like the thistles?",
  ui_story_5046_50460301_8_dialog_content = "Yeah. Mom used to bring them into the house unintentionally, and I always picked them off her.",
  ui_story_5046_50460301_9_dialog_content = "Oh, did you get the thing?",
  ui_story_5046_50460301_10_dialog_content = "No. The cocklebur held me up, and then more people showed up, so I couldn't make a move.",
  ui_story_5046_50460301_11_dialog_content = "The cocklebur seems to be a very important figure. They were concerned.",
  ui_story_5046_50460301_12_dialog_content = "Hey, isn't this the Caelestite?",
  ui_story_5046_50460301_13_dialog_content = "What's that?",
  ui_story_5046_50460301_14_dialog_content = "You don't know about Caelestite? Oh, that's right, I forgot you've only been out in the world for two months.",
  ui_story_5046_50460301_15_dialog_content = "Do Caelestites like to pretend they're asleep?",
  ui_story_5046_50460301_16_dialog_content = "(What? She knows I'm eavesdropping?!)",
  ui_story_5046_50460301_17_dialog_content = "I don't know. No tabloids in Umbraton mentioned that.",
  ui_story_5046_50460301_18_dialog_content = "Hey, get up.",
  ui_story_5046_50460301_19_dialog_content = "(She's shaking me with enough strength to break my bones!)",
  ui_story_5046_50460301_20_dialog_content = "(I'll have to pretend I just woke up.)",
  ui_story_5046_50460301_21_dialog_content = "Ugh...",
  ui_story_5046_50460301_22_dialog_content = "Where am I?",
  ui_story_5046_50460301_23_dialog_content = "Why do you fake like you just woke up? You were peeking around the bar when we came in.",
  ui_story_5046_50460301_24_dialog_content = "Uh, haha, what are you talking about? I obviously just regained my senses.",
  ui_story_5046_50460301_25_dialog_content = "A good person wouldn't lie.",
  ui_story_5046_50460301_26_dialog_content = "All right, let's not frighten PlayerName.",
  ui_story_5046_50460301_27_dialog_content = "How do you know my name?",
  ui_story_5046_50460301_28_dialog_content = "You're popular throughout the land. It's not unusual to know who you are.",
  ui_story_5046_50460301_29_dialog_content = "Well, that's true.",
  ui_story_5046_50460301_30_dialog_content = "Don't be nervous. We have no bad intentions.",
  ui_story_5046_50460301_31_dialog_content = "I'm Grimme, the barkeep of this Firefly Bar.",
  ui_story_5046_50460301_32_dialog_content = "She's Hati, currently working for the bar.",
  ui_story_5046_50460301_33_dialog_content = "As for what I am to her... You can call me her guardian.",
  ui_story_5046_50460301_34_dialog_content = "She's been in my care ever since she left the Shadowlord.",
  ui_story_5046_50460301_35_dialog_content = "Don't be fooled by her appearance. She may look twenty-something but is actually just eighteen!",
  ui_story_5046_50460301_36_dialog_content = "And she's only been out in the real world for two months, so her mind is closer to a seven or eight-year-old.",
  ui_story_5046_50460301_37_dialog_content = "I'm not sure why Hati brought you back, but believe me, she's a good kid.",
  ui_story_5046_50460301_38_dialog_content = "You think kidnapping someone is good...?",
  ui_story_5046_50460301_39_dialog_content = "She's just blunt and straightforward but means no harm.",
  ui_story_5046_50460301_40_dialog_content = "Although she is to blame for this, so I'll make her apologize to you.",
  ui_story_5046_50460301_41_dialog_content = "Now why should I apologize to that person?",
  ui_story_5046_50460301_42_dialog_content = "They all treated me like a bad guy, and kept calling me the Dark Slayer...",
  ui_story_5046_50460301_43_dialog_content = "Despite what was said to you, you're wrong to kidnap anybody.",
  ui_story_5046_50460301_44_dialog_content = "You have to apologize when you do something wrong.",
  ui_story_5046_50460301_45_dialog_content = "Tsk...",
  ui_story_5046_50460301_46_dialog_content = "Sorry.",
  ui_story_5046_50460301_47_dialog_content = "(I didn't expect someone so fierce would listen to Grimme...)",
  ui_story_5046_50460301_48_dialog_content = "Sorry, PlayerName.",
  ui_story_5046_50460301_49_dialog_content = "(That sounded sincere, and she actually didn't do me any harm...)",
  ui_story_5046_50460301_50_dialog_content = "S-Sure, given how sincere you are, I forgive you.",
  ui_story_5046_50460301_51_dialog_content = "Then you two shake hands and we start over on a clean slate.",
  ui_story_5046_50460301_52_dialog_content = "...",
  ui_story_5046_50460301_53_dialog_content = "...",
  ui_story_5046_50460301_54_dialog_content = "Haha, you two act alike when you're at odds.",
  ui_story_5046_50460301_55_dialog_content = "Don't lump me in with her...",
  ui_story_5046_50460301_56_dialog_content = "Oh, I heard Caelestites have psychic abilities and can glimpse deep into other's memory.",
  ui_story_5046_50460301_57_dialog_content = "Maybe PlayerName can help you recall what went on with your mother.",
  ui_story_5046_50460301_58_dialog_content = "(Hati seems very gloomy when her mother is mentioned.)",
  ui_story_5046_50460301_59_dialog_content = "Haven't you wanted to know what happened, Hati?",
  ui_story_5046_50460301_60_dialog_content = "You think this guy can help?",
  ui_story_5046_50460301_61_dialog_content = "Are you looking down on me? And why should I do that?",
  ui_story_5046_50460301_62_dialog_content = "Hmm, it seems we have a quandary.",
  ui_story_5046_50460301_63_dialog_content = "How about this, then? If I help you with my powers, you have to take me back.",
  ui_story_5046_50460301_64_dialog_content = "Also, Hati has to turn herself in for all the crimes she's done!",
  ui_story_5046_50460301_65_dialog_content = "That's reasonable. We can go with that.",
  ui_story_5046_50460301_66_dialog_content = "But Hati didn't do all those things, I can attest to that.",
  ui_story_5046_50460301_67_dialog_content = "If you're interested in solving the cases, you can uncover the culprit with Hati.",
  ui_story_5046_50460301_68_dialog_content = "How's that for a bargain for your help?",
  ui_story_5046_50460301_69_dialog_content = "It's a deal!",
  ui_story_5046_50460301_70_dialog_content = "...",
  ui_story_5046_50460301_71_dialog_content = "If you really can recover that memory for me...",
  ui_story_5046_50460301_72_dialog_content = "I don't mind you turning me in for the 200,000 Nightium rewards.",
  ui_story_5046_50460301_73_dialog_content = "Relax, if you didn't do it, I won't trade you for the money.",
  ui_story_5046_50460301_74_dialog_content = "Even though 200,000 is a lot, I'd never do it out of greed.",
  ui_story_5046_50460301_75_dialog_content = "It matters not to me.",
  ui_story_5046_50460301_76_dialog_content = "A-All right, then just help me figure out what to do.",
  ui_story_5046_50460301_77_dialog_content = "You have to be as detailed with the story as you can for me to maximize the result.",
  ui_story_5046_50460301_78_dialog_content = "I want to find my mother.",
  ui_story_5046_50460301_79_dialog_content = "I lived with her when I was little. She was neither good nor bad to me.",
  ui_story_5046_50460301_80_dialog_content = "Until one day, we got separated for unknown reasons.",
  ui_story_5046_50460301_81_dialog_content = "The next thing I knew, I was in the orphanage.",
  ui_story_5046_50460301_82_dialog_content = "So you're saying there's a part missing in your memory.",
  ui_story_5046_50460301_83_dialog_content = "If we can recover it, it's possible to find your mother.",
  ui_story_5046_50460301_84_dialog_content = "That's right.",
  ui_story_5046_50460301_85_dialog_content = "Is that all you got to go on?",
  ui_story_5046_50460301_86_dialog_content = "Yes.",
  ui_story_5046_50460301_87_dialog_content = "Okay. I can understand you don't believe me or my psychic abilities.",
  ui_story_5046_50460301_88_dialog_content = "But I'll try my best to do what I promised.",
  ui_story_5046_50460301_89_dialog_content = "...",
  ui_story_5046_50460301_90_dialog_content = "Sorry, PlayerName, the kid is new to the world and won't open up easily.",
  ui_story_5046_50460301_91_dialog_content = "That's okay. I just hope you'll do what's promised and let me go afterward.",
  ui_story_5046_50460301_92_dialog_content = "Hati, I need you to focus on recalling the last thing you saw before the memory was interrupted.",
  ui_story_5046_50460301_93_dialog_content = "Let me know when you're ready.",
  ui_story_5046_50460301_94_dialog_content = "I'm ready.",
  ui_story_5046_50460301_95_dialog_content = "Take a deep breath, Hati, and relax.",
  ui_story_5046_50460301_96_dialog_content = "Let's begin.",
  ui_story_5046_50460301_97_option_content = "Force Boost!",
  ui_story_5046_50460301_98_dialog_content = "...",
  ui_story_5046_50460301_99_dialog_content = "(Where am I? It looks like an ordinary house.)",
  ui_story_5046_50460301_100_dialog_content = "(Is this where Hati lived?)",
  ui_story_5046_50460301_101_dialog_content = "(PlayerName?)",
  ui_story_5046_50460301_102_dialog_content = "(You can see into my memory.)",
  ui_story_5046_50460301_103_dialog_content = "(Now you believe me?)",
  ui_story_5046_50460301_104_dialog_content = "<color=#e8d9bb>Pitter patter...</color>",
  ui_story_5046_50460301_105_dialog_content = "(I hear footsteps and they're getting closer.)",
  ui_story_5046_50460301_106_dialog_content = "Where did you run off to this time, Hati?",
  ui_story_5046_50460301_107_dialog_content = "(Who's this?)",
  ui_story_5046_50460301_108_dialog_content = "(Mom...)",
  ui_story_5046_50460301_109_dialog_content = "Sigh...",
  ui_story_5046_50460301_110_dialog_content = "It's getting harder and harder to control that child's power, and I'm worried...",
  ui_story_5046_50460301_111_dialog_content = "Not only that, she's starting to yearn for the outside world.",
  ui_story_5046_50460301_112_dialog_content = "But I must never let her out...",
  ui_story_5046_50460301_113_dialog_content = "(Why wouldn't she let Hati out?)",
  ui_story_5046_50460301_114_dialog_content = "(Because she fears my powers, fears my... fire.)",
  ui_story_5046_50460301_115_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5046_50460301_116_dialog_content = "Roar!",
  ui_story_5046_50460301_117_dialog_content = "(Whoa—!)",
  ui_story_5046_50460301_118_dialog_content = "(Is that a dog or a wolf? It's so big!!!)",
  ui_story_5046_50460301_119_dialog_content = "(And somewhat resembling Hati...)",
  ui_story_5046_50460301_120_dialog_content = "(It's my inner demon, the embodiment of the fears and loathing for my own power.)",
  ui_story_5046_50460301_121_dialog_content = "(It's guarding the lost memory and won't let me get close.)",
  ui_story_5046_50460301_122_dialog_content = "(Urgh—! My head hurts!)",
  ui_story_5046_50460301_123_dialog_content = "(What's wrong? You don't look well.)",
  ui_story_5046_50460301_124_dialog_content = "You hate me...? But I am... you...",
  ui_story_5046_50460301_125_dialog_content = "(This doesn't feel right. I should end the session here!)",
  ui_story_5046_50460301_126_dialog_content = "You could see my memory, PlayerName, and even my inner demon...",
  ui_story_5046_50460301_127_dialog_content = "The power of a Caelestite is truly marvelous.",
  ui_story_5046_50460301_128_dialog_content = "We made headways with the Caelestite's psychic abilities, I see.",
  ui_story_5046_50460301_129_dialog_content = "That's wonderful, Hati.",
  ui_story_5046_50460301_130_dialog_content = "Hati got extremely emotional when the inner demon showed up, so I ended the session.",
  ui_story_5046_50460301_131_dialog_content = "We didn't get anything more out of that.",
  ui_story_5046_50460301_132_dialog_content = "The more you know, the easier for you to help me remember, right?",
  ui_story_5046_50460301_133_dialog_content = "Huh?",
  ui_story_5046_50460301_134_dialog_content = "Y-Yeah, that's about right...",
  ui_story_5046_50460301_135_dialog_content = "So if I tell you more, can you use the power again?",
  ui_story_5046_50460301_136_dialog_content = "Yes, I can...",
  ui_story_5046_50460301_137_dialog_content = "But you have to let me go like you promised.",
  ui_story_5046_50460301_138_dialog_content = "Deal.",
  ui_story_5046_50460401_1_dialog_content = "This is the report on the orphanage fire for your perusal, Judge Kristen.",
  ui_story_5046_50460401_2_dialog_content = "Thank you. I'm just an intern right now, so just call me Kristen.",
  ui_story_5046_50460401_3_dialog_content = "The source was flammable fuel, and it was stored in the warehouse along with other leftover construction materials.",
  ui_story_5046_50460401_4_dialog_content = "Everyone was too busy with the ceremony to pay attention to the extra fuel in storage.",
  ui_story_5046_50460401_5_dialog_content = "The fuel is identical to that found on arson sites in the past two months, so the same person should be responsible.",
  ui_story_5046_50460401_6_dialog_content = "Yes, that's a logical conclusion.",
  ui_story_5046_50460401_7_dialog_content = "But there was never a kidnapping in any of the past cases, and the Caelestite was nabbed this time...",
  ui_story_5046_50460401_8_dialog_content = "That doesn't seem to fit the pattern. And what's the suspect's motive?",
  ui_story_5046_50460401_9_dialog_content = "According to eyewitness accounts, the suspect is a demi-human Aurorian named Hati.",
  ui_story_5046_50460401_10_dialog_content = "Hati had been living in the Shadowlord's mansion until two months ago. This is her file.",
  ui_story_5046_50460401_11_dialog_content = "Hmm...",
  ui_story_5046_50460401_12_dialog_content = "\"According to eyewitnesses, Hati released massive Lumina flame on the night of the orphanage fire and caused a huge blaze.\"",
  ui_story_5046_50460401_13_dialog_content = "All current clues point to the demi-human named Hati.",
  ui_story_5046_50460401_14_dialog_content = "And all the arsons happened to occur after she left the Shadowlord's mansion. However, what would be her motive?",
  ui_story_5046_50460401_15_dialog_content = "Oh, and the little girl we just rescued...",
  ui_story_5046_50460401_16_dialog_content = "We put her in the orphanage dormitory under the caretaker's watch.",
  ui_story_5046_50460401_17_dialog_content = "Let me go ask her what happened.",
  ui_story_5046_50460401_18_dialog_content = "Hello, I'm Kristen, a probationary judge from Lumopolis.",
  ui_story_5046_50460401_19_dialog_content = "I would like to ask this child about the fire.",
  ui_story_5046_50460401_20_dialog_content = "A noble lady from Lumopolis, I see. I cannot decline your request, but know that the child finally calmed down only a moment ago.",
  ui_story_5046_50460401_21_dialog_content = "You should make it fast, for I must ask you to leave if the child throws another tantrum.",
  ui_story_5046_50460401_22_dialog_content = "Thanks for the thought. I will get it over with as quickly as possible.",
  ui_story_5046_50460401_23_dialog_content = "Hello, little one.",
  ui_story_5046_50460401_24_dialog_content = "Hey, you're the lady from before!",
  ui_story_5046_50460401_25_dialog_content = "Are the big doggy and the gentle guy who saved me here too?",
  ui_story_5046_50460401_26_dialog_content = "Oh, they're not here. Do you know both of them?",
  ui_story_5046_50460401_27_dialog_content = "No. But the gentle one protected me in the fire so he's a good person!",
  ui_story_5046_50460401_28_dialog_content = "And when a beam fell, the big doggy appeared and saved us!",
  ui_story_5046_50460401_29_dialog_content = "(Hati saved them?)",
  ui_story_5046_50460401_30_dialog_content = "Can you tell me why you were there?",
  ui_story_5046_50460401_31_dialog_content = "Sob...",
  ui_story_5046_50460401_32_dialog_content = "What's going on?",
  ui_story_5046_50460401_33_dialog_content = "Would you like candy, little one?",
  ui_story_5046_50460401_34_dialog_content = "Yes!",
  ui_story_5046_50460401_35_dialog_content = "*Chews* So, I was playing hide-and-seek and hid inside that house.",
  ui_story_5046_50460401_36_dialog_content = "There were a lot of kegs inside and a weird little box.",
  ui_story_5046_50460401_37_dialog_content = "Weird little box?",
  ui_story_5046_50460401_38_dialog_content = "I nudged it accidentally to the ground, and it started burning!",
  ui_story_5046_50460401_39_dialog_content = "I tried to run out, but there was fire all around, it was scary.",
  ui_story_5046_50460401_40_dialog_content = "Boo-hoo... I didn't mean to burn the house down...",
  ui_story_5046_50460401_41_dialog_content = "Waah!",
  ui_story_5046_50460401_42_dialog_content = "The fire was so scary!",
  ui_story_5046_50460401_43_dialog_content = "All right, you made her cry again. Time's up, you have to leave now.",
  ui_story_5046_50460401_44_dialog_content = "Sorry... Now, little one, don't go somewhere unfamiliar next time.",
  ui_story_5046_50460401_45_dialog_content = "Boo-hoo... I got it...",
  ui_story_5046_50460401_46_dialog_content = "<color=#e8d9bb>Firefly Bar in Umbraton</color>",
  ui_story_5046_50460401_47_dialog_content = "Nope, still can't remember...",
  ui_story_5046_50460401_48_dialog_content = "Even with all the detail, your power still can't recover the lost memory for me?",
  ui_story_5046_50460401_49_dialog_content = "I'm sorry that I couldn't help...",
  ui_story_5046_50460401_50_dialog_content = "It's very nice of you not to blame her for kidnapping you and even try to help her with your psychic abilities.",
  ui_story_5046_50460401_51_dialog_content = "There has to be another way!",
  ui_story_5046_50460401_52_dialog_content = "The pendant! Yes, the pendant!",
  ui_story_5046_50460401_53_dialog_content = "The pendant?",
  ui_story_5046_50460401_54_dialog_content = "I kidnapped him to trade with the masked man for the pendant.",
  ui_story_5046_50460401_55_dialog_content = "That pendant is very meaningful to me, just like you are very meaningful to that masked man.",
  ui_story_5046_50460401_56_dialog_content = "It's a fair trade.",
  ui_story_5046_50460401_57_dialog_content = "Trade me for a pendant? How rude of you to propose that!",
  ui_story_5046_50460401_58_dialog_content = "No social knowledge whatsoever!",
  ui_story_5046_50460401_59_dialog_content = "Don't you have anything to say as her guardian, Grimme?",
  ui_story_5046_50460401_60_dialog_content = "It was blunt, but I didn't see anything wrong with what she said.",
  ui_story_5046_50460401_61_dialog_content = "You can go back, and Hati gets what she wants by consummating the trade.",
  ui_story_5046_50460401_62_dialog_content = "Isn't that reasonable?",
  ui_story_5046_50460401_63_dialog_content = "T-That does make sense...",
  ui_story_5046_50460401_64_dialog_content = "Wait a minute, didn't you promise to let me go if I helped?",
  ui_story_5046_50460401_65_dialog_content = "Why am I a bargaining chip now?! You're welching!",
  ui_story_5046_50460401_66_dialog_content = "But Hati didn't get her memory back.",
  ui_story_5046_50460401_67_dialog_content = "The people in Umbraton are all devious, I see.",
  ui_story_5046_50460401_68_dialog_content = "(It doesn't feel good to be treated as a chip, though I'm not hurt otherwise...)",
  ui_story_5046_50460401_69_dialog_content = "(Maybe I can sneak out when they aren't looking, find Bethel and let her know that...)",
  ui_story_5046_50460401_70_dialog_content = "We just need to figure out how to make a deal with the masked man.",
  ui_story_5046_50460401_71_dialog_content = "There are wanted posters of you all over the town, Hati. If you show yourself, you'll be arrested before making it to the negotiation table.",
  ui_story_5046_50460401_72_dialog_content = "Let's do this. You write a message, Hati, and I'll deliver it to the man.",
  ui_story_5046_50460401_73_dialog_content = "Ask him to come alone somewhere outside Umbraton.",
  ui_story_5046_50460401_74_dialog_content = "Okay.",
  ui_story_5046_50460401_75_dialog_content = "Watch the guy closely, Grimme, so there's no escape.",
  ui_story_5046_50460401_76_dialog_content = "Try to run, knock the light out, just like how I dragged the body in.",
  ui_story_5046_50460401_77_dialog_content = "What?",
  ui_story_5046_50460401_78_dialog_content = "Want something to drink? You can go back once the deal's done.",
  ui_story_5046_50460401_79_dialog_content = "Then you won't get a chance to enjoy a round.",
  ui_story_5046_50460401_80_dialog_content = "What's the story with that pendant?",
  ui_story_5046_50460401_81_dialog_content = "Why does Hati want it so badly?",
  ui_story_5046_50460401_82_dialog_content = "Well, I can tell you the story now that Hati isn't around.",
  ui_story_5046_50460401_83_dialog_content = "I remember one day, Hati ran back and told me she saw her mother's pendant on a masked man.",
  ui_story_5046_50460401_84_dialog_content = "Masked man? That must be Captain Zenas. He's the only one wearing a mask.",
  ui_story_5046_50460401_85_dialog_content = "She approached him before, but he seemed very surprised to see her and unwilling to give up the pendant for anything.",
  ui_story_5046_50460401_86_dialog_content = "So she's been plotting to get the pendant from him since then.",
  ui_story_5046_50460401_87_dialog_content = "That constitutes a crime!",
  ui_story_5046_50460401_88_dialog_content = "And why is Hati so certain Zenas' pendant is the one she's looking for?",
  ui_story_5046_50460401_89_dialog_content = "She said it gave her a headache the first time she spotted the pendant on Zenas.",
  ui_story_5046_50460401_90_dialog_content = "She said she remembered very clearly that the pattern matched the one on her mother's exactly.",
  ui_story_5046_50460401_91_dialog_content = "She also said getting that pendant will let her recover even more lost memories.",
  ui_story_5046_50460401_92_dialog_content = "You mean the little pony pattern?",
  ui_story_5046_50460401_93_dialog_content = "I heard every noble family in Lumopolis has their own crest, so do Zenas and Hati's mothers come from the same bloodline?",
  ui_story_5046_50460401_94_dialog_content = "That I don't know.",
  ui_story_5046_50460401_95_dialog_content = "The message is ready.",
  ui_story_5046_50460401_96_dialog_content = "<color=#e8d9bb>Knock-knock, knock, knock-knock</color>",
  ui_story_5046_50460401_97_dialog_content = "Right on time. Come on in.",
  ui_story_5046_50460401_98_dialog_content = "Boss.",
  ui_story_5046_50460401_99_dialog_content = "It's all right, Hati and PlayerName are cool.",
  ui_story_5046_50460401_100_dialog_content = "Nothing with the Umbraton factions so far. The knight from Lumopolis is on the way to the bar with people right now.",
  ui_story_5046_50460401_101_dialog_content = "They should be here any time.",
  ui_story_5046_50460401_102_dialog_content = "Is that so? Perfect timing.",
  ui_story_5046_50460401_103_dialog_content = "Good job. Here's your pay.",
  ui_story_5046_50460401_104_dialog_content = "Thanks, boss!",
  ui_story_5046_50460401_105_dialog_content = "I'll be leaving now.",
  ui_story_5046_50460401_106_dialog_content = "(That kid is Grimme's informant? Who is Grimme, really...?)",
  ui_story_5046_50460401_107_dialog_content = "I'll deliver the message, Hati. You head for the meeting spot.",
  ui_story_5046_50460401_108_dialog_content = "Okay. Let's go, PlayerName.",
  ui_story_5046_50460401_109_dialog_content = "You better come along quietly and don't try to call for help, or...",
  ui_story_5046_50460401_110_dialog_content = "Or you'll knock me out, right?",
  ui_story_5046_50460401_111_dialog_content = "I hope you do what you promised this time—let me go once you have the pendant.",
  ui_story_5046_50460401_112_dialog_content = "The Lumopolis guards are nearby, so be careful when you leave.",
  ui_story_5046_50460401_113_dialog_content = "I'll just knock them out silently.",
  ui_story_5046_50460402_1_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5046_50460402_2_dialog_content = "Welcome. What would you like to drink?",
  ui_story_5046_50460402_3_dialog_content = "Officials from Lumopolis? What brings you into my small Umbraton bar, may I ask?",
  ui_story_5046_50460402_4_dialog_content = "We're not here to chitchat, just asking some questions.",
  ui_story_5046_50460402_5_dialog_content = "Why don't you stick around and have a drink? I'll tell you everything I know.",
  ui_story_5046_50460402_6_dialog_content = "That's not necessary.",
  ui_story_5046_50460402_7_dialog_content = "Witnesses claimed the arsonist at the rehearsal was your friend Hati.",
  ui_story_5046_50460402_8_dialog_content = "Judging from her escape route, we believe she fled to this bar.",
  ui_story_5046_50460402_9_dialog_content = "We hope you'll cooperate with our investigation.",
  ui_story_5046_50460402_10_dialog_content = "I would love to, but I hope you can produce concrete evidence that Hati is the arsonist.",
  ui_story_5046_50460402_11_dialog_content = "Or I can't help you.",
  ui_story_5046_50460402_12_dialog_content = "Then we'll have to search by force.",
  ui_story_5046_50460402_13_dialog_content = "Hati has the Caelestite.",
  ui_story_5046_50460402_14_dialog_content = "!",
  ui_story_5046_50460402_15_dialog_content = "Lumopolis security came to Umbraton only to lose a VIP.",
  ui_story_5046_50460402_16_dialog_content = "Miss Bethel didn't turn to any Umbraton faction but allowed you to investigate covertly.",
  ui_story_5046_50460402_17_dialog_content = "My guess is she didn't want it to get out in public.",
  ui_story_5046_50460402_18_dialog_content = "You don't want me to spread it around, either, do you?",
  ui_story_5046_50460402_19_dialog_content = "Humph, so you know where Hati is? Give her up and you might get something out of both Lumopolis and Umbraton.",
  ui_story_5046_50460402_20_dialog_content = "Yeah, we can talk about that when we're alone.",
  ui_story_5046_50460402_21_dialog_content = "Leave us, all of you.",
  ui_story_5046_50460402_22_dialog_content = "But Captain—",
  ui_story_5046_50460402_23_dialog_content = "Wait for me outside.",
  ui_story_5046_50460402_24_dialog_content = "Yes, sir.",
  ui_story_5046_50460402_25_dialog_content = "There's a reason you made it to where you are today.",
  ui_story_5046_50460402_26_dialog_content = "Now then, this is a message that Hati wanted me to deliver.",
  ui_story_5046_50460402_27_dialog_content = "\"To Masked Man:\"",
  ui_story_5046_50460402_28_dialog_content = "\"Bring the pendant and meet me under the tallest maple tree on the east side of Umbraton before sunset. You're exchanging it for the Caelestite.\"",
  ui_story_5046_50460402_29_dialog_content = "\"Make sure you come alone and do not tell anyone. Don't try any tricks, either.\"",
  ui_story_5046_50460402_30_dialog_content = "\"Hati\"",
  ui_story_5046_50460402_31_dialog_content = "...",
  ui_story_5046_50460402_32_dialog_content = "Can you guarantee that the Caelestite is safe?",
  ui_story_5046_50460402_33_dialog_content = "Rest assured. The Caelestite is completely safe. Plus, the time isn't on your side and it's your only choice.",
  ui_story_5046_50460402_34_dialog_content = "No one threatens me.",
  ui_story_5046_50460402_35_dialog_content = "Take it easy. Stay for a drink next time.",
  ui_story_5046_50460402_36_dialog_content = "...",
  ui_story_5046_50460402_37_dialog_content = "Boss.",
  ui_story_5046_50460402_38_dialog_content = "Watch the bar. I gotta go.",
  ui_story_5046_50460402_39_dialog_content = "Captain!",
  ui_story_5046_50460402_40_dialog_content = "I have to check something out alone.",
  ui_story_5046_50460402_41_dialog_content = "You guys stick around and comb every inch of the place.",
  ui_story_5046_50460402_42_dialog_content = "If you spot the suspect and the Caelestite, bring them back as long as the latter's safety is ensured.",
  ui_story_5046_50460402_43_dialog_content = "Yes, sir!",
  ui_story_5046_50460402_44_dialog_content = "<color=#e8d9bb>Umbraton Archive</color>",
  ui_story_5046_50460402_45_dialog_content = "Everything about the fires in the last two months is here.",
  ui_story_5046_50460402_46_dialog_content = "Thank you. I'll look over them myself.",
  ui_story_5046_50460402_47_dialog_content = "The fires happened too often in the time frame, yet only three died.",
  ui_story_5046_50460402_48_dialog_content = "Andre, male, 36, victim of the first fire, worked part-time and was an alcoholic.",
  ui_story_5046_50460402_49_dialog_content = "Fairmont, male, 42, victim of the second fire, a merchant running a tepid business.",
  ui_story_5046_50460402_50_dialog_content = "Carlotta, female, 31, victim of the third fire, an ordinary laundrywoman.",
  ui_story_5046_50460402_51_dialog_content = "All three once worked in the orphanage. Andre was an accountant, Fairmont a deliveryman, and Carlotta a cleaning lady.",
  ui_story_5046_50460402_52_dialog_content = "And the common denominator they shared with Hati is the orphanage.",
  ui_story_5046_50460402_53_dialog_content = "So, was Hati bullied by them in the orphanage and killed them out of spite?",
  ui_story_5046_50460402_54_dialog_content = "I must dig deeper into the old orphanage personnel.",
  ui_story_5046_50460402_55_dialog_content = "Every one of them scattered after the fire, though. It's virtually impossible to find anyone to talk to.",
  ui_story_5046_50460402_56_dialog_content = "What am I going to do?",
  ui_story_5046_50460402_57_dialog_content = "\"Mr. Hamell has donated to the orphanage for a long time, and regularly organizes charity events to raise funds for the facility...\"",
  ui_story_5046_50460402_58_dialog_content = "Mr. Hamell?!",
  ui_story_5046_50460402_59_dialog_content = "<color=#e8d9bb>Inside the Orphanage</color>",
  ui_story_5046_50460402_60_dialog_content = "Can I take a few minutes of your time, Mr. Hamell?",
  ui_story_5046_50460402_61_dialog_content = "Miss Kristen! You found the Caelestite, right? How wonderful!",
  ui_story_5046_50460402_62_dialog_content = "Still no sign of the Caelestite, unfortunately, but I have some questions about the Dark Slayer I'd like to ask you.",
  ui_story_5046_50460402_63_dialog_content = "That arsonist?",
  ui_story_5046_50460402_64_dialog_content = "Hati is the prime suspect in the case, and she might have set the fires in revenge against workers of the old orphanage with whom she held grudges.",
  ui_story_5046_50460402_65_dialog_content = "You've been funding and running charities for the facility for a long time, so you ought to know the situation well.",
  ui_story_5046_50460402_66_dialog_content = "So I would like to ask your opinion.",
  ui_story_5046_50460402_67_dialog_content = "Well, it's true I've been funding and running charities for the orphanage.",
  ui_story_5046_50460402_68_dialog_content = "But the director and the personnel actually handled the specifics. I just had to show my face at the events.",
  ui_story_5046_50460402_69_dialog_content = "The orphanage would present financial statements regularly to me, but other than that, I don't know anything else.",
  ui_story_5046_50460402_70_dialog_content = "But you're the director of the new orphanage, and you had a close relationship with the old facility.",
  ui_story_5046_50460402_71_dialog_content = "So if the suspect is really targeting old orphanage personnel for revenge, you can be the next target.",
  ui_story_5046_50460402_72_dialog_content = "I hope you can recall more details. That will help us apprehend the suspect.",
  ui_story_5046_50460402_73_dialog_content = "Also, I hope you can take up temporary residence in a location protected by Lumo Guard.",
  ui_story_5046_50460402_74_dialog_content = "The suspect can strike and threaten your life anytime, and the Lumo Guard can keep you safe.",
  ui_story_5046_50460402_75_dialog_content = "Miss Kristen, everything you said is conjecture.",
  ui_story_5046_50460402_76_dialog_content = "You should known, the orphanage used to be the biggest in Umbraton. Too many people had a connection to it.",
  ui_story_5046_50460402_77_dialog_content = "You can ask anybody here and they probably have something to do with the facility.",
  ui_story_5046_50460402_78_dialog_content = "Construction workers, cleaning crew, even street vendors outside the orphanage...",
  ui_story_5046_50460402_79_dialog_content = "Are you telling me the suspect wants to off them too?",
  ui_story_5046_50460402_80_dialog_content = "Uh...",
  ui_story_5046_50460402_81_dialog_content = "The speculation is probably just coincidental.",
  ui_story_5046_50460402_82_dialog_content = "Rather than wasting time on coincidences, perhaps it's best spent chasing down the suspect and making everybody breathe easier.",
  ui_story_5046_50460402_83_dialog_content = "It's getting late. Time for these old bones to turn in.",
  ui_story_5046_50460402_84_dialog_content = "Sorry to bother you. Goodbye.",
  ui_story_5046_50460402_85_dialog_content = "Pardon me for not seeing you out.",
  ui_story_5046_50460402_86_dialog_content = "It's been a long time, old friend.",
  ui_story_5046_50460402_87_dialog_content = "It's you.",
  ui_story_5046_50460402_88_dialog_content = "Not happy to see your old friend?",
  ui_story_5046_50460402_89_dialog_content = "I don't think you're here for me but <color=#FFB400>that thing</color>, right?",
  ui_story_5046_50460501_1_dialog_content = "Mr. Hamell was acting a little suspicious, like he was hiding something.",
  ui_story_5046_50460501_2_dialog_content = "But he was not willing to give up more info.",
  ui_story_5046_50460501_3_dialog_content = "Hati's a suspect, the Caelestite's kidnapping, the fuels and detonator at the rehearsal venue...",
  ui_story_5046_50460501_4_dialog_content = "The old orphanage fire, Mr. Hamell's reluctance...",
  ui_story_5046_50460501_5_dialog_content = "Can it all be just one big coincidence?",
  ui_story_5046_50460501_6_dialog_content = "Sigh... I'm at wit's end.",
  ui_story_5046_50460501_7_dialog_content = "If only Mr. Zenas is here. He's certain to—",
  ui_story_5046_50460501_8_dialog_content = "Are you looking for me, my lady?",
  ui_story_5046_50460501_9_dialog_content = "Sir?!",
  ui_story_5046_50460501_10_dialog_content = "How long have you been here?",
  ui_story_5046_50460501_11_dialog_content = "A while. I saw you mumbling to yourself like you were in deep thought so I decided not to interrupt.",
  ui_story_5046_50460501_12_dialog_content = "Sorry, I didn't notice...",
  ui_story_5046_50460501_13_dialog_content = "Oh, I made a big discovery in the case, sir!",
  ui_story_5046_50460501_14_dialog_content = "Really? What did you find?",
  ui_story_5046_50460501_15_dialog_content = "The little girl we saved at the rehearsal said the fire started because she accidentally bumped a box.",
  ui_story_5046_50460501_16_dialog_content = "I'm guessing the box is a detonator set to ignite the fuel kegs stockpiled in the storage at a specific time.",
  ui_story_5046_50460501_17_dialog_content = "Whoever set it up certainly didn't count on the little girl to mess up the plan.",
  ui_story_5046_50460501_18_dialog_content = "Timed ignition... What for, though?",
  ui_story_5046_50460501_19_dialog_content = "Based on previous investigations, there were only three fires in the last two months with casualties.",
  ui_story_5046_50460501_20_dialog_content = "And all three deceased once worked for the old orphanage.",
  ui_story_5046_50460501_21_dialog_content = "Hati, who showed up at the scene today, stayed in that facility for a month.",
  ui_story_5046_50460501_22_dialog_content = "I believe something must have happened to her at the orphanage to make her hate the victims.",
  ui_story_5046_50460501_23_dialog_content = "After losing control of her power and burning down the orphanage, she was taken in by the Shadowlord to a mansion, so she was forced to abandon her revenge plan.",
  ui_story_5046_50460501_24_dialog_content = "Until she was released two months ago, prompting Hati to immediately go after them.",
  ui_story_5046_50460501_25_dialog_content = "Mr. Hamell has been a long-time funder of the orphanage and also showed up on site today.",
  ui_story_5046_50460501_26_dialog_content = "So you're thinking Hati is targeting Mr. Hamell.",
  ui_story_5046_50460501_27_dialog_content = "Yes, but it's only a theory without anything solid to back it up.",
  ui_story_5046_50460501_28_dialog_content = "So you went to see Mr. Hamell in hopes that he would cooperate.",
  ui_story_5046_50460501_29_dialog_content = "Yeah...",
  ui_story_5046_50460501_30_dialog_content = "Mr. Hamell dismissed my theory as a coincidence, but I got the feeling he was hiding something from me.",
  ui_story_5046_50460501_31_dialog_content = "Your body is always one step ahead of your mind, my lady.",
  ui_story_5046_50460501_32_dialog_content = "What do you mean by that, sir?",
  ui_story_5046_50460501_33_dialog_content = "Everyone who could achieve wealth and fame in a mixed bag like Umbraton has their own secrets.",
  ui_story_5046_50460501_34_dialog_content = "And those secrets are their lifelines that they wouldn't want anyone else to know, especially those from Lumopolis.",
  ui_story_5046_50460501_35_dialog_content = "I can understand how you want to protect Mr. Hamell, my lady, but you're only alarming the suspect.",
  ui_story_5046_50460501_36_dialog_content = "Mr. Hamell would never cooperate or accept your protection, and the suspect will likely notice what you have done and burrow deeper into hiding.",
  ui_story_5046_50460501_37_dialog_content = "It's a lack of foresight on my part... Sorry, sir.",
  ui_story_5046_50460501_38_dialog_content = "It turns out I'm no help to you at all...",
  ui_story_5046_50460501_39_dialog_content = "But I don't think your theory is baseless. It's not all coincidence.",
  ui_story_5046_50460501_40_dialog_content = "You approve my theory, then, sir?",
  ui_story_5046_50460501_41_dialog_content = "Of course. Having witnessed your development over all these years, I know better than anyone what you're capable of.",
  ui_story_5046_50460501_42_dialog_content = "You're the best at pulling clues out of records and weaving them into one comprehensive body of proof, my lady.",
  ui_story_5046_50460501_43_dialog_content = "S-Sir...",
  ui_story_5046_50460501_44_dialog_content = "It's because you're such a great instructor!",
  ui_story_5046_50460501_45_dialog_content = "...",
  ui_story_5046_50460501_46_dialog_content = "Ahem. Weren't you looking into the suspect and the Caelestite's whereabouts, sir?",
  ui_story_5046_50460501_47_dialog_content = "Yes. It led me to the Firefly Bar, whose owner is a friend of Hati.",
  ui_story_5046_50460501_48_dialog_content = "But they were tight-lipped, so I couldn't get anything. I have people staking out the bar, so hopefully we'll get something.",
  ui_story_5046_50460501_49_dialog_content = "Ow...",
  ui_story_5046_50460501_50_dialog_content = "What's wrong, sir? Is the burn hurting you?",
  ui_story_5046_50460501_51_dialog_content = "It's all my fault that you were hurt...",
  ui_story_5046_50460501_52_dialog_content = "I'm okay. The minor wound isn't going to bother me.",
  ui_story_5046_50460501_53_dialog_content = "Since you believe Mr. Hamell is Hati's next target, I must return and make plans...",
  ui_story_5046_50460501_54_dialog_content = "We're running out of time...",
  ui_story_5046_50460501_55_dialog_content = "Ugh!",
  ui_story_5046_50460501_56_dialog_content = "Please stop overexerting yourself, sir!",
  ui_story_5046_50460501_57_dialog_content = "When we met the first time, you charged into a fire to save me despite your injuries.",
  ui_story_5046_50460501_58_dialog_content = "And today, you shielded me when I rushed recklessly into the fire.",
  ui_story_5046_50460501_59_dialog_content = "It's time I do something for you!",
  ui_story_5046_50460501_60_dialog_content = "My lady...",
  ui_story_5046_50460501_61_dialog_content = "Please stop calling me that.",
  ui_story_5046_50460501_62_dialog_content = "I don't want to keep being a flower pampered by you, sir.",
  ui_story_5046_50460501_63_dialog_content = "I want to be a judge who brings justice to Lumopolis and someone who's as dependable as you, sir.",
  ui_story_5046_50460501_64_dialog_content = "I-I know I still have a long way to go, but I won't go anywhere if I don't take the first step.",
  ui_story_5046_50460501_65_dialog_content = "Even if it's just a small step, I must still take it.",
  ui_story_5046_50460501_66_dialog_content = "So, so please allow me to ensure Mr. Hamell's safety!",
  ui_story_5046_50460501_67_dialog_content = "Heh...",
  ui_story_5046_50460501_68_dialog_content = "My lady...",
  ui_story_5046_50460501_69_dialog_content = "I mean, Kristen.",
  ui_story_5046_50460501_70_dialog_content = "That's a touching sentiment, and I am deeply moved by the determination.",
  ui_story_5046_50460501_71_dialog_content = "(Wait, why is he leaning closer...?)",
  ui_story_5046_50460501_72_dialog_content = "(I can feel his breath...)",
  ui_story_5046_50460501_73_dialog_content = "(His hair is making my face itch...)",
  ui_story_5046_50460501_74_dialog_content = "And I can also feel fully the affection you hold toward me...",
  ui_story_5046_50460501_75_dialog_content = "(Affection? What's he talking about?)",
  ui_story_5046_50460501_76_dialog_content = "(No, don't tell me!)",
  ui_story_5046_50460501_77_dialog_content = "Kristen, I...",
  ui_story_5046_50460501_78_dialog_content = "S-Sir!",
  ui_story_5046_50460501_79_dialog_content = "I should be on my way to Mr. Hamell's!",
  ui_story_5046_50460501_80_dialog_content = "I'll strive to fulfill this mission!",
  ui_story_5046_50460501_81_dialog_content = "Heheh...",
  ui_story_5046_50460501_82_dialog_content = "I believe with your intelligence and courage, you'll meet the challenge with flying colors.",
  ui_story_5046_50460501_83_dialog_content = "Thank you, sir!",
  ui_story_5046_50460501_84_dialog_content = "I shall not let you down and complete the mission!",
  ui_story_5046_50460501_85_dialog_content = "<color=#e8d9bb>Rural Umbraton</color>",
  ui_story_5046_50460501_86_dialog_content = "That's the tallest maple tree in the woods.",
  ui_story_5046_50460501_87_dialog_content = "Are we there now?",
  ui_story_5046_50460501_88_dialog_content = "The trails are bumpy in the woods, so watch out—",
  ui_story_5046_50460501_89_dialog_content = "Ouch!",
  ui_story_5046_50460501_90_dialog_content = "—or you'll trip.",
  ui_story_5046_50460501_91_dialog_content = "That hurts!",
  ui_story_5046_50460501_92_dialog_content = "Sit down.",
  ui_story_5046_50460501_93_dialog_content = "It's not serious. I'll be fine.",
  ui_story_5046_50460501_94_dialog_content = "Sit down, you.",
  ui_story_5046_50460501_95_dialog_content = "(How intimidating... I can't fight it at all...)",
  ui_story_5046_50460501_96_dialog_content = "All right, I'll just sit for a while.",
  ui_story_5046_50460501_97_dialog_content = "Roll up your pant legs.",
  ui_story_5046_50460501_98_dialog_content = "What for?",
  ui_story_5046_50460501_99_dialog_content = "I'll make it hurt less.",
  ui_story_5046_50460501_100_dialog_content = "Well, it isn't hurting that badly... Whoa, you don't have to roll it up for me, I can do it myself!",
  ui_story_5046_50460501_101_dialog_content = "I-Is this good enough?",
  ui_story_5046_50460501_102_dialog_content = "Yeah, should be here. Does this hurt when I press it?",
  ui_story_5046_50460501_103_dialog_content = "It's okay, but your hand is hot! Even though it's pretty chilly in the woods.",
  ui_story_5046_50460501_104_dialog_content = "My body runs warmer than the average Aurorian. Come closer if you're feeling cold.",
  ui_story_5046_50460501_105_dialog_content = "(Hati might seem unapproachable, but her fluffy ears would perk up when she crouches.)",
  ui_story_5046_50460501_106_dialog_content = "(And she's actually pretty nice, reminding me to be careful walking here and massaging my sprained ankle...)",
  ui_story_5046_50460501_107_dialog_content = "What's wrong?",
  ui_story_5046_50460501_108_dialog_content = "Nothing, not a thing!",
  ui_story_5046_50460501_109_dialog_content = "We still got time. Why don't we take a break here?",
  ui_story_5046_50460501_110_dialog_content = "Okay.",
  ui_story_5046_50460501_111_dialog_content = "...",
  ui_story_5046_50460501_112_dialog_content = "...",
  ui_story_5046_50460501_113_dialog_content = "(This is awkward. I should say something...)",
  ui_story_5046_50460501_114_dialog_content = "Can you tell me about your mother?",
  ui_story_5046_50460501_115_dialog_content = "I-I didn't mean anything ill by that!",
  ui_story_5046_50460501_116_dialog_content = "My mother left me soon after I was born. I didn't even get to see what she looked like...",
  ui_story_5046_50460501_117_dialog_content = "...",
  ui_story_5046_50460501_118_dialog_content = "I guess you don't feel like telling me, t-that's okay.",
  ui_story_5046_50460501_119_dialog_content = "...",
  ui_story_5046_50460501_120_dialog_content = "Frankly, I understand how much you want to recover those memories.",
  ui_story_5046_50460501_121_dialog_content = "...",
  ui_story_5046_50460501_122_dialog_content = "Soroz is the one that raised me for all these years.",
  ui_story_5046_50460501_123_dialog_content = "It's not just a Colossus but my pal and teacher too.",
  ui_story_5046_50460501_124_dialog_content = "We've been inseparable for many years. It would teach me about the world outside and chat when I was bored.",
  ui_story_5046_50460501_125_dialog_content = "Too bad it doesn't remember me now.",
  ui_story_5046_50460501_126_dialog_content = "It lost its memory too?",
  ui_story_5046_50460501_127_dialog_content = "It lost all memories to save my life, so I'm working on finding a way to restore it.",
  ui_story_5046_50460501_128_dialog_content = "Grimme was right, we do have something in common.",
  ui_story_5046_50460501_129_dialog_content = "And that's we're both working hard to get memories back.",
  ui_story_5046_50460501_130_dialog_content = "So I understand how you feel, and I hope you can recall the events with your mother.",
  ui_story_5046_50460501_131_dialog_content = "...",
  ui_story_5046_50460501_132_dialog_content = "Feel free to let me know if there's anything I can help with Soroz's memory.",
  ui_story_5046_50460501_133_dialog_content = "Before you can help, you gotta clear your suspect status!",
  ui_story_5046_50460501_134_dialog_content = "Promise me you'll come clean after we get the pendant, okay?",
  ui_story_5046_50460501_135_dialog_content = "Tsk... How troublesome.",
  ui_story_5046_50460501_136_dialog_content = "Yes, but you still gotta do it!",
  ui_story_5046_50460501_137_dialog_content = "Fine.",
  ui_story_5046_50460501_138_dialog_content = "You promise!",
  ui_story_5046_50460501_139_dialog_content = "Graah—!",
  ui_story_5046_50460501_140_dialog_content = "We got Eclipsites coming, and lots of them...",
  ui_story_5046_50460501_141_dialog_content = "Gaaaaaah!!!",
  ui_story_5046_50460501_142_dialog_content = "Watch out.",
  ui_story_5046_50460501_143_dialog_content = "Come on, PlayerName, why are you so weak?",
  ui_story_5046_50460501_144_dialog_content = "Caelestites were never known for fighting!",
  ui_story_5046_50460501_145_dialog_content = "Powerless.",
  ui_story_5046_50460501_146_dialog_content = "Don't look down on me. Eclipsites are coming on your left!",
  ui_story_5046_50460501_147_dialog_content = "Graah—!",
  ui_story_5046_50460501_148_dialog_content = "Eat my axe!",
  ui_story_5046_50460501_149_dialog_content = "How's that? I might not be able to fight, but my ability to coordinate has the seal of approval from Carleen!",
  ui_story_5046_50460501_150_dialog_content = "Then hide behind me and coordinate!",
  ui_story_5046_50460502_1_dialog_content = "This is bad, how could there be so many Eclipsites here...",
  ui_story_5046_50460502_2_dialog_content = "Gasp... gasp...",
  ui_story_5046_50460502_3_dialog_content = "This is not the place or time for me to go down...",
  ui_story_5046_50460502_4_dialog_content = "Graah...",
  ui_story_5046_50460502_5_dialog_content = "More Eclipsites are coming!",
  ui_story_5046_50460502_6_dialog_content = "Curses! Must I do that...",
  ui_story_5046_50460502_7_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5046_50460502_8_dialog_content = "Graah—!",
  ui_story_5046_50460502_9_dialog_content = "Whoa, the Eclipsites... They're all burned to a crisp!",
  ui_story_5046_50460502_10_dialog_content = "I don't sense any more Eclipsites around.",
  ui_story_5046_50460502_11_dialog_content = "Huff... huff...",
  ui_story_5046_50460502_12_dialog_content = "Urgh!",
  ui_story_5046_50460502_13_dialog_content = "You used the power...",
  ui_story_5046_50460502_14_dialog_content = "Tsk, tsk...",
  ui_story_5046_50460502_15_dialog_content = "You... You have turned into what you hated...",
  ui_story_5046_50460502_16_dialog_content = "This is how... mother... left us...",
  ui_story_5046_50460502_17_dialog_content = "Shut up! I say shut your mouth!",
  ui_story_5046_50460502_18_dialog_content = "What's wrong, Hati?!",
  ui_story_5046_50460502_19_dialog_content = "(Hati is rolling on the ground in agony with her eyes closed.)",
  ui_story_5046_50460502_20_dialog_content = "I say, shut up!",
  ui_story_5046_50460502_21_dialog_content = "Mom... I'm not a naughty kid... I'm not...",
  ui_story_5046_50460502_22_dialog_content = "Mom? Is she immersed in past memories?",
  ui_story_5046_50460502_23_dialog_content = "This isn't going to be good. I have to use my psychic ability to free her.",
  ui_story_5046_50460502_24_dialog_content = "Sorry, Hati, but I don't mean to pry into your mind.",
  ui_story_5046_50460502_25_option_content = "Force Boost!",
  ui_story_5046_50460502_26_dialog_content = "(Where am I?)",
  ui_story_5046_50460502_27_dialog_content = "Mom, you got cocklebur on you! Let me get them off.",
  ui_story_5046_50460502_28_dialog_content = "Thank you, Hati.",
  ui_story_5046_50460502_29_dialog_content = "You're such a good girl.",
  ui_story_5046_50460502_30_dialog_content = "Hehe...",
  ui_story_5046_50460502_31_dialog_content = "It's not often you take me out to play, Mom.",
  ui_story_5046_50460502_32_dialog_content = "(Young Hati? And her mother too.)",
  ui_story_5046_50460502_33_dialog_content = "...",
  ui_story_5046_50460502_34_dialog_content = "Sorry, Hati.",
  ui_story_5046_50460502_35_dialog_content = "Why are you apologizing, Mom? You didn't do anything wrong.",
  ui_story_5046_50460502_36_dialog_content = "Well, it's my fault.",
  ui_story_5046_50460502_37_dialog_content = "No, you didn't do anything wrong...",
  ui_story_5046_50460502_38_dialog_content = "You should be playing outside like any other kids, but—",
  ui_story_5046_50460502_39_dialog_content = "Am I right in doing this, Fenrir...?",
  ui_story_5046_50460502_40_dialog_content = "Are you crying because of me, Mom?",
  ui_story_5046_50460502_41_dialog_content = "Then I won't come outside anymore.",
  ui_story_5046_50460502_42_dialog_content = "It's okay, I'm fine... Come, let's play!",
  ui_story_5046_50460502_43_dialog_content = "I'll close my eyes, count to three and come to find you!",
  ui_story_5046_50460502_44_dialog_content = "Okay!",
  ui_story_5046_50460502_45_dialog_content = "Three...",
  ui_story_5046_50460502_46_dialog_content = "Graah...",
  ui_story_5046_50460502_47_dialog_content = "Something black is approaching Mom...",
  ui_story_5046_50460502_48_dialog_content = "Two...",
  ui_story_5046_50460502_49_dialog_content = "The black thing looks like it's going to hurt her...",
  ui_story_5046_50460502_50_dialog_content = "One...",
  ui_story_5046_50460502_51_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5046_50460502_52_dialog_content = "!!!",
  ui_story_5046_50460502_53_dialog_content = "Hati?!",
  ui_story_5046_50460502_54_dialog_content = "Mom, this critter is very bad!",
  ui_story_5046_50460502_55_dialog_content = "I will burn it into a fireball!",
  ui_story_5046_50460502_56_dialog_content = "Hah!",
  ui_story_5046_50460502_57_dialog_content = "Why you—didn't I tell you not to use fire?!",
  ui_story_5046_50460502_58_dialog_content = "Why don't you listen?",
  ui_story_5046_50460502_59_dialog_content = "But Mom...",
  ui_story_5046_50460502_60_dialog_content = "Go home with me now!",
  ui_story_5046_50460502_61_dialog_content = "Boo-hoo... Why...",
  ui_story_5046_50460502_62_dialog_content = "Does Mom hate me... when I play with fire...?",
  ui_story_5046_50460502_63_dialog_content = "(Mom doesn't like Hati... Doesn't like fire...)",
  ui_story_5046_50460502_64_dialog_content = "(Hati is a naughty kid...)",
  ui_story_5046_50460502_65_dialog_content = "(Naughty kid...)",
  ui_story_5046_50460502_66_dialog_content = "(Hati is... a naughty kid?)",
  ui_story_5046_50460502_67_dialog_content = "(No, Hati is not a naughty kid!)",
  ui_story_5046_50460502_68_dialog_content = "(Using power Mom didn't approve to save loved ones...)",
  ui_story_5046_50460502_69_dialog_content = "(That doesn't mean Hati is a naughty kid!)",
  ui_story_5046_50460502_70_dialog_content = "(Hati is not a naughty kid...?)",
  ui_story_5046_50460502_71_dialog_content = "(Your mom must have had an unspoken reason to be mean to Hati...)",
  ui_story_5046_50460502_72_dialog_content = "(And the young you looked super cool using fire to protect your mom!)",
  ui_story_5046_50460502_73_dialog_content = "(Just like the cool Hati who used fire to protect me!)",
  ui_story_5046_50460502_74_dialog_content = "(Hati is a great, awesome kid!)",
  ui_story_5046_50460502_75_dialog_content = "(Hati is an awesome kid?)",
  ui_story_5046_50460502_76_dialog_content = "(That's right, Hati is an awesome kid! Now be calm and wake up slowly...)",
  ui_story_5046_50460502_77_dialog_content = "...",
  ui_story_5046_50460502_78_dialog_content = "PlayerName?",
  ui_story_5046_50460502_79_dialog_content = "It's me. Feeling okay, right?",
  ui_story_5046_50460502_80_dialog_content = "Yeah...",
  ui_story_5046_50460502_81_dialog_content = "Sorry to make trouble for you.",
  ui_story_5046_50460502_82_dialog_content = "No, I should be apologizing.",
  ui_story_5046_50460502_83_dialog_content = "I slipped into your memory without your permission...",
  ui_story_5046_50460502_84_dialog_content = "Hope you're not mad at me for that!",
  ui_story_5046_50460502_85_dialog_content = "If it wasn't for you...",
  ui_story_5046_50460502_86_dialog_content = "I probably would've gone insane.",
  ui_story_5046_50460502_87_dialog_content = "So thank you.",
  ui_story_5046_50460502_88_dialog_content = "Okay, I'm not used to you getting this demure all of a sudden.",
  ui_story_5046_50460502_89_dialog_content = "Ahem, it's almost time. We have to get to that tree.",
  ui_story_5046_50460502_90_dialog_content = "If you still need me to recover memories for you after this is all over...",
  ui_story_5046_50460502_91_dialog_content = "Just come see me at the Colossus.",
  ui_story_5046_50460502_92_dialog_content = "Sure.",
  ui_story_5046_50460502_93_dialog_content = "Also, remember that you promised to explain everything and clear yourself...",
  ui_story_5046_50460502_94_dialog_content = "Otherwise, you'll get turned in for a reward before you can even see me.",
  ui_story_5046_50460502_95_dialog_content = "I promise.",
  ui_story_5046_50460502_96_dialog_content = "You do?",
  ui_story_5046_50460502_97_dialog_content = "I do.",
  ui_story_5046_50460601_1_dialog_content = "(A squad of Lumopolis guards arrived at the orphanage this morning but Mr. Hamell didn't send them away.)",
  ui_story_5046_50460601_2_dialog_content = "(And he even led them out of Umbraton and into this forest...)",
  ui_story_5046_50460601_3_dialog_content = "(Now both the Caelestite and Hati are here, and the two sides clash.)",
  ui_story_5046_50460601_4_dialog_content = "(These guards aren't fighting in Lumopolis style, yet they wore Lumo Guard uniforms.)",
  ui_story_5046_50460601_5_dialog_content = "(What's going on here...?)",
  ui_story_5046_50460601_6_dialog_content = "(It's futile to stop them right now, so I should just watch from here for the time being.)",
  ui_story_5046_50460601_7_dialog_content = "Huff... huff... Even that couldn't kill you.",
  ui_story_5046_50460601_8_dialog_content = "Mr. Hamell? What are you saying? And what are you doing here?",
  ui_story_5046_50460601_9_dialog_content = "Where's Mr. Zenas? Didn't the message make it to him?",
  ui_story_5046_50460601_10_dialog_content = "Rather than waiting for you to come to kill me, I prefer a pre-emptive strike.",
  ui_story_5046_50460601_11_dialog_content = "Didn't you kill Andre, Fairmont, and Carlotta?",
  ui_story_5046_50460601_12_dialog_content = "You hold a grudge for what happened to you in the orphanage and want revenge against us?",
  ui_story_5046_50460601_13_dialog_content = "You wanted to kill us both in one swoop at the rehearsal, right?",
  ui_story_5046_50460601_14_dialog_content = "Too bad that plan failed.",
  ui_story_5046_50460601_15_dialog_content = "I have no idea who those people are, and I was just passing by the rehearsal.",
  ui_story_5046_50460601_16_dialog_content = "Quit playing dumb! You'd like nothing more than for me and—Argh!",
  ui_story_5046_50460601_17_dialog_content = "Look out!",
  ui_story_5046_50460601_18_dialog_content = "(Mr. Hamell is down! Did Hati kill him?)",
  ui_story_5046_50460601_19_dialog_content = "Hang in there, Mr. Hamell!",
  ui_story_5046_50460601_20_dialog_content = "He's dead.",
  ui_story_5046_50460601_21_dialog_content = "Hati Kelp, you're a murder suspect. I demand that you come with me to Umbraton for further investigation!",
  ui_story_5046_50460601_22_dialog_content = "Miss Kristen? What are you doing here?",
  ui_story_5046_50460601_23_dialog_content = "I didn't kill him.",
  ui_story_5046_50460601_24_dialog_content = "Of course, you would say that.",
  ui_story_5046_50460601_25_dialog_content = "I can attest to Hati's innocence. Mr. Hamell fell untouched.",
  ui_story_5046_50460601_26_dialog_content = "Why are you harboring a murderer, PlayerName?",
  ui_story_5046_50460601_27_dialog_content = "She's still holding a lethal weapon in her hand...",
  ui_story_5046_50460601_28_dialog_content = "I'm telling the truth!",
  ui_story_5046_50460601_29_dialog_content = "Since you want to defend yourselves, why don't you come to the Hall of Justice with me?",
  ui_story_5046_50460601_30_dialog_content = "Even though I'm just a probationary judge, I must see that justice is served and no crime goes unpunished.",
  ui_story_5046_50460601_31_dialog_content = "No way, I can't go with you yet.",
  ui_story_5046_50460601_32_dialog_content = "Resisting arrest is only going to make things worse.",
  ui_story_5046_50460601_33_dialog_content = "Yeah, whatever.",
  ui_story_5046_50460601_34_dialog_content = "Please cool it, both of you!",
  ui_story_5046_50460601_35_dialog_content = "Kristen! Are you okay?",
  ui_story_5046_50460601_36_dialog_content = "You're late, masked man.",
  ui_story_5046_50460601_37_dialog_content = "Is this Mr. Hamell?",
  ui_story_5046_50460601_38_dialog_content = "Hati? You killed Mr. Hamell, didn't you? Arrest her at once, Kristen.",
  ui_story_5046_50460601_39_dialog_content = "Wait a minute! Hati didn't do any of it!",
  ui_story_5046_50460601_40_dialog_content = "You wanna fight? Not problem with me!",
  ui_story_5046_50460601_41_dialog_content = "It's dangerous over there, PlayerName, come here!",
  ui_story_5046_50460601_42_dialog_content = "Take this!",
  ui_story_5046_50460601_43_dialog_content = "You're too slow.",
  ui_story_5046_50460601_44_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5046_50460601_45_dialog_content = "My mask...",
  ui_story_5046_50460601_46_dialog_content = "The face...!",
  ui_story_5046_50460601_47_dialog_content = "Who is he? Who is he?!",
  ui_story_5046_50460601_48_dialog_content = "What's wrong, Hati?",
  ui_story_5046_50460601_49_dialog_content = "I... uh... oh...!",
  ui_story_5046_50460601_50_dialog_content = "<color=#e8d9bb>\"That day—\"</color>",
  ui_story_5046_50460601_51_dialog_content = "<color=#e8d9bb>\"I saw this face.\"</color>",
  ui_story_5046_50460601_52_dialog_content = "<color=#e8d9bb>\"That day—\"</color>",
  ui_story_5046_50460601_53_dialog_content = "<color=#e8d9bb>\"What happened... to me... mother?\"</color>",
  ui_story_5046_50460601_54_dialog_content = "Aghhhh!",
  ui_story_5046_50460601_55_dialog_content = "Hati? Hati?!",
  ui_story_5046_50460601_56_dialog_content = "Something's wrong with her, sir.",
  ui_story_5046_50460601_57_dialog_content = "Ahhhhhhh!",
  ui_story_5046_50460601_58_dialog_content = "Hati! Hati! Can you hear me?",
  ui_story_5046_50460601_59_dialog_content = "Snap out of it!",
  ui_story_5046_50460601_60_dialog_content = "Ugh!",
  ui_story_5046_50460601_61_dialog_content = "<color=#e8d9bb>Sizzle—</color>",
  ui_story_5046_50460601_62_dialog_content = "Her look just changed! And she's on fire?!",
  ui_story_5046_50460601_63_dialog_content = "Careful! Back away, Kristen!",
  ui_story_5046_50460601_64_dialog_content = "Awooo!!!",
  ui_story_5046_50460601_65_dialog_content = "Hati!!!",
  ui_story_5046_50460601_66_dialog_content = "(The way she looks now resembles the inner demon I saw in her memory...)",
  ui_story_5046_50460601_67_dialog_content = "(Has it taken her over? No way, I have to snap her out of it!)",
  ui_story_5046_50460601_68_dialog_content = "Come over here, PlayerName! Hati is a dangerous threat right now!",
  ui_story_5046_50460601_69_dialog_content = "It's all right, Hati won't hurt me! She needs me now!",
  ui_story_5046_50460601_70_dialog_content = "You must calm down, Hati!",
  ui_story_5046_50460601_71_dialog_content = "Awooo!",
  ui_story_5046_50460601_72_dialog_content = "Stop wasting your time, she's not listening!",
  ui_story_5046_50460601_73_dialog_content = "Come over here quickly, PlayerName!",
  ui_story_5046_50460601_74_dialog_content = "PlayerName...",
  ui_story_5046_50460601_75_dialog_content = "Hati is calling my name!",
  ui_story_5046_50460601_76_dialog_content = "No, I can't just leave her alone!",
  ui_story_5046_50460601_77_dialog_content = "(Is there a way for her to hear me...)",
  ui_story_5046_50460601_78_dialog_content = "(I got it, I can do this...)",
  ui_story_5046_50460601_79_option_content = "Force Boost!",
  ui_story_5046_50460601_80_dialog_content = "(Calm down, Hati!)",
  ui_story_5046_50460601_81_dialog_content = "(PlayerName? I... I just couldn't control myself... when I saw that man's face...)",
  ui_story_5046_50460601_82_dialog_content = "(My head started hurting so bad. Urgh—)",
  ui_story_5046_50460601_83_dialog_content = "(What am I going to do...?)",
  ui_story_5046_50460601_84_dialog_content = "(Regardless, we gotta get out of here and find a quiet place for you to relax.)",
  ui_story_5046_50460601_85_dialog_content = "(We go together...?)",
  ui_story_5046_50460601_86_dialog_content = "(Together!)",
  ui_story_5046_50460601_87_dialog_content = "Don't let them get away! Ugh!",
  ui_story_5046_50460601_88_dialog_content = "Stay put, sir, you're injured!",
  ui_story_5046_50460601_89_dialog_content = "Where's the Caelestite?",
  ui_story_5046_50460601_90_dialog_content = "Hati took him with her...",
  ui_story_5046_50460601_91_dialog_content = "Rats, she got away again!",
  ui_story_5046_50460601_92_dialog_content = "Where's my mask?",
  ui_story_5046_50460601_93_dialog_content = "I'll get it for you, just stay put!",
  ui_story_5046_50460601_94_dialog_content = "(The wound on his face...)",
  ui_story_5046_50460601_95_dialog_content = "Oh no, fire!",
  ui_story_5046_50460601_96_dialog_content = "The young miss is still inside!",
  ui_story_5046_50460601_97_dialog_content = "Is someone still in there?",
  ui_story_5046_50460601_98_dialog_content = "Please, sir, I beg you to save Miss Kristen!",
  ui_story_5046_50460601_99_dialog_content = "Cough, cough...",
  ui_story_5046_50460601_100_dialog_content = "Mom... Dad... Where are you...",
  ui_story_5046_50460601_101_dialog_content = "Miss!",
  ui_story_5046_50460601_102_dialog_content = "Who... Who is this...",
  ui_story_5046_50460601_103_dialog_content = "Finally found you. Don't be scared, I'll get you out of this.",
  ui_story_5046_50460601_104_dialog_content = "Are you okay, my lady?",
  ui_story_5046_50460601_105_dialog_content = "I'm fine, thank you—Ah!",
  ui_story_5046_50460601_106_dialog_content = "Oh no! Your face is severely injured! It must be treated immediately!",
  ui_story_5046_50460601_107_dialog_content = "Me? I'm sorry to frighten the young lady.",
  ui_story_5046_50460601_108_dialog_content = "I-I'm sorry. You saved me only for me to...",
  ui_story_5046_50460601_109_dialog_content = "It's okay. I'm glad you're all right.",
  ui_story_5046_50460601_110_dialog_content = "May I ask your name...?",
  ui_story_5046_50460601_111_dialog_content = "Zenas.",
  ui_story_5046_50460601_112_dialog_content = "Starting today, I'm your home tutor, my lady.",
  ui_story_5046_50460601_113_dialog_content = "That's great, sir!",
  ui_story_5046_50460601_114_dialog_content = "I'm grateful for you accepting a lowly noble like me, as well as recommending me to your father.",
  ui_story_5046_50460601_115_dialog_content = "You're a noble, sir?",
  ui_story_5046_50460601_116_dialog_content = "Yes. See, this is my family crest.",
  ui_story_5046_50460601_117_dialog_content = "What a unique pattern.",
  ui_story_5046_50460601_118_dialog_content = "The house has declined and is not worth mentioning anymore.",
  ui_story_5046_50460601_119_dialog_content = "<color=#e8d9bb>\"From then on, he stayed and tutored me.\"</color>",
  ui_story_5046_50460601_120_dialog_content = "<color=#e8d9bb>\"Until he resigned and went to serve Lumopolis in an official capacity.\"</color>",
  ui_story_5046_50460601_121_dialog_content = "<color=#e8d9bb>\"After I graduated from Dawn Academy, I joined the Lumo Hall of Justice and continued following him.\"</color>",
  ui_story_5046_50460601_122_dialog_content = "Your mask, sir.",
  ui_story_5046_50460601_123_dialog_content = "Phew...",
  ui_story_5046_50460601_124_dialog_content = "Hati killed Mr. Hamell and abducted the Caelestite again.",
  ui_story_5046_50460601_125_dialog_content = "We must send guards in pursuit and expand our investigation.",
  ui_story_5046_50460601_126_dialog_content = "Yes, sir!",
  ui_story_5046_50460601_127_dialog_content = "This is where you get off the case, Kristen.",
  ui_story_5046_50460601_128_dialog_content = "What?",
  ui_story_5046_50460601_129_dialog_content = "Considering that the case will only get worse, I don't want to put you in more danger.",
  ui_story_5046_50460601_130_dialog_content = "Also, based on the incident with Hamell, I think you still lack the experience to tangle with the suspect.",
  ui_story_5046_50460601_131_dialog_content = "But no one's more invested in these cases than me except you, sir. Please allow me to keep assisting you!",
  ui_story_5046_50460601_132_dialog_content = "Say no more. I'll handle them myself.",
  ui_story_5046_50460601_133_dialog_content = "Just compile all the findings so far in one file and deliver it to the Hall of Justice.",
  ui_story_5046_50460601_134_dialog_content = "But—",
  ui_story_5046_50460601_135_dialog_content = "Enough! You might be my young lady, but I am your superior.",
  ui_story_5046_50460601_136_dialog_content = "Please follow my order!",
  ui_story_5046_50460601_137_dialog_content = "Yes...",
  ui_story_5046_50460601_138_dialog_content = "I was probably too harsh with my words, but it was out of concern for your safety.",
  ui_story_5046_50460601_139_dialog_content = "You should go back now.",
  ui_story_5046_50460601_140_dialog_content = "My first time sent to follow the suspect and I messed it all up.",
  ui_story_5046_50460601_141_dialog_content = "Even if he wouldn't let me, I'm going to get to the bottom of this.",
  ui_story_5046_50460601_142_dialog_content = "Not to mention I got my doubts about all these cases...",
  ui_story_5046_50460601_143_dialog_content = "If Hati meant to set the fire, why did she save PlayerName and the little girl?",
  ui_story_5046_50460601_144_dialog_content = "Also, why would PlayerName speak up for Hati and help her escape when he's the hostage?",
  ui_story_5046_50460601_145_dialog_content = "Before he died, Hamell mentioned that Hati had another target beside him.",
  ui_story_5046_50460601_146_dialog_content = "Find out who that is and I'll find Hati.",
  ui_story_5046_50460601_147_dialog_content = "Mr. Zenas, I'll prove to you this time that I'm no longer a pampered flower!",
  ui_story_5046_50460601_148_dialog_content = "I'll absolutely be an invaluable help through my own abilities!",
  ui_story_5046_50460701_1_dialog_content = "(Ugh, wet blanket is the worst.)",
  ui_story_5046_50460701_2_dialog_content = "(Is the roof leaking again? That was never the case with the old house.)",
  ui_story_5046_50460701_3_dialog_content = "Mom... Mom?",
  ui_story_5046_50460701_4_dialog_content = "(Is Mom asleep?)",
  ui_story_5046_50460701_5_dialog_content = "(She's been out a lot lately and had to cook and do chores when she got home, so she must be very tired.)",
  ui_story_5046_50460701_6_dialog_content = "(I'm a big girl now and cannot cause problems for Mom!)",
  ui_story_5046_50460701_7_dialog_content = "(I have to dry the blanket myself!)",
  ui_story_5046_50460701_8_dialog_content = "(She'll be very happy when she sees me doing chores after she wakes up!)",
  ui_story_5046_50460701_9_dialog_content = "(She'll call me a nice kid!)",
  ui_story_5046_50460701_10_dialog_content = "<color=#e8d9bb>Flap, flap...</color>",
  ui_story_5046_50460701_11_dialog_content = "(Phew, this ought to do it. How long does Mom usually hang the blanket up?)",
  ui_story_5046_50460701_12_dialog_content = "(If only it's dried before Mom wakes up!)",
  ui_story_5046_50460701_13_dialog_content = "Dry, blankie!",
  ui_story_5046_50460701_14_dialog_content = "Blankie, blankie!",
  ui_story_5046_50460701_15_dialog_content = "Dry now!",
  ui_story_5046_50460701_16_dialog_content = "<color=#e8d9bb>Sizzle—</color>",
  ui_story_5046_50460701_17_dialog_content = "Whoa!",
  ui_story_5046_50460701_18_dialog_content = "Where did the fire come from?!",
  ui_story_5046_50460701_19_dialog_content = "Mom's going to be mad if she sees this!",
  ui_story_5046_50460701_20_dialog_content = "I gotta put the fire out!",
  ui_story_5046_50460701_21_dialog_content = "Hati? What are you doing?!",
  ui_story_5046_50460701_22_dialog_content = "Boo-hoo... Mom!",
  ui_story_5046_50460701_23_dialog_content = "(She seemed very frightened... I gotta apologize now!)",
  ui_story_5046_50460701_24_dialog_content = "Sorry, I just wanted to dry the blanket...",
  ui_story_5046_50460701_25_dialog_content = "I-I didn't mean to set it on fire... it just...",
  ui_story_5046_50460701_26_dialog_content = "Are you hurt?",
  ui_story_5046_50460701_27_dialog_content = "No... I didn't do it on purpose, Mom...",
  ui_story_5046_50460701_28_dialog_content = "And I didn't mean to do anything you didn't want me to do...",
  ui_story_5046_50460701_29_dialog_content = "Okay, remember never to use your power again!",
  ui_story_5046_50460701_30_dialog_content = "Do you hear me!?",
  ui_story_5046_50460701_31_dialog_content = "(Mom is so fierce...)",
  ui_story_5046_50460701_32_dialog_content = "But I was only... I didn't do it on purpose...",
  ui_story_5046_50460701_33_dialog_content = "Wahhhhh—!",
  ui_story_5046_50460701_34_dialog_content = "You still can't control the power right now...",
  ui_story_5046_50460701_35_dialog_content = "And it's very powerful, enough to hurt you if you're careless...",
  ui_story_5046_50460701_36_dialog_content = "There are also people who would want the power and that can get you hurt too...",
  ui_story_5046_50460701_37_dialog_content = "So never use it again, you hear, Hati?",
  ui_story_5046_50460701_38_dialog_content = "Boo-hoo... Got it...",
  ui_story_5046_50460701_39_dialog_content = "(Mom...)",
  ui_story_5046_50460701_40_dialog_content = "<color=#e8d9bb>\"Do you fear my power that much, Mom?\"</color>",
  ui_story_5046_50460701_41_dialog_content = "<color=#e8d9bb>\"Do you fear me that much, Mom?\"</color>",
  ui_story_5046_50460701_42_dialog_content = "<color=#e8d9bb>\"But I love you the most, Mom!\"</color>",
  ui_story_5046_50460701_43_dialog_content = "Aghhhh!",
  ui_story_5046_50460701_44_dialog_content = "(Mom doesn't want Hati anymore...)",
  ui_story_5046_50460701_45_dialog_content = "(Because Hati didn't listen to her...)",
  ui_story_5046_50460701_46_dialog_content = "I... Ugh... Mom... Aghhh!",
  ui_story_5046_50460701_47_dialog_content = "Wake up, Hati!",
  ui_story_5046_50460701_48_dialog_content = "(She appears to be stuck in her memory.)",
  ui_story_5046_50460701_49_dialog_content = "(I can sense her inner demon relentlessly whispering in her ear...)",
  ui_story_5046_50460701_50_dialog_content = "If Hati can't face her inner demon head-on, she'll remain trapped in her memories forever...",
  ui_story_5046_50460701_51_dialog_content = "Leaving her to drift unconsciously in the past like this isn't an option.",
  ui_story_5046_50460701_52_dialog_content = "I have to help her!",
  ui_story_5046_50460701_53_option_content = "Force Boost!",
  ui_story_5046_50460701_54_dialog_content = "(This must be Hati's home.)",
  ui_story_5046_50460701_55_dialog_content = "Hati! What are you doing!?",
  ui_story_5046_50460701_56_dialog_content = "M-Mom?",
  ui_story_5046_50460701_57_dialog_content = "Answer me—what are you doing!?",
  ui_story_5046_50460701_58_dialog_content = "I-I just wanted to see what the children outside are playing.",
  ui_story_5046_50460701_59_dialog_content = "Close the window! Right now!",
  ui_story_5046_50460701_60_dialog_content = "But I want to go out and play too.",
  ui_story_5046_50460701_61_dialog_content = "How many times have I told you? Do you need me to repeat it?",
  ui_story_5046_50460701_62_dialog_content = "Sob...",
  ui_story_5046_50460701_63_dialog_content = "Why won't you let me go out to play!?",
  ui_story_5046_50460701_64_dialog_content = "You always say it's for my own protection!",
  ui_story_5046_50460701_65_dialog_content = "But you never tell me why that is!",
  ui_story_5046_50460701_66_dialog_content = "...",
  ui_story_5046_50460701_67_dialog_content = "This new place we've moved to is so rundown and cold! It's horrible here!",
  ui_story_5046_50460701_68_dialog_content = "Don't you have those picture books? Go and read by yourself.",
  ui_story_5046_50460701_69_dialog_content = "But I've read all of those books so many times already!",
  ui_story_5046_50460701_70_dialog_content = "The children in those books can play together and visit each other...",
  ui_story_5046_50460701_71_dialog_content = "You used those picture books to teach me how to talk to people, buy things, and say thank you...",
  ui_story_5046_50460701_72_dialog_content = "...",
  ui_story_5046_50460701_73_dialog_content = "But I haven't had the chance to use any of it at all!",
  ui_story_5046_50460701_74_dialog_content = "Because you won't let me go out!",
  ui_story_5046_50460701_75_dialog_content = "I taught you all these things because...",
  ui_story_5046_50460701_76_dialog_content = "I hope you'll be able to take care of yourself one day, when I'm not around anymore.",
  ui_story_5046_50460701_77_dialog_content = "Why would you not be around anymore?",
  ui_story_5046_50460701_78_dialog_content = "...",
  ui_story_5046_50460701_79_dialog_content = "Why do you look so sad, Mom?",
  ui_story_5046_50460701_80_dialog_content = "Was someone mean to you?",
  ui_story_5046_50460701_81_dialog_content = "I'm already all grown up!",
  ui_story_5046_50460701_82_dialog_content = "If someone's bullying you, I'll hit them all until they run away!",
  ui_story_5046_50460701_83_dialog_content = "And if I can't hit them all, I'll burn them!",
  ui_story_5046_50460701_84_dialog_content = "!!!",
  ui_story_5046_50460701_85_dialog_content = "<color=#e8d9bb>Slap!</color>",
  ui_story_5046_50460701_86_dialog_content = "M...Mom?",
  ui_story_5046_50460701_87_dialog_content = "Didn't I tell you that you can't do that!?",
  ui_story_5046_50460701_88_dialog_content = "Mom... you hit me...",
  ui_story_5046_50460701_89_dialog_content = "Tell me! Why can't I!?",
  ui_story_5046_50460701_90_dialog_content = "Why, why, why!?",
  ui_story_5046_50460701_91_dialog_content = "(Tell me... Why can't I...)",
  ui_story_5046_50460701_92_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5046_50460701_93_dialog_content = "?!",
  ui_story_5046_50460701_94_dialog_content = "Wow!",
  ui_story_5046_50460701_95_dialog_content = "Hati, you...!",
  ui_story_5046_50460701_96_dialog_content = "M-Mom? My body... is on fire...",
  ui_story_5046_50460701_97_dialog_content = "Mom has a pendant just like mine.",
  ui_story_5046_50460701_98_dialog_content = "What is this pendant for?",
  ui_story_5046_50460701_99_dialog_content = "This pendant is very important.",
  ui_story_5046_50460701_100_dialog_content = "So take good care of it.",
  ui_story_5046_50460701_101_dialog_content = "Oh!",
  ui_story_5046_50460701_102_dialog_content = "But why is this pendant so important?",
  ui_story_5046_50460701_103_dialog_content = "... The pendant... important...",
  ui_story_5046_50460701_104_dialog_content = "... pendant... on...",
  ui_story_5046_50460701_105_dialog_content = "(This part of her memory is so vague...)",
  ui_story_5046_50460701_106_dialog_content = "Mom, what are you doing? You look stressed.",
  ui_story_5046_50460701_107_dialog_content = "It's my birthday today! I wanna eat strawberry cake!",
  ui_story_5046_50460701_108_dialog_content = "... Hati... listen to me.",
  ui_story_5046_50460701_109_dialog_content = "It's too late... It's too late for such talk. There's no time.",
  ui_story_5046_50460701_110_dialog_content = "Take this pendant, keep it close and never lose it!",
  ui_story_5046_50460701_111_dialog_content = "Mom, what are you saying? I don't understand.",
  ui_story_5046_50460701_112_dialog_content = "A bad person... A very bad person is coming for you.",
  ui_story_5046_50460701_113_dialog_content = "A bad person? Who?",
  ui_story_5046_50460701_114_dialog_content = "Mom, who is this bad person?",
  ui_story_5046_50460701_115_dialog_content = "Mom, what are you going to do? Mom?",
  ui_story_5046_50460701_116_dialog_content = "Ah—!",
  ui_story_5046_50460701_117_dialog_content = "<color=#e8d9bb>\"Mom, who's this bad person?\"</color>",
  ui_story_5046_50460701_118_dialog_content = "<color=#e8d9bb>\"Why did the bad person come and do this to us...?\"</color>",
  ui_story_5046_50460701_119_dialog_content = "<color=#e8d9bb>\"Does Mom think... I'm a bad person?\"</color>",
  ui_story_5046_50460701_120_dialog_content = "<color=#e8d9bb>\"Is that why she set me on fire...?\"</color>",
  ui_story_5046_50460701_121_dialog_content = "<color=#e8d9bb>\"Am I right, Mom?\"</color>",
  ui_story_5046_50460701_122_dialog_content = "(I finally understand... Hati...)",
  ui_story_5046_50460701_123_dialog_content = "(The bad person Mom was talking about... It's you...)",
  ui_story_5046_50460701_124_dialog_content = "(I hate this power... This power... it swallows us whole...)",
  ui_story_5046_50460701_125_dialog_content = "Us...?",
  ui_story_5046_50460701_126_dialog_content = "Hati! Hati!",
  ui_story_5046_50460701_127_dialog_content = "Who's that...?",
  ui_story_5046_50460701_128_dialog_content = "It's me! PlayerName!",
  ui_story_5046_50460701_129_dialog_content = "PlayerName? You want to... abandon me too?",
  ui_story_5046_50460701_130_dialog_content = "(PlayerName... Your beloved PlayerName...)",
  ui_story_5046_50460701_131_dialog_content = "(He'll leave you behind too...)",
  ui_story_5046_50460701_132_dialog_content = "(Who would like someone who's always setting everything on fire...? Someone who can't control their own flames...)",
  ui_story_5046_50460701_133_dialog_content = "(Someone who always made her mother angry... Until she finally abandoned her... Hati...)",
  ui_story_5046_50460701_134_dialog_content = "Mom doesn't love me... nobody will...",
  ui_story_5046_50460701_135_dialog_content = "It's not like that!",
  ui_story_5046_50460701_136_dialog_content = "Every time you use your power, it's for people important to you!",
  ui_story_5046_50460701_137_dialog_content = "To stop the Eclipsites from hurting your mother... Drying your quilt yourself, so that your mother could get more rest...",
  ui_story_5046_50460701_138_dialog_content = "Saving me from a horde of Eclipsites when I was helpless to fight against them...",
  ui_story_5046_50460701_139_dialog_content = "Using your forbidden power for the sake of those you care about...",
  ui_story_5046_50460701_140_dialog_content = "Can't you see, Hati? You're a very kind and considerate girl!",
  ui_story_5046_50460701_141_dialog_content = "That's what I like about you!",
  ui_story_5046_50460701_142_dialog_content = "And I know your mother must feel the same way!",
  ui_story_5046_50460701_143_dialog_content = "How could your mother not love a child as kind and compassionate as you?",
  ui_story_5046_50460701_144_dialog_content = "Mom... loves me?",
  ui_story_5046_50460701_145_dialog_content = "(He's lying to you...)",
  ui_story_5046_50460701_146_dialog_content = "Everything I said is true!",
  ui_story_5046_50460701_147_dialog_content = "You're the liar! All you have done is tear Hati down! You're the bad person!",
  ui_story_5046_50460701_148_dialog_content = "Hati, let's beat this bad person together!",
  ui_story_5046_50460702_1_dialog_content = "I... won?",
  ui_story_5046_50460702_2_dialog_content = "(Did you... win...?)",
  ui_story_5046_50460702_3_dialog_content = "(No... You're still here... I'm still here...)",
  ui_story_5046_50460702_4_dialog_content = "(You still can't... truly... accept yourself...)",
  ui_story_5046_50460702_5_dialog_content = "What... are you?",
  ui_story_5046_50460702_6_dialog_content = "(We will... meet again...)",
  ui_story_5046_50460702_7_dialog_content = "Hati!",
  ui_story_5046_50460702_8_dialog_content = "Urgh... huff...",
  ui_story_5046_50460702_9_dialog_content = "Hmm? PlayerName...?",
  ui_story_5046_50460702_10_dialog_content = "Brilliant, you finally woke up.",
  ui_story_5046_50460702_11_dialog_content = "...",
  ui_story_5046_50460702_12_dialog_content = "Thank you. You just saved me again.",
  ui_story_5046_50460702_13_dialog_content = "You don't need to thank me. You saved me from the Eclipsites just now!",
  ui_story_5046_50460702_14_dialog_content = "...",
  ui_story_5046_50460702_15_dialog_content = "I want to get my pendant back from that masked man because it belonged to my mom.",
  ui_story_5046_50460702_16_dialog_content = "Ever since I was a kid, I was always different from everyone else. I could only watch them from a distance through the window, and was never allowed to go outside.",
  ui_story_5046_50460702_17_dialog_content = "In my world, there was only my mom.",
  ui_story_5046_50460702_18_dialog_content = "She played games with me, taught me to read, read stories to me... My mom was everything to me.",
  ui_story_5046_50460702_19_dialog_content = "I loved her so much, but my mom... Maybe she didn't love me as much as I loved her.",
  ui_story_5046_50460702_20_dialog_content = "How can you say that...?",
  ui_story_5046_50460702_21_dialog_content = "As far back as I can remember, we were always on the move, and never stayed in one place for too long.",
  ui_story_5046_50460702_22_dialog_content = "My mother often looked at me with a hint of fear in her eyes, and she never let me go out.",
  ui_story_5046_50460702_23_dialog_content = "Our last home was the one we stayed at the longest. It was also the place my childhood came to an end...",
  ui_story_5046_50460702_24_dialog_content = "Hati...",
  ui_story_5046_50460702_25_dialog_content = "I always try to escape, to avoid having to recall that day. But how can I forget?",
  ui_story_5046_50460702_26_dialog_content = "August 26th. That day... was my birthday.",
  ui_story_5046_50460702_27_dialog_content = "?!",
  ui_story_5046_50460702_28_dialog_content = "Hati...",
  ui_story_5046_50460702_29_dialog_content = "Although my mother could be strict sometimes, she was really good to me.",
  ui_story_5046_50460702_30_dialog_content = "She always remembered my birthday and prepared everything one day in advance. She even made a strawberry cream cake with me...",
  ui_story_5046_50460702_31_dialog_content = "That day, Mom got up early as usual, but she seemed to be in a weird mood.",
  ui_story_5046_50460702_32_dialog_content = "She simply wished me a happy birthday and then started busying herself around the house like she was preparing something.",
  ui_story_5046_50460702_33_dialog_content = "I kept asking if I could eat the cake, but my mom didn't answer.",
  ui_story_5046_50460702_34_dialog_content = "Then she threw me into the fireplace. She tried to burn me alive.",
  ui_story_5046_50460702_35_dialog_content = "Why would she do that!?",
  ui_story_5046_50460702_36_dialog_content = "I can't really remember what happened after she threw me into the fire. When I woke up, I was at the orphanage.",
  ui_story_5046_50460702_37_dialog_content = "That was the first time I hung out with so many children...",
  ui_story_5046_50460702_38_dialog_content = "I had always wanted to go out and play with other children, but I never imagined this was how it would happen.",
  ui_story_5046_50460702_39_dialog_content = "I learned to get along with the other children and grown-ups in the orphanage, but they weren't very friendly.",
  ui_story_5046_50460702_40_dialog_content = "The children were always fighting with each other, and the grown-ups were really mean to us.",
  ui_story_5046_50460702_41_dialog_content = "It was awful there, and I just wanted to complain to my mom, but I didn't know where she was.",
  ui_story_5046_50460702_42_dialog_content = "That was when I realized... that she had abandoned me.",
  ui_story_5046_50460702_43_dialog_content = "One night, the people at the orphanage tried to do something to me while I was sleeping. I tried to break free with all my might, and someone cut my ear.",
  ui_story_5046_50460702_44_dialog_content = "A chunk of my ear came off, just like that. I had never been in so much pain before.",
  ui_story_5046_50460702_45_dialog_content = "I couldn't control my emotions—I let out my rage and burned the whole orphanage down.",
  ui_story_5046_50460702_46_dialog_content = "As you know, I was sent to the Shadowlord after this and he let me go just two months ago.",
  ui_story_5046_50460702_47_dialog_content = "Hati...",
  ui_story_5046_50460702_48_dialog_content = "There's no such thing as a mother who doesn't love her child.",
  ui_story_5046_50460702_49_dialog_content = "I'm sure she wants you to live a good life, no matter what comes your way.",
  ui_story_5046_50460702_50_dialog_content = "You don't need to try making me feel better, PlayerName.",
  ui_story_5046_50460702_51_dialog_content = "If my mom loved me, why would she have thrown me into that fireplace?",
  ui_story_5046_50460702_52_dialog_content = "I know that's not what you really think deep down in your heart, right, Hati?",
  ui_story_5046_50460702_53_dialog_content = "Otherwise, why would you try so hard to find that lost memory?",
  ui_story_5046_50460702_54_dialog_content = "You must believe that your mom still loves you, somewhere in your heart.",
  ui_story_5046_50460702_55_dialog_content = "...",
  ui_story_5046_50460702_56_dialog_content = "... Hmn.",
  ui_story_5046_50460702_57_dialog_content = "When I lost control of myself just now, why didn't you leave with the others amid all the chaos?",
  ui_story_5046_50460702_58_dialog_content = "Because... I thought you might need my help.",
  ui_story_5046_50460702_59_dialog_content = "Apart from Grimme, no one would try so hard to help me.",
  ui_story_5046_50460702_60_dialog_content = "It's only right for friends to support each other.",
  ui_story_5046_50460702_61_dialog_content = "Friends? I don't have any friends.",
  ui_story_5046_50460702_62_dialog_content = "From now on, you can call me your friend.",
  ui_story_5046_50460702_63_dialog_content = "You've been searching for your memories for the entire two months since you left the Shadowlord.",
  ui_story_5046_50460702_64_dialog_content = "But there's still such a huge world out there, waiting for you to explore.",
  ui_story_5046_50460702_65_dialog_content = "When you get your memory back, you're welcome to come hang out with me on the Colossus!",
  ui_story_5046_50460702_66_dialog_content = "We can travel around the world and make up for the time you weren't allowed to go out in the past!",
  ui_story_5046_50460702_67_dialog_content = "...",
  ui_story_5046_50460702_68_dialog_content = "So, what do you think?",
  ui_story_5046_50460702_69_dialog_content = "...",
  ui_story_5046_50460702_70_dialog_content = "Sure.",
  ui_story_5046_50460801_1_dialog_content = "(Mr. Hamell's last words and the sole survivor he mentioned—it's all related to the orphanage.)",
  ui_story_5046_50460801_2_dialog_content = "(There are no other clues available at present. The suspects Hati and PlayerName have also fled.)",
  ui_story_5046_50460801_3_dialog_content = "(As things stand, my only option is to continue looking into the orphanage.)",
  ui_story_5046_50460801_4_dialog_content = "(Almost no traces of the past remain after the orphanage's reconstruction. Now, only the remaining children from that year have yet to be investigated.)",
  ui_story_5046_50460801_5_dialog_content = "You're a judge? Are you sure you've got the right person? I'm just a servant...",
  ui_story_5046_50460801_6_dialog_content = "(There were only two people I could find records on in the archives. It looks like this girl is two years older than Hati.)",
  ui_story_5046_50460801_7_dialog_content = "(After the fire, she was sent to live with a foster family nearby. Now, she's a maid for a noble family in Lumopolis.)",
  ui_story_5046_50460801_8_dialog_content = "Please, there's no need to be nervous. I just want to know about the fire at the Umbraton Orphanage.",
  ui_story_5046_50460801_9_dialog_content = "As far as I know, you stayed there for quite a long time.",
  ui_story_5046_50460801_10_dialog_content = "They asked me all these questions so many times before... Why is this happening all over again?",
  ui_story_5046_50460801_11_dialog_content = "I was sound asleep that night... until I was awakened by the screams of the other children. When I woke up, the whole place was already engulfed in flames.",
  ui_story_5046_50460801_12_dialog_content = "That new girl, the demi-human—her whole body was on fire. The boy in the bed next to me said she was the one who started it all.",
  ui_story_5046_50460801_13_dialog_content = "I scrambled to get out of there, I couldn't really pay attention to much else.",
  ui_story_5046_50460801_14_dialog_content = "(Hmm... It's exactly the same as her previous statement. This is all known information.)",
  ui_story_5046_50460801_15_dialog_content = "Did you notice at the time whether this demi-human named Hati had been arguing with anyone at the orphanage?",
  ui_story_5046_50460801_16_dialog_content = "Or did she hold any grievances toward the teachers, administrators, or other people at the orphanage?",
  ui_story_5046_50460801_17_dialog_content = "I'm not sure, I hadn't heard anything.",
  ui_story_5046_50460801_18_dialog_content = "But revenge...? How old was she back then? She's not even as old as me.",
  ui_story_5046_50460801_19_dialog_content = "And she had only been at the orphanage for a month. Who could she have made enemies within such a short space of time?",
  ui_story_5046_50460801_20_dialog_content = "If you really think it might be possible, some kids were bigger than the rest and liked to throw their weight around to bully people into doing what they wanted.",
  ui_story_5046_50460801_21_dialog_content = "That demi-human girl was too small to fight those big kids...",
  ui_story_5046_50460801_22_dialog_content = "And the teachers there didn't care about any of the disputes between the kids, they were neither patient nor kind...",
  ui_story_5046_50460801_23_dialog_content = "I don't think any of us liked the staff there?",
  ui_story_5046_50460801_24_dialog_content = "By the way, there's one more thing I want to ask.",
  ui_story_5046_50460801_25_dialog_content = "Have you kept in contact with any of the children who were adopted from the orphanage?",
  ui_story_5046_50460801_26_dialog_content = "The adoption rate at the orphanage was very high, but there are no records for any adoptees and no proof of return visits...",
  ui_story_5046_50460801_27_dialog_content = "I haven't kept in contact with anyone.",
  ui_story_5046_50460801_28_dialog_content = "Back then, we used to joke that when they came to take eight or nine children away every month, they were being fed to Eclipsites.",
  ui_story_5046_50460801_29_dialog_content = "Eight or nine children were adopted every month...",
  ui_story_5046_50460801_30_dialog_content = "(This is indeed an abnormal situation...)",
  ui_story_5046_50460801_31_dialog_content = "Sorry for taking up your time. Thank you very much.",
  ui_story_5046_50460801_32_dialog_content = "(The next survivor is a boy about the same age as Hati.)",
  ui_story_5046_50460801_33_dialog_content = "(According to the records, he managed the bakery with his adoptive parents after he was adopted.)",
  ui_story_5046_50460801_34_dialog_content = "You're a judge? I didn't do nuthin'!",
  ui_story_5046_50460801_35_dialog_content = "Please, there's no need to be so nervous. I want to understand what happened regarding the fire at the Umbraton Orphanage.",
  ui_story_5046_50460801_36_dialog_content = "Huh? That all happened so long ago, but you're still investigating it, eh?",
  ui_story_5046_50460801_37_dialog_content = "But I'm afraid you're out of luck—I can't tell you anything new. Everything I could remember has already been taken down in my statement.",
  ui_story_5046_50460801_38_dialog_content = "So if possible, I hope you'll refrain from spooking my customers.",
  ui_story_5046_50460801_39_dialog_content = "Uh...",
  ui_story_5046_50460801_40_dialog_content = "If you can help me by recalling more of what happened, I'll buy all the bread in your bakery.",
  ui_story_5046_50460801_41_dialog_content = "Really!?",
  ui_story_5046_50460801_42_dialog_content = "Well, now that you mention it, I might be able to recall a few more details.",
  ui_story_5046_50460801_43_dialog_content = "Thank you for your cooperation. You said that Hati set the fire. Can you describe what happened in more detail?",
  ui_story_5046_50460801_44_dialog_content = "That night... I've always been a very light sleeper since I was tiny, so I woke up as soon as I heard that demi-human start yelling.",
  ui_story_5046_50460801_45_dialog_content = "My bed was pretty far from hers. I didn't see what had happened, but she started getting angry after the shouting.",
  ui_story_5046_50460801_46_dialog_content = "Then the flames all over her body set the curtain on fire. The fire started to get bigger and bigger, and the other children eventually woke up.",
  ui_story_5046_50460801_47_dialog_content = "I ran for it, along with all the other children, but my leg was burned. I said all this before when they asked me the first time 'round.",
  ui_story_5046_50460801_48_dialog_content = "Then, do you know whether Hati, the demi-human, had made any enemies in the orphanage?",
  ui_story_5046_50460801_49_dialog_content = "The victims of the recent arson attacks have all been related to the orphanage. I want to know whether they held any grudges against Hati.",
  ui_story_5046_50460801_50_dialog_content = "There were always new children showing up at the orphanage, but most ended up being sent away before they could really get to know anyone.",
  ui_story_5046_50460801_51_dialog_content = "If it weren't for the fact she's a demi-human, I wouldn't have even remembered who she was, let alone who she didn't get along with.",
  ui_story_5046_50460801_52_dialog_content = "As for the people who ran the orphanage...",
  ui_story_5046_50460801_53_dialog_content = "They had to deal with a big group of noisy brats every day, and none of them were their own.",
  ui_story_5046_50460801_54_dialog_content = "Even if they looked friendly enough on the surface, who knew what they were really like behind closed doors?",
  ui_story_5046_50460801_55_dialog_content = "(It seems everyone has a bad impression of the orphanage staff...)",
  ui_story_5046_50460801_56_dialog_content = "Have you had any contact with any of the other children adopted from the orphanage?",
  ui_story_5046_50460801_57_dialog_content = "Or do you have the contact details of any of the adopting families?",
  ui_story_5046_50460801_58_dialog_content = "I lost contact with everyone after they were adopted.",
  ui_story_5046_50460801_59_dialog_content = "As for the contact details of the adopting families...",
  ui_story_5046_50460801_60_dialog_content = "Isn't that something the director should've made a note of?",
  ui_story_5046_50460801_61_dialog_content = "You know, I used to see the teachers at the orphanage staring at certain children, writing and drawing in their notebooks.",
  ui_story_5046_50460801_62_dialog_content = "And when adoption time came 'round, those were the kids who got sent away.",
  ui_story_5046_50460801_63_dialog_content = "Now that I think about it, those notebooks should contain plenty of information about the adopted children, no? I dunno—you're a judge, you should have the authority to go take a look at them, right?",
  ui_story_5046_50460801_64_dialog_content = "Unfortunately, it seems everything was destroyed in the fire.",
  ui_story_5046_50460801_65_dialog_content = "Anyway, thank you for your cooperation. I'll take all the bread you have.",
  ui_story_5046_50460801_66_dialog_content = "(Phew, I managed to deal with that ridiculously huge amount of bread. But now...)",
  ui_story_5046_50460801_67_dialog_content = "(There's still the matter of those adopted children who disappeared, and Hati, who was accused of being a murderer when she was just a child.)",
  ui_story_5046_50460801_68_dialog_content = "(What kind of orphanage succeeds in having so many children adopted every month, and then they all disappear without a trace?)",
  ui_story_5046_50460801_69_dialog_content = "(The worst-case scenario is that they used them for something...)",
  ui_story_5046_50460801_70_dialog_content = "(It's a horrifying thought... but if it's true, Hati had just cause to start the fire and kill Mr. Hamell.)",
  ui_story_5046_50460801_71_dialog_content = "(The very thought of it makes me shudder. How many secrets are hidden in that old orphanage?)",
  ui_story_5046_50460801_72_dialog_content = "Oh...",
  ui_story_5046_50460801_73_dialog_content = "Watch your step, miss.",
  ui_story_5046_50460801_74_dialog_content = "Thank you...",
  ui_story_5046_50460801_75_dialog_content = "Grimme's the name. I'm the owner of the Firefly Bar, just around the corner.",
  ui_story_5046_50460801_76_dialog_content = "Grimme? Aren't you Hati's friend? Mr. Zenas mentioned you.",
  ui_story_5046_50460801_77_dialog_content = "Oh, so you've heard of me? Listen, do you mind if we save the small talk for later? There's actually something I was wondering whether you'd be able to help me with.",
  ui_story_5046_50460801_78_dialog_content = "What is it...?",
  ui_story_5046_50460801_79_dialog_content = "Graaahh—!",
  ui_story_5046_50460801_80_dialog_content = "!!!",
  ui_story_5046_50460801_81_dialog_content = "I just got done dealing with a few filthy things in the suburbs.",
  ui_story_5046_50460801_82_dialog_content = "Eclipsites!? Look out behind you!",
  ui_story_5046_50460802_1_dialog_content = "Thank you, young lady. If you weren't here to help out just now, those Eclipsites would've made short work of me.",
  ui_story_5046_50460802_2_dialog_content = "It was nothing. By the way, I want to ask you something about Hati.",
  ui_story_5046_50460802_3_dialog_content = "Certainly. The Firefly Bar is on the corner up ahead. Let's sit down and chat over a drink.",
  ui_story_5046_50460802_4_dialog_content = "<color=#e8d9bb>Ding—!</color>",
  ui_story_5046_50460802_5_dialog_content = "Sorry for the inconvenience.",
  ui_story_5046_50460802_6_dialog_content = "You just did me a real solid, miss. This is the least I can do.",
  ui_story_5046_50460802_7_dialog_content = "Please take a seat. It's not business hours yet. Would you like something to drink?",
  ui_story_5046_50460802_8_dialog_content = "I'm on duty, and I don't drink.",
  ui_story_5046_50460802_9_dialog_content = "Alcohol aside, we also have a range of very nice soft drinks here.",
  ui_story_5046_50460802_10_dialog_content = "There's Blue Storm, Umbraton Delight, White Night Iced Tea...",
  ui_story_5046_50460802_11_dialog_content = "No, thank you. Let's get straight to the point.",
  ui_story_5046_50460802_12_dialog_content = "How did you and Hati meet?",
  ui_story_5046_50460802_13_dialog_content = "Well, she works here with me, doesn't she!",
  ui_story_5046_50460802_14_dialog_content = "She usually handles bringing in the ingredients, cleaning the kitchen... a lot of different jobs, really. She doesn't say much, but she's one heck of a hard worker.",
  ui_story_5046_50460802_15_dialog_content = "Where was Hati when the recent fires occurred?",
  ui_story_5046_50460802_16_dialog_content = "Now those weren't that recent at all, I can't rightly recall.",
  ui_story_5046_50460802_17_dialog_content = "However, I do remember this one day very clearly. It was purchasing day.",
  ui_story_5046_50460802_18_dialog_content = "Hati was busy all day in the kitchen, counting the stock and checking the freshness of the ingredients. She didn't get a chance to rest until evening.",
  ui_story_5046_50460802_19_dialog_content = "(This was the day Fairmont was killed. According to Grimme's testimony, Hati didn't have the opportunity to commit murder.)",
  ui_story_5046_50460802_20_dialog_content = "(However, Grimme may be trying to protect Hati.)",
  ui_story_5046_50460802_21_dialog_content = "Miss, please believe me. I'm telling you the truth.",
  ui_story_5046_50460802_22_dialog_content = "You can call me Kristen.",
  ui_story_5046_50460802_23_dialog_content = "Back to Hati—do you have any other information about her you can share with me?",
  ui_story_5046_50460802_24_dialog_content = "For example, has she ever mentioned holding a grudge against anyone? Has she ever mentioned revenge or anything similar?",
  ui_story_5046_50460802_25_dialog_content = "Like I said, Hati doesn't talk much. We haven't been acquainted long, but I haven't heard her mention anything like that the whole time I've known her.",
  ui_story_5046_50460802_26_dialog_content = "(This doesn't seem to be getting me anywhere.)",
  ui_story_5046_50460802_27_dialog_content = "In that case, I won't trouble you any further. Good day.",
  ui_story_5046_50460802_28_dialog_content = "You're gonna leave without trying the homemade juice I made just for you?",
  ui_story_5046_50460802_29_dialog_content = "You didn't seem interested in any of the drinks I mentioned before, so I mixed up a special beverage for you just now.",
  ui_story_5046_50460802_30_dialog_content = "You should know, I'm the best mixologist in Umbraton.",
  ui_story_5046_50460802_31_dialog_content = "That won't be necessary.",
  ui_story_5046_50460802_32_dialog_content = "Don't be like that. A drink for a story straddling truth and lies—that's how things are done in Umbraton.",
  ui_story_5046_50460802_33_dialog_content = "What's the harm in giving it a try, eh?",
  ui_story_5046_50460802_34_dialog_content = "(Looks like Grimme is trying to imply something... and why suddenly standing so close to me!?)",
  ui_story_5046_50460802_35_dialog_content = "I still have official duties to attend to, and the culprit has not been caught yet. I can't...",
  ui_story_5046_50460802_36_dialog_content = "You looked so sad when I saw you out there on the street. Has the case hit a brick wall?",
  ui_story_5046_50460802_37_dialog_content = "It's times like these we should sit down for a drink and listen to a tale or two to relax. You may even find some new inspiration.",
  ui_story_5046_50460802_38_dialog_content = "(That sounds about right.)",
  ui_story_5046_50460802_39_dialog_content = "(There are no other clues to go on for the time being. I should just sit down and listen.)",
  ui_story_5046_50460802_40_dialog_content = "Fine, but just the one.",
  ui_story_5046_50460802_41_dialog_content = "Hehe, then I'll start the story.",
  ui_story_5046_50460802_42_dialog_content = "Ten years ago, Umbraton didn't have a Shadowlord, and no one batted an eyelid at the fighting and killing going on in the streets, let alone a certain orphanage on the outskirts of town.",
  ui_story_5046_50460802_43_dialog_content = "But this orphanage on the outskirts still managed to stay open for business...",
  ui_story_5046_50460802_44_dialog_content = "What do you think the reason for that was?",
  ui_story_5046_50460802_45_dialog_content = "In this turbulent society, the orphanage managed to remain operational... I suppose it was because of a charitable person's support.",
  ui_story_5046_50460802_46_dialog_content = "That's correct. The orphanage did indeed receive support, but there was no charity.",
  ui_story_5046_50460802_47_dialog_content = "The orphanage had only five employees and one director, and there wasn't even the faintest rumor of any kind of Umbraton bigshot keeping that place afloat.",
  ui_story_5046_50460802_48_dialog_content = "And every so often, some kids were adopted, while some kids were sent to the orphanage...",
  ui_story_5046_50460802_49_dialog_content = "It was like buying and selling drinks behind the bar.",
  ui_story_5046_50460802_50_dialog_content = "D-Do you mean to say that this orphanage was running a child trafficking operation?",
  ui_story_5046_50460802_51_dialog_content = "Don't get ahead of yourself, this story's not over yet.",
  ui_story_5046_50460802_52_dialog_content = "They say the adopted children were sent to certain nobles of Lumopolis—nobles whose lines are all but extinct.",
  ui_story_5046_50460802_53_dialog_content = "However, I heard that some time ago, an official named Pittman started investigating these nobles again.",
  ui_story_5046_50460802_54_dialog_content = "<color=#FFB400>The case</color> Pittman is investigating!",
  ui_story_5046_50460802_55_dialog_content = "Five employees and one director... That matches the information I have on the old orphanage precisely!",
  ui_story_5046_50460802_56_dialog_content = "The director of the old orphanage was killed in the fire, and three of the employees have died in fires occurring in the past two months...",
  ui_story_5046_50460802_57_dialog_content = "Mr. Hamell was also connected to the old orphanage, plus the person he mentioned...",
  ui_story_5046_50460802_58_dialog_content = "That makes five!",
  ui_story_5046_50460802_59_dialog_content = "Combined with the previously investigated statements of the two children who survived the fire...",
  ui_story_5046_50460802_60_dialog_content = "The orphanage in this story is the old orphanage, is it not?",
  ui_story_5046_50460802_61_dialog_content = "Well... I'm just telling a story, nothing more.",
  ui_story_5046_50460802_62_dialog_content = "If you can derive some inspiration from it, good for you.",
  ui_story_5046_50460802_63_dialog_content = "I have learned a lot from this story. I appreciate your help.",
  ui_story_5046_50460802_64_dialog_content = "But I'm curious... Where did you hear this story?",
  ui_story_5046_50460802_65_dialog_content = "The case Mr. Pittman investigated is related to the nobles of Lumopolis.",
  ui_story_5046_50460802_66_dialog_content = "Whoever told you this story knows so many precise details. It can't have been an ordinary citizen.",
  ui_story_5046_50460802_67_dialog_content = "The people who tell stories here don't always leave their names. The less I know, the more interesting the story is.",
  ui_story_5046_50460802_68_dialog_content = "The shadows know all secrets.",
  ui_story_5046_50460802_69_dialog_content = "(Grimme looks unreliable but speaks with perfect precision.)",
  ui_story_5046_50460802_70_dialog_content = "(Our encounter in the streets today was not an accident. I was brought here on purpose to listen to all this.)",
  ui_story_5046_50460802_71_dialog_content = "Everything that takes place on the continent is connected. A butterfly in Umbraton can cause a storm in Lumopolis.",
  ui_story_5046_50460802_72_dialog_content = "Hmm?",
  ui_story_5046_50460802_73_dialog_content = "(What's with that look and the sudden saying?)",
  ui_story_5046_50460802_74_dialog_content = "Hehe... Alright, alright, story time's over.",
  ui_story_5046_50460802_75_dialog_content = "Look, the night view is amazing. You rarely get to see the night sky of Umbraton, isn't that right?",
  ui_story_5046_50460802_76_dialog_content = "At night, many small vendors appear in Umbraton, their lamps stretching on like a river of stars. It's an unforgettable sight.",
  ui_story_5046_50460802_77_dialog_content = "Thank you for your story. The drink was nice too.",
  ui_story_5046_50460802_78_dialog_content = "Hehe, this special mocktail is actually something I had never tried before. I only thought of going for this kind of combination after seeing you.",
  ui_story_5046_50460802_79_dialog_content = "Does this drink have a name?",
  ui_story_5046_50460802_80_dialog_content = "Not yet, but I'm going to call it—",
  ui_story_5046_50460802_81_dialog_content = "Lumopolis' Lily.",
  ui_story_5046_50460901_1_dialog_content = "Hati, do you remember where you used to live?",
  ui_story_5046_50460901_2_dialog_content = "If you want to retrieve your memories of the past, go to the place you used to live and see what you can remember.",
  ui_story_5046_50460901_3_dialog_content = "My mom and I moved home several times. I can't remember my old address.",
  ui_story_5046_50460901_4_dialog_content = "But I still remember the house I set on fire. It was near Umbraton.",
  ui_story_5046_50460901_5_dialog_content = "You didn't burn it down. You've definitely got that part wrong.",
  ui_story_5046_50460901_6_dialog_content = "Let's go there and take a look around. Maybe you'll remember something.",
  ui_story_5046_50460901_7_dialog_content = "This is it.",
  ui_story_5046_50460901_8_dialog_content = "All the houses we passed by along the way were deserted. It looks like no one has lived here for a long time.",
  ui_story_5046_50460901_9_dialog_content = "This is the only house that has been burned to the ground. One glance is all it takes to see that.",
  ui_story_5046_50460901_10_option_content = "Why was this place abandoned?",
  ui_story_5046_50460901_11_dialog_content = "I don't know.",
  ui_story_5046_50460901_12_dialog_content = "All I remember is that, when I woke up after the fire, I was already in the orphanage.",
  ui_story_5046_50460901_13_dialog_content = "Before long, the orphanage burned down, and I was sent to the Shadowlord.",
  ui_story_5046_50460901_14_dialog_content = "Today is the first time I've been back here in so long.",
  ui_story_5046_50460901_15_dialog_content = "Show me around your home.",
  ui_story_5046_50460901_16_option_content = "Why did you and your mother move around so often?",
  ui_story_5046_50460901_17_dialog_content = "Because bad people were chasing us all the time.",
  ui_story_5046_50460901_18_dialog_content = "My mom once told me that my dad was very powerful and that someone wanted to take him away and do experiments on him.",
  ui_story_5046_50460901_19_dialog_content = "Then one day, a bad person actually broke into our house and tried to catch my dad. After that, my dad stayed behind to protect my mom.",
  ui_story_5046_50460901_20_dialog_content = "Mom ran away and gave birth to me.",
  ui_story_5046_50460901_21_dialog_content = "I remember asking my mom why I never got to see my dad. Mom told me that my dad was somewhere far away.",
  ui_story_5046_50460901_22_dialog_content = "When I grew up, my mom told me that a scary organization wanted to catch my dad to use him in their experiments.",
  ui_story_5046_50460901_23_dialog_content = "This organization wouldn't give up on chasing us, so my mom always dragged me to new places.",
  ui_story_5046_50460901_24_dialog_content = "Show me around your home.",
  ui_story_5046_50460901_25_option_content = "Show me around your home.",
  ui_story_5046_50460901_26_dialog_content = "I know it's all burned down now, but you should still remember what life was like there.",
  ui_story_5046_50460901_27_dialog_content = "It might make you sad, but any tiny detail could trigger your lost memories.",
  ui_story_5046_50460901_28_dialog_content = "I was actually afraid to come back here... Afraid to remember the little scraps of my memories living with Mom.",
  ui_story_5046_50460901_29_dialog_content = "I'm also afraid to remember that other missing memory...",
  ui_story_5046_50460901_30_dialog_content = "If I find out that Mom threw me into the fireplace because she feared my power...",
  ui_story_5046_50460901_31_dialog_content = "No way. Your mother must have done it for some other reason.",
  ui_story_5046_50460901_32_dialog_content = "Fire can't hurt you. Your mother must have known this.",
  ui_story_5046_50460901_33_dialog_content = "Maybe you were in danger at that time, and your mother wanted to protect you, so she put you in the fireplace.",
  ui_story_5046_50460901_34_dialog_content = "Just like how your father stayed behind to protect her.",
  ui_story_5046_50460901_35_dialog_content = "...",
  ui_story_5046_50460901_36_dialog_content = "Let's go. I'll show you where I used to live.",
  ui_story_5046_50460901_37_dialog_content = "Okay!",
  ui_story_5046_50460901_38_dialog_content = "You can see the living room from here once you walk through the door. My mom used to bring me tasty food and picture books.",
  ui_story_5046_50460901_39_dialog_content = "There was a window here, which was always covered by thick curtains. The light couldn't get through it, and I couldn't see outside.",
  ui_story_5046_50460901_40_dialog_content = "But I could hear the children playing out there.",
  ui_story_5046_50460901_41_dialog_content = "I remember one time I wanted to open the window to see what the children were playing, but my mom stopped me as soon as I did.",
  ui_story_5046_50460901_42_dialog_content = "\"Close the window! Right now!\"",
  ui_story_5046_50460901_43_dialog_content = "The room must've always been dark if the light couldn't get in.",
  ui_story_5046_50460901_44_dialog_content = "Mom lit loads of candles around the house. That's what we used for light.",
  ui_story_5046_50460901_45_dialog_content = "How strange...",
  ui_story_5046_50460901_46_dialog_content = "I was born with powerful flame Lumina. Mom said I inherited it from my dad.",
  ui_story_5046_50460901_47_dialog_content = "When I was little, I often accidentally set quilts and picture books on fire, and my mom also told me I wasn't allowed to use my flames.",
  ui_story_5046_50460901_48_dialog_content = "I guess my mom was afraid of my power, so she didn't let me go out to play with other children... and then she threw me into the fireplace.",
  ui_story_5046_50460901_49_dialog_content = "(Hati's mother wouldn't let her go out, and she sealed the house securely so people couldn't see inside...)",
  ui_story_5046_50460901_50_dialog_content = "(Also, people were hunting them down. Maybe Hati's mother was trying to hide something from the world outside.)",
  ui_story_5046_50460901_51_dialog_content = "Look, this is the fireplace.",
  ui_story_5046_50460901_52_dialog_content = "...",
  ui_story_5046_50460901_53_dialog_content = "PlayerName, I... I want to go into the fireplace.",
  ui_story_5046_50460901_54_dialog_content = "Huh?",
  ui_story_5046_50460901_55_dialog_content = "The same way you made me recall my life in this house, I want to remember what it was like being thrown in there.",
  ui_story_5046_50460901_56_dialog_content = "Maybe I'll remember something.",
  ui_story_5046_50460901_57_dialog_content = "That sounds like a reasonable idea...",
  ui_story_5046_50460901_58_dialog_content = "Okay!",
  ui_story_5046_50460901_59_dialog_content = "If you have any trouble in there, I'll use my psychic abilities to enter your memories and help you!",
  ui_story_5046_50460901_60_dialog_content = "Thank you... but I want to try remembering by myself.",
  ui_story_5046_50460901_61_dialog_content = "Okay, but just tell me if you need help!",
  ui_story_5046_50460901_62_dialog_content = "<color=#e8d9bb>Rural Umbraton</color>",
  ui_story_5046_50460901_63_dialog_content = "The place Hati used to live is just up ahead.",
  ui_story_5046_50460901_64_dialog_content = "My father's Umbraton vacation manor is also nearby.",
  ui_story_5046_50460901_65_dialog_content = "Left at this intersection, and just a little further, I should be able to see the gates.",
  ui_story_5046_50460901_66_dialog_content = "The last time I came to this manor, I was on vacation with my parents. The place Mr. Zenas rescued me is also around here...",
  ui_story_5046_50460901_67_dialog_content = "That's... PlayerName!",
  ui_story_5046_50460901_68_dialog_content = "Did you remember something?",
  ui_story_5046_50460901_69_dialog_content = "Not yet.",
  ui_story_5046_50460901_70_dialog_content = "Can I really... not remember?",
  ui_story_5046_50460901_71_dialog_content = "PlayerName! Hati!",
  ui_story_5046_50460901_72_dialog_content = "Kristen!?",
  ui_story_5046_50460901_73_dialog_content = "Hati, according to the law, you're under arrest on suspicion of several serious crimes, including intentional homicide and arson!",
  ui_story_5046_50460901_74_dialog_content = "W-Wait!",
  ui_story_5046_50460901_75_dialog_content = "She didn't do any of those things! Why are you trying to arrest her!?",
  ui_story_5046_50460901_76_dialog_content = "What criminal would be willing to admit their guilt?",
  ui_story_5046_50460901_77_dialog_content = "W-Well, if you want to arrest someone, don't you need evidence?",
  ui_story_5046_50460901_78_dialog_content = "... Evidence?",
  ui_story_5046_50460901_79_dialog_content = "PlayerName, didn't you see it too? Hati killed Hamell before our very eyes.",
  ui_story_5046_50460901_80_dialog_content = "Kristen, believe me, Hati didn't kill Hamell!",
  ui_story_5046_50460901_81_dialog_content = "Someone else must have killed Hamell from the shadows.",
  ui_story_5046_50460901_82_dialog_content = "In any case, Hati was there when Hamell died.",
  ui_story_5046_50460901_83_dialog_content = "Even if she didn't kill him, she's obligated to cooperate with the investigation.",
  ui_story_5046_50460901_84_dialog_content = "Come with me.",
  ui_story_5046_50460901_85_dialog_content = "I need to find my lost memories with my mom.",
  ui_story_5046_50460901_86_dialog_content = "That's all I care about right now.",
  ui_story_5046_50460901_87_dialog_content = "So, are you resisting arrest?",
  ui_story_5046_50460901_88_dialog_content = "Call it whatever you like.",
  ui_story_5046_50460901_89_dialog_content = "It seems I'll have to resort to using force.",
  ui_story_5046_50460901_90_dialog_content = "Kristen, can you let Hati try to get her memory back before you take her away?",
  ui_story_5046_50460901_91_dialog_content = "Step aside, PlayerName.",
  ui_story_5046_50460901_92_dialog_content = "I will have to arrest you as an accomplice if you stand in my way of the suspect again.",
  ui_story_5046_50460901_93_dialog_content = "Memories of mom... are very important.",
  ui_story_5046_50460901_94_dialog_content = "I can understand the importance of these memories to Hati.",
  ui_story_5046_50460901_95_dialog_content = "And I promised her I'd help find these lost memories...",
  ui_story_5046_50460901_96_dialog_content = "So, no... There's no way I'm going anywhere.",
  ui_story_5046_50460901_97_dialog_content = "I will protect Hati until she finds her lost memories.",
  ui_story_5046_50460901_98_dialog_content = "You wish to protect Hati... but I also wish to protect Captain Zenas!",
  ui_story_5046_50460901_99_dialog_content = "Hati set fire to the orphanage and took you hostage...",
  ui_story_5046_50460901_100_dialog_content = "It is you who cast a shadow on Mr. Zenas' knighthood!",
  ui_story_5046_50460901_101_dialog_content = "He has endured so much to find you and Hati!",
  ui_story_5046_50460901_102_dialog_content = "If I just take you back and explain everything to the Shadowlord and all of Umbraton...",
  ui_story_5046_50460901_103_dialog_content = "If I just do this, Mr. Zenas will be alright!",
  ui_story_5046_50460901_104_dialog_content = "I'll say it once more!",
  ui_story_5046_50460901_105_dialog_content = "Step aside, PlayerName!",
  ui_story_5046_50460901_106_dialog_content = "No! I'll never step aside!",
  ui_story_5046_50460901_107_dialog_content = "Hati... protect... the pendant...",
  ui_story_5046_50460901_108_dialog_content = "Mom... What did my mom want me to protect...?",
  ui_story_5046_50460901_109_dialog_content = "Tell me, Mom...",
  ui_story_5046_50460901_110_dialog_content = "What happened that day? You pushed me into the fireplace so heartlessly...",
  ui_story_5046_50460901_111_dialog_content = "I'll say it again, for the last time! Step aside, PlayerName!",
  ui_story_5046_50460901_112_dialog_content = "Give it to me... die...",
  ui_story_5046_50460901_113_dialog_content = "Urgh! My head hurts! It's like something's burrowing into my brain!",
  ui_story_5046_50460901_114_dialog_content = "He's here.",
  ui_story_5046_50460901_115_dialog_content = "This day... It's finally here.",
  ui_story_5046_50460901_116_dialog_content = "Mom?",
  ui_story_5046_50460901_117_dialog_content = "Hati, no matter what happens, whether Mom is with you or not, Mom will always love you.",
  ui_story_5046_50460901_118_dialog_content = "Why wouldn't you be with me, Mom?",
  ui_story_5046_50460901_119_dialog_content = "I don't understand.",
  ui_story_5046_50460901_120_dialog_content = "It's too late...",
  ui_story_5046_50460901_121_dialog_content = "Hati, make sure you protect this half of the pendant.",
  ui_story_5046_50460901_122_dialog_content = "This pendant symbolizes how much your dad and I love you. We'll always protect you, Hati.",
  ui_story_5046_50460901_123_dialog_content = "Live a good life. Mom loves you...",
  ui_story_5046_50460901_124_dialog_content = "Mom!?",
  ui_story_5046_50460901_125_dialog_content = "Urgh!",
  ui_story_5046_50460901_126_dialog_content = "(Why did Mom push me into the fireplace!?)",
  ui_story_5046_50460901_127_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5046_50460901_128_dialog_content = "(Is someone here!? Who is it? No one has ever entered the house before!)",
  ui_story_5046_50460901_129_dialog_content = "It wasn't easy tracking you down, Catherine Kelp. Do you really think you can escape?",
  ui_story_5046_50460901_130_dialog_content = "... Zenas.",
  ui_story_5046_50460901_131_dialog_content = "Tsk, this house is so dark. Why isn't there any light in here?",
  ui_story_5046_50460901_132_dialog_content = "A lady of luxury living in a house like this? It seems life hasn't been very good to you lately.",
  ui_story_5046_50460901_133_dialog_content = "However shabby the house I live in may be, as long as you're dead, I'll live very well indeed.",
  ui_story_5046_50460901_134_dialog_content = "Shh—a fine lady never speaks such foul things.",
  ui_story_5046_50460901_135_dialog_content = "Enough nonsense.",
  ui_story_5046_50460901_136_dialog_content = "I must kill you today... to avenge Fenrir.",
  ui_story_5046_50460901_137_dialog_content = "(Fenrir? That's my dad's name! Did this man kill my dad!?)",
  ui_story_5046_50460901_138_dialog_content = "You overestimate your ability.",
  ui_story_5046_50460901_139_dialog_content = "Gasp... gasp...",
  ui_story_5046_50460901_140_dialog_content = "Catherine, just hand over the pendant and I'll spare your life.",
  ui_story_5046_50460901_141_dialog_content = "Over my dead body...",
  ui_story_5046_50460901_142_dialog_content = "How stubborn. If you really wish to die, I will oblige you.",
  ui_story_5046_50460901_143_dialog_content = "(Mom!)",
  ui_story_5046_50460901_144_dialog_content = "Hyaa—!",
  ui_story_5046_50460901_145_dialog_content = "(The fire!? Mom was the one who started it?)",
  ui_story_5046_50460901_146_dialog_content = "Argh! How did this fire spread so quickly?",
  ui_story_5046_50460901_147_dialog_content = "This was your plan, Catherine?",
  ui_story_5046_50460901_148_dialog_content = "You won't leave here alive...",
  ui_story_5046_50460901_149_dialog_content = "Let me go! You want me to be burned to a crisp here with you!?",
  ui_story_5046_50460901_150_dialog_content = "As long as I avenge Fenrir...",
  ui_story_5046_50460901_151_dialog_content = "Aaaaah!",
  ui_story_5046_50460901_152_dialog_content = "(Mom! Mom's still looking at me...)",
  ui_story_5046_50460901_153_dialog_content = "...",
  ui_story_5046_50460901_154_dialog_content = "(Mom's saying... don't come out?)",
  ui_story_5046_50460901_155_dialog_content = "(Mom!? Mom's not moving!?)",
  ui_story_5046_50460901_156_dialog_content = "(Mom—!)",
  ui_story_5046_50460901_157_dialog_content = "Hmph, didn't even break a sweat.",
  ui_story_5046_50460901_158_dialog_content = "(Waaaaah... Mom...)",
  ui_story_5046_50460901_159_dialog_content = "(The man is searching Mom for something...)",
  ui_story_5046_50460901_160_dialog_content = "(I need to go out there and kill him... to avenge my mom!)",
  ui_story_5046_50460901_161_dialog_content = "(No, Mom just told me not to go out...)",
  ui_story_5046_50460901_162_dialog_content = "It's so hot in here... Where did she hide that thing!?",
  ui_story_5046_50460901_163_dialog_content = "...",
  ui_story_5046_50460901_164_dialog_content = "Finally found it. My face stings, is it burned?",
  ui_story_5046_50460901_165_dialog_content = "Fire! Fire!",
  ui_story_5046_50460901_166_dialog_content = "I can't let anyone see me.",
  ui_story_5046_50460901_167_dialog_content = "(He's gone... Mom isn't moving anymore...)",
  ui_story_5046_50460901_168_dialog_content = "(Mom...)",
  ui_story_5046_50460901_169_dialog_content = "That fire was outta control, but we finally managed to put it out...",
  ui_story_5046_50460901_170_dialog_content = "They found Catherine, but she'd already stopped breathing...",
  ui_story_5046_50460901_171_dialog_content = "A fire like that'll choke ya to death, even if the flames never touch ya...",
  ui_story_5046_50460901_172_dialog_content = "If you have nothing nice to say, just say nothing.",
  ui_story_5046_50460901_173_dialog_content = "Hmph.",
  ui_story_5046_50460901_174_dialog_content = "Help clean this place up if you have nothing to do.",
  ui_story_5046_50460901_175_dialog_content = "I know, I know.",
  ui_story_5046_50460901_176_dialog_content = "Get over here! There's a kid in the fireplace!",
  ui_story_5046_50460901_177_dialog_content = "I've never heard Catherine mention she had a kid...",
  ui_story_5046_50460901_178_dialog_content = "And the kid's not hurt one bit, despite those raging flames...",
  ui_story_5046_50460901_179_dialog_content = "Sigh... She blocked up the windows and lit candles in the room during the daytime.",
  ui_story_5046_50460901_180_dialog_content = "It was only a matter of time before this happened. See?",
  ui_story_5046_50460901_181_dialog_content = "Come on, stop being so morbid. The most important question right now is—what do we do with this kid?",
  ui_story_5046_50460901_182_dialog_content = "Take her to the orphanage?",
  ui_story_5046_50460901_183_dialog_content = "I guess that's all we can do.",
  ui_story_5046_50460901_184_dialog_content = "I have other questions.",
  ui_story_5046_50461001_1_dialog_content = "She seems to be calming down.",
  ui_story_5046_50461001_2_dialog_content = "Thank you, Kristen.",
  ui_story_5046_50461001_3_dialog_content = "For what?",
  ui_story_5046_50461001_4_dialog_content = "Thank you, that you wait for Hati to regain her memory.",
  ui_story_5046_50461001_5_dialog_content = "You don't think Hati is the culprit either, do you?",
  ui_story_5046_50461001_6_dialog_content = "After conducting a thorough investigation, I certainly suspect Hati less.",
  ui_story_5046_50461001_7_dialog_content = "Although these cases are all related to Hati, and every clue points to her.",
  ui_story_5046_50461001_8_dialog_content = "But there are still many contradictions yet to be resolved.",
  ui_story_5046_50461001_9_dialog_content = "You're really putting your all into this case, Kristen.",
  ui_story_5046_50461001_10_dialog_content = "Mr. Zenas taught me that we should take every case seriously and never leave a single clue behind.",
  ui_story_5046_50461001_11_dialog_content = "But he was still unwilling to let me take on this case...",
  ui_story_5046_50461001_12_dialog_content = "So, Kristen, you've been investigating this case in secret?",
  ui_story_5046_50461001_13_dialog_content = "Yes...",
  ui_story_5046_50461001_14_dialog_content = "Speaking of which, PlayerName, why did you run off with Hati? She's been holding you against your will.",
  ui_story_5046_50461001_15_dialog_content = "I believe she's innocent, and with everything that's happened, her emotions have been very unstable.",
  ui_story_5046_50461001_16_dialog_content = "She needed my help, so I asked her to take me with her.",
  ui_story_5046_50461001_17_dialog_content = "You established such a strong bond of trust with each other in such a short time...?",
  ui_story_5046_50461001_18_dialog_content = "<size=30>If only Mr. Zenas could trust me so much...</size>",
  ui_story_5046_50461001_19_dialog_content = "How did you find this place?",
  ui_story_5046_50461001_20_dialog_content = "A local showed me the way.",
  ui_story_5046_50461001_21_dialog_content = "It's not far from the orphanage, but it's still part of Umbraton. Many, many years ago, the locals here lived very hard lives.",
  ui_story_5046_50461001_22_dialog_content = "The year of the orphanage fire, Istvan won the hearts of a great many people after he took it upon himself to ameliorate the situation.",
  ui_story_5046_50461001_23_dialog_content = "After becoming the Shadowlord, Istvan asked the people here to move to Umbraton.",
  ui_story_5046_50461001_24_dialog_content = "It was actually the very same man who delivered Hati to the orphanage, which led me here.",
  ui_story_5046_50461001_25_dialog_content = "He said a fire broke out in this town before, and Hati was found in the rubble after the fire was extinguished.",
  ui_story_5046_50461001_26_dialog_content = "The woman who lived here died.",
  ui_story_5046_50461001_27_dialog_content = "But the locals never heard the woman mention that she had a child, so they didn't know what to do.",
  ui_story_5046_50461001_28_dialog_content = "Finally, they decided to send the child to the orphanage. That child was Hati.",
  ui_story_5046_50461001_29_dialog_content = "So that's it...",
  ui_story_5046_50461001_30_dialog_content = "Amazing work, Kristen. You found out so much with just a few clues to go on.",
  ui_story_5046_50461001_31_dialog_content = "Ahem! It really doesn't matter how much you praise me, I'll bring you back with me to cooperate with the investigation.",
  ui_story_5046_50461001_32_dialog_content = "I believe from the bottom of my heart that you're truly amazing! I know you'll be a terrific judge in the future!",
  ui_story_5046_50461001_33_dialog_content = "If only he thought the same...",
  ui_story_5046_50461001_34_dialog_content = "Mr. Zenas?",
  ui_story_5046_50461001_35_dialog_content = "Yes... Mr. Zenas was injured using Luminatics to put out the fire, but even after this, Mr. Hamell was killed...",
  ui_story_5046_50461001_36_dialog_content = "He no longer has any faith in me.",
  ui_story_5046_50461001_37_dialog_content = "I think you've done really well, Kristen.",
  ui_story_5046_50461001_38_dialog_content = "Although we've only had the chance to meet each other a few times, I can sense you're a conscientious, patient, and kind judge.",
  ui_story_5046_50461001_39_dialog_content = "D-Don't think your honeyed words can turn me...",
  ui_story_5046_50461001_40_dialog_content = "I received extensive professional training from the Lumo Hall of Justice! My belief in justice will never be shaken by the likes of you!",
  ui_story_5046_50461001_41_dialog_content = "I just said what I wanted to say! I didn't mean anything else by it!",
  ui_story_5046_50461001_42_dialog_content = "If Hati had really done those things, I would have made her confess.",
  ui_story_5046_50461001_43_dialog_content = "But if she didn't do anything, you can't just frame her!",
  ui_story_5046_50461001_44_dialog_content = "R-Right! That's the meaning of justice!",
  ui_story_5046_50461001_45_dialog_content = "You should try to believe in yourself and stop worrying about what other people think.",
  ui_story_5046_50461001_46_dialog_content = "Especially considering how amazing you are!",
  ui_story_5046_50461001_47_dialog_content = "...",
  ui_story_5046_50461001_48_dialog_content = "Has anyone ever told you that you're quite good at making girls happy?",
  ui_story_5046_50461001_49_dialog_content = "Huh? I make girls happy?",
  ui_story_5046_50461001_50_dialog_content = "Vice is always hating on me for spending money and making her worry about the Colossus' expenses every day.",
  ui_story_5046_50461001_51_dialog_content = "You'd be better off saying I always cause trouble for the girls.",
  ui_story_5046_50461001_52_dialog_content = "<size=45>Graaaaaah—</size>",
  ui_story_5046_50461001_53_dialog_content = "Was that an Eclipsite? It sounds like there's more than one.",
  ui_story_5046_50461001_54_dialog_content = "This place has been deserted for so long. It's only to be expected that Eclipsites would haunt this area.",
  ui_story_5046_50461001_55_dialog_content = "But Hati hasn't woken up yet. I'm afraid it might be dangerous to bring her out here now.",
  ui_story_5046_50461001_56_dialog_content = "Don't worry, it's just a few Eclipsites. I'll judge them on the spot!",
  ui_story_5046_50461002_1_dialog_content = "Phew—",
  ui_story_5046_50461002_2_dialog_content = "The Eclipsite aura around here has finally dissipated.",
  ui_story_5046_50461002_3_dialog_content = "Thank you, Kristen.",
  ui_story_5046_50461002_4_dialog_content = "I see now just how powerful the Caelestites are.",
  ui_story_5046_50461002_5_dialog_content = "Were it not for you, those Eclipsites' sneak attacks may have been successful.",
  ui_story_5046_50461002_6_dialog_content = "PlayerName...",
  ui_story_5046_50461002_7_dialog_content = "Hati! Hati's awake!",
  ui_story_5046_50461002_8_dialog_content = "Now that you're awake, you must come back with me for interrogation. Before the investigation results come out...",
  ui_story_5046_50461002_9_dialog_content = "It was Zenas...",
  ui_story_5046_50461002_10_dialog_content = "My mentor?",
  ui_story_5046_50461002_11_dialog_content = "PlayerName... I remember everything.",
  ui_story_5046_50461002_12_dialog_content = "That night, my mom pushed me into the fireplace to protect me.",
  ui_story_5046_50461002_13_dialog_content = "She faced Zenas alone... Yes, that man's name was Zenas.",
  ui_story_5046_50461002_14_dialog_content = "He killed my mom and stole her pendant from her.",
  ui_story_5046_50461002_15_dialog_content = "I must retrieve the pendant.",
  ui_story_5046_50461002_16_dialog_content = "My mentor? What does this have to do with my mentor?",
  ui_story_5046_50461002_17_dialog_content = "Zenas is the murderer.",
  ui_story_5046_50461002_18_dialog_content = "Nonsense!",
  ui_story_5046_50461002_19_dialog_content = "If you dare disrespect Mr. Zenas again, don't blame me for what I do next!",
  ui_story_5046_50461002_20_dialog_content = "A killer is a killer, and he's the one.",
  ui_story_5046_50461002_21_dialog_content = "Zenas broke into my house that night, killed my mom, and stole my pendant.",
  ui_story_5046_50461002_22_dialog_content = "I saw it all with my own eyes! I need to kill him to avenge my mom!",
  ui_story_5046_50461002_23_dialog_content = "How can you say my mentor murdered your mother!?",
  ui_story_5046_50461002_24_dialog_content = "You only just remembered this incident, and it has been so long.",
  ui_story_5046_50461002_25_dialog_content = "How can you be sure that your memory isn't wrong? And how do I know you're not lying?",
  ui_story_5046_50461002_26_dialog_content = "I know I'm not wrong...",
  ui_story_5046_50461002_27_dialog_content = "With the burns on his face and my mom's pendant...",
  ui_story_5046_50461002_28_dialog_content = "I'm certain he's the murderer!",
  ui_story_5046_50461002_29_dialog_content = "I'm sorry, but my mentor suffered a burn on his face when he was saving me.",
  ui_story_5046_50461002_30_dialog_content = "That evening, my parents went out to a banquet.",
  ui_story_5046_50461002_31_dialog_content = "I remember it growing dark very early that day... As soon as I saw my parents off, it grew dark.",
  ui_story_5046_50461002_32_dialog_content = "I went back to my room to read by myself.",
  ui_story_5046_50461002_33_dialog_content = "Suddenly, a huge fire broke out somewhere. My parents were not at home, and the smoke grew thicker, I just stood there crying loudly.",
  ui_story_5046_50461002_34_dialog_content = "Luckily, Mr. Zenas shouted my name and followed my sobs to find me...",
  ui_story_5046_50461002_35_dialog_content = "As we were escaping, Mr. Zenas held me tightly in his arms, and I didn't suffer any injuries except for being choked by the heavy smoke.",
  ui_story_5046_50461002_36_dialog_content = "But Mr. Zenas... Half of his face was burned.",
  ui_story_5046_50461002_37_dialog_content = "So, Zenas's face was burned while rescuing Kristen.",
  ui_story_5046_50461002_38_dialog_content = "...",
  ui_story_5046_50461002_39_dialog_content = "Hati, do you remember the day Zenas attacked?",
  ui_story_5046_50461002_40_dialog_content = "August 26th. It was... my birthday.",
  ui_story_5046_50461002_41_dialog_content = "August 26th!?",
  ui_story_5046_50461002_42_dialog_content = "The day Mr. Zenas saved me was also August 26th.",
  ui_story_5046_50461002_43_dialog_content = "That day... I remember it very clearly.",
  ui_story_5046_50461002_44_dialog_content = "It seems these two events took place on the same day...",
  ui_story_5046_50461002_45_dialog_content = "Just now, Kristen said that her manor caught fire that night, which means Zenas appeared at Kristen's house at night time.",
  ui_story_5046_50461002_46_dialog_content = "But Hati also said Zenas attacked at night.",
  ui_story_5046_50461002_47_dialog_content = "In other words, Zenas appeared in two different places at the same time on the same day.",
  ui_story_5046_50461002_48_dialog_content = "When you look at it that way, it's impossible. You must be mistaken, Hati.",
  ui_story_5046_50461002_49_dialog_content = "How do you explain the pendant?",
  ui_story_5046_50461002_50_dialog_content = "Why would the pendant my mom ask me to take care of be in his hands?",
  ui_story_5046_50461002_51_dialog_content = "It was precisely because of this pendant that I recognized him.",
  ui_story_5046_50461002_52_dialog_content = "The pendant you mentioned is my mentor's family heirloom.",
  ui_story_5046_50461002_53_dialog_content = "The pattern on the pendant is the family crest of a noble Lumopolis family that sadly fell over a decade ago.",
  ui_story_5046_50461002_54_dialog_content = "The day my mentor rescued me from the fire, my father wished to express his gratitude for saving my life and he asked him about his background.",
  ui_story_5046_50461002_55_dialog_content = "My mentor took out that pendant and said he was originally a noble, but he had to wander around without hope because his family declined.",
  ui_story_5046_50461002_56_dialog_content = "My father sympathized with him, being a fellow noble, and asked my mentor to stay on and serve our family.",
  ui_story_5046_50461002_57_dialog_content = "I remember clearly that the pendant belonged to my mom.",
  ui_story_5046_50461002_58_dialog_content = "He must have taken my mom's pendant and passed it off as his own!",
  ui_story_5046_50461002_59_dialog_content = "You! Your inferences cannot be deemed true until you have evidence.",
  ui_story_5046_50461002_60_dialog_content = "(Hati mentioned earlier that her mother kept the house tightly guarded against daylight and lit it with candles.)",
  ui_story_5046_50461002_61_dialog_content = "(So, perhaps Hati isn't sure whether it was day or night when the incident occurred!)",
  ui_story_5046_50461002_62_dialog_content = "Hati, can you be sure the murderer broke into your house at night?",
  ui_story_5046_50461002_63_dialog_content = "I-I remember candles lit the room. It should have been night.",
  ui_story_5046_50461002_64_dialog_content = "That's the thing.",
  ui_story_5046_50461002_65_dialog_content = "Because candles often lit up your home, of course you'd think—",
  ui_story_5046_50461002_66_dialog_content = "\"Because I saw lit candles, the incident occurred at night.\"",
  ui_story_5046_50461002_67_dialog_content = "But in fact, candles were lit in your house both day and night, so it would be wrong to use lit candles to judge the time.",
  ui_story_5046_50461002_68_dialog_content = "I propose that the time Hati's home was attacked was actually daytime.",
  ui_story_5046_50461002_69_dialog_content = "So, that's it...",
  ui_story_5046_50461002_70_dialog_content = "Kristen can accurately recall her parents attending a banquet in the evening and remembers that it grew dark early that day.",
  ui_story_5046_50461002_71_dialog_content = "So the fire at Kristen's house really took place at night.",
  ui_story_5046_50461002_72_dialog_content = "According to this deduction, the suspect attacked Hati's home during the day and rushed to Kristen's house at night to extinguish the fire.",
  ui_story_5046_50461002_73_dialog_content = "Therefore, there's no instance of one person appearing in two different places at the same time.",
  ui_story_5046_50461002_74_dialog_content = "Brilliant reasoning...",
  ui_story_5046_50461002_75_dialog_content = "But we still need some more information. How long does it take to get from here to your vacation manor?",
  ui_story_5046_50461002_76_dialog_content = "I took note of this on my way here. It's not far from my manor.",
  ui_story_5046_50461002_77_dialog_content = "Was it really... my mentor? No, it's impossible...",
  ui_story_5046_50461002_78_dialog_content = "If you wish to determine whether Zenas was the attacker, just ask him to show you his pendant.",
  ui_story_5046_50461002_79_dialog_content = "Hati said that these two pendants were a matching pair.",
  ui_story_5046_50461002_80_dialog_content = "If Zenas did not attack Hati's family and, as he said, he's indeed a fallen noble...",
  ui_story_5046_50461002_81_dialog_content = "Then his pendant won't match the one in Hati's hand.",
  ui_story_5046_50461002_82_dialog_content = "But if these two pendants fit together perfectly...",
  ui_story_5046_50461002_83_dialog_content = "Then he must be the culprit.",
  ui_story_5046_50461002_84_dialog_content = "No, my mentor can't be a murderer!",
  ui_story_5046_50461002_85_dialog_content = "Oh yes, that's right! Motive!",
  ui_story_5046_50461002_86_dialog_content = "No enmity existed between your family and my mentor, so why would he hunt down and kill your parents?",
  ui_story_5046_50461002_87_dialog_content = "My mom told me that a mysterious organization wanted my dad's power, and they wanted to catch him to use him in their experiments.",
  ui_story_5046_50461002_88_dialog_content = "In my memory, my mom wanted to avenge my dad, and lost her life trying to kill Zenas...",
  ui_story_5046_50461002_89_dialog_content = "So, Zenas is a member of that mysterious organization.",
  ui_story_5046_50461002_90_dialog_content = "I don't believe it!",
  ui_story_5046_50461002_91_dialog_content = "No, there's no way!",
  ui_story_5046_50461002_92_dialog_content = "Kristen, calm down.",
  ui_story_5046_50461002_93_dialog_content = "Whether Zenas is the culprit or not can be determined by simply putting his pendant and Hati's together.",
  ui_story_5046_50461002_94_dialog_content = "Ask him to hand over his pendant.",
  ui_story_5046_50461002_95_dialog_content = "If he refuses to hand it over, I'll beat him to a pulp and grab it from him.",
  ui_story_5046_50461002_96_dialog_content = "We can't use violence! Umbraton is full of soldiers searching for you. It'll be difficult for us to confront Zenas and discuss this with him.",
  ui_story_5046_50461002_97_dialog_content = "...",
  ui_story_5046_50461002_98_dialog_content = "I can help you.",
  ui_story_5046_50461002_99_dialog_content = "As PlayerName said, confirming whether the pendants fit together is the easiest way to prove my mentor's innocence.",
  ui_story_5046_50461002_100_dialog_content = "So I'll help you to meet my mentor without any other soldiers.",
  ui_story_5046_50461002_101_dialog_content = "However, you must also promise me that if the pendants do not fit together, you will fully cooperate with the investigation.",
  ui_story_5046_50461002_102_dialog_content = "So, you believe us?",
  ui_story_5046_50461002_103_dialog_content = "I didn't say that.",
  ui_story_5046_50461002_104_dialog_content = "But I've learned a lot from the serious investigation attitude PlayerName has towards this incident.",
  ui_story_5046_50461002_105_dialog_content = "I want to reexamine this case more carefully.",
  ui_story_5046_50461002_106_dialog_content = "It's getting late. Let's hurry back to Umbraton.",
  ui_story_5046_50461101_1_dialog_content = "Miss Kristen, you're back.",
  ui_story_5046_50461101_2_dialog_content = "Just call me Kristen.",
  ui_story_5046_50461101_3_dialog_content = "Where's Captain Zenas? Why can't I find him?",
  ui_story_5046_50461101_4_dialog_content = "Captain Zenas took several people to the orphanage.",
  ui_story_5046_50461101_5_dialog_content = "The orphanage? What's the captain doing there?",
  ui_story_5046_50461101_6_dialog_content = "Erm... He didn't say.",
  ui_story_5046_50461101_7_dialog_content = "Alright, carry on.",
  ui_story_5046_50461101_8_dialog_content = "We couldn't find anything, sir.",
  ui_story_5046_50461101_9_dialog_content = "Keep looking. Anything you find, you give it straight to me, understand?",
  ui_story_5046_50461101_10_dialog_content = "Reporting in!",
  ui_story_5046_50461101_11_dialog_content = "Did you find anything?",
  ui_story_5046_50461101_12_dialog_content = "No, but Miss Kristen is here. She wants to see you.",
  ui_story_5046_50461101_13_dialog_content = "What is she doing here?",
  ui_story_5046_50461101_14_dialog_content = "Sir.",
  ui_story_5046_50461101_15_dialog_content = "Please leave us be. I want to speak with Captain Zenas in private.",
  ui_story_5046_50461101_16_dialog_content = "Yes, miss.",
  ui_story_5046_50461101_17_dialog_content = "Kristen? What are you doing here?",
  ui_story_5046_50461101_18_dialog_content = "Aren't you supposed to be presenting the case at the Lumo Hall of Justice?",
  ui_story_5046_50461101_19_dialog_content = "Before returning to Lumopolis, I wanted to ask you something.",
  ui_story_5046_50461101_20_dialog_content = "Can I borrow your pendant?",
  ui_story_5046_50461101_21_dialog_content = "My pendant?",
  ui_story_5046_50461101_22_dialog_content = "You once showed me a pendant with your family emblem upon it.",
  ui_story_5046_50461101_23_dialog_content = "Why do you want to see it?",
  ui_story_5046_50461101_24_dialog_content = "Hmm...",
  ui_story_5046_50461101_25_dialog_content = "I saw a pattern similar to your family emblem while going through my files, so I wanted to take another look at your pendant, just to be certain.",
  ui_story_5046_50461101_26_dialog_content = "...",
  ui_story_5046_50461101_27_dialog_content = "Kristen, I watched you grow up. I can tell in an instant when you're lying.",
  ui_story_5046_50461101_28_dialog_content = "Sir...",
  ui_story_5046_50461101_29_dialog_content = "Come on, what's the reason?",
  ui_story_5046_50461101_30_dialog_content = "Well, actually... I actually want to prove your innocence with that pendant.",
  ui_story_5046_50461101_31_dialog_content = "Prove my innocence?",
  ui_story_5046_50461101_32_dialog_content = "I learned that you might be related to an arson case many years ago.",
  ui_story_5046_50461101_33_dialog_content = "The pendant you always wear is the key to eliminating all suspicion surrounding you.",
  ui_story_5046_50461101_34_dialog_content = "What is the relationship between my pendant and this arson case?",
  ui_story_5046_50461101_35_dialog_content = "I was told that your pendant is part of a pair and matches the pendant I have here in my hand.",
  ui_story_5046_50461101_36_dialog_content = "All I need is for you to lend me the pendant and let me confirm whether the two pendants can be combined...",
  ui_story_5046_50461101_37_dialog_content = "If you're holding onto something related to the case, you should hand it over to the relevant personnel for detailed examination.",
  ui_story_5046_50461101_38_dialog_content = "Directly questioning your superior with evidence... Kristen, have I taught you nothing all these years?",
  ui_story_5046_50461101_39_dialog_content = "If you don't want to hand it over, we have other ways of making you cooperate.",
  ui_story_5046_50461101_40_dialog_content = "Hati?",
  ui_story_5046_50461101_41_dialog_content = "Kristen, since you've caught the suspect, why don't you just put her in jail where she belongs?",
  ui_story_5046_50461101_42_dialog_content = "Because Hati isn't a suspect, the arson cases in Umbraton and Mr. Hamell's death have nothing to do with her.",
  ui_story_5046_50461101_43_dialog_content = "I see... So, that's it.",
  ui_story_5046_50461101_44_dialog_content = "Kristen, you actually harbored a suspect and conspired with her to deceive your superior!?",
  ui_story_5046_50461101_45_dialog_content = "I... I didn't...",
  ui_story_5046_50461101_46_dialog_content = "She just wanted to borrow your pendant... Don't you think your reaction seems a tad too extreme?",
  ui_story_5046_50461101_47_dialog_content = "Could it be because... you're guilty?",
  ui_story_5046_50461101_48_dialog_content = "You took advantage of the fact that candles were lit in Hati's house day and night to create an alibi for yourself, and you used Kristen as your witness!",
  ui_story_5046_50461101_49_dialog_content = "After you committed murder at Hati's house, you set fire to Kristen's manor not far away.",
  ui_story_5046_50461101_50_dialog_content = "You pretended to be passing by and ran in to save whoever was inside, creating the illusion that the burn on your face resulted from your heroism!",
  ui_story_5046_50461101_51_dialog_content = "But in fact, the ugly truth is that the burn on your face resulted from the fight with Hati's mother, who started a fire in an attempt to make sure you perished with her!",
  ui_story_5046_50461101_52_dialog_content = "Hmph. Is this the story you made up to frame me? It's very exciting.",
  ui_story_5046_50461101_53_dialog_content = "This is my take on the case based on the information available.",
  ui_story_5046_50461101_54_dialog_content = "Kristen, is this what you also believe?",
  ui_story_5046_50461101_55_dialog_content = "Sir... I...",
  ui_story_5046_50461101_56_dialog_content = "PlayerName's deduction...",
  ui_story_5046_50461101_57_dialog_content = "I...",
  ui_story_5046_50461101_58_dialog_content = "...",
  ui_story_5046_50461101_59_dialog_content = "Hahahahahaha!",
  ui_story_5046_50461101_60_dialog_content = "Kristen, my lady... you really are something else.",
  ui_story_5046_50461101_61_dialog_content = "You'd rather believe a Caelestite you've only known a day than your very own mentor.",
  ui_story_5046_50461101_62_dialog_content = "Why won't you let us see the pendant...?",
  ui_story_5046_50461101_63_dialog_content = "Clearly, all you need to do is show it to me to dispel my doubts...",
  ui_story_5046_50461101_64_dialog_content = "Since the seeds of doubt have already been sown in your heart, what's the point?",
  ui_story_5046_50461101_65_dialog_content = "Whether I give it to you or not, you have already reached a verdict.",
  ui_story_5046_50461101_66_dialog_content = "No, that's not true at all! All deductions require evidence to prove their veracity...",
  ui_story_5046_50461101_67_dialog_content = "Okay, say no more.",
  ui_story_5046_50461101_68_dialog_content = "In the future, do not refer to me as your mentor.",
  ui_story_5046_50461101_69_dialog_content = "Since you have chosen to associate with this suspect, the tip of my sword now points toward you.",
  ui_story_5046_50461101_70_dialog_content = "Sir... What is the meaning of this?",
  ui_story_5046_50461101_71_dialog_content = "Kristen, you have to trust your own judgment!",
  ui_story_5046_50461101_72_dialog_content = "He's trying to blackmail you emotionally! It doesn't matter whether he's your mentor or not—you have to hold onto the sense of justice in your heart!",
  ui_story_5046_50461101_73_dialog_content = "This is who you are, Kristen—a probationary judge of Lumopolis!",
  ui_story_5046_50461101_74_dialog_content = "I...",
  ui_story_5046_50461101_75_dialog_content = "Guards! Kristen has colluded with the Caelestite to harbor the suspect, Hati. Arrest them all!",
  ui_story_5046_50461101_76_dialog_content = "Sir!",
  ui_story_5046_50461102_1_dialog_content = "Gasp... gasp...",
  ui_story_5046_50461102_2_dialog_content = "I can't believe you defeated all my guards...",
  ui_story_5046_50461102_3_dialog_content = "According to the laws of the Hall of Justice, what do we do with those who resist arrest and attack Lumo Guards?",
  ui_story_5046_50461102_4_dialog_content = "Well, Kristen?",
  ui_story_5046_50461102_5_dialog_content = "Sir, please cooperate with the investigation...",
  ui_story_5046_50461102_6_dialog_content = "Once the investigation is concluded, your innocence will be proven and everything can return to how it was...",
  ui_story_5046_50461102_7_dialog_content = "Alright.",
  ui_story_5046_50461102_8_dialog_content = "Huh!? You agree!?",
  ui_story_5046_50461102_9_dialog_content = "(He was so adamant not to give in a moment ago... Why did he suddenly agree?)",
  ui_story_5046_50461102_10_dialog_content = "Hand over the pendant, quickly!",
  ui_story_5046_50461102_11_dialog_content = "He killed my mom... He has to pay for what he did!",
  ui_story_5046_50461102_12_dialog_content = "I will avenge my parents! I'll kill him!",
  ui_story_5046_50461102_13_dialog_content = "Calm down, Hati!",
  ui_story_5046_50461102_14_dialog_content = "You can count on Kristen to investigate this whole matter.",
  ui_story_5046_50461102_15_dialog_content = "If you were to use violence to resolve things, you'd become a murderer for real!",
  ui_story_5046_50461102_16_dialog_content = "The Hati I know is a gentle and kind child whose parents love her!",
  ui_story_5046_50461102_17_dialog_content = "Your parents wouldn't want you to avenge them in this way!",
  ui_story_5046_50461102_18_dialog_content = "Really... Mom and Dad wouldn't want me to...?",
  ui_story_5046_50461102_19_dialog_content = "... Hmn.",
  ui_story_5046_50461102_20_dialog_content = "I can hand over the pendant, but I'll need to return to Umbraton first and prove my innocence in front of everyone.",
  ui_story_5046_50461102_21_dialog_content = "Let's go, Kristen.",
  ui_story_5046_50461102_22_dialog_content = "When we return to Umbraton, I will prove my innocence, and then we can go back to how things were...",
  ui_story_5046_50461102_23_dialog_content = "Hmn...",
  ui_story_5046_50461102_24_dialog_content = "Don't any of you move, or I'll break her neck.",
  ui_story_5046_50461102_25_dialog_content = "Sir!? Why...",
  ui_story_5046_50461102_26_dialog_content = "What do you think you're doing? Let go of Kristen!",
  ui_story_5046_50461102_27_dialog_content = "While in pursuit of the suspect Hati, the suspect resisted arrest, and Kristen, unfortunately, died in the line of duty...",
  ui_story_5046_50461102_28_dialog_content = "You're insane!",
  ui_story_5046_50461102_29_dialog_content = "As long as Kristen dies, I'll be the only one who knows what actually happened here today.",
  ui_story_5046_50461102_30_dialog_content = "I'll submit a report to the Hall of Justice, and Hati will be branded a ruthless murderer and arsonist!",
  ui_story_5046_50461102_31_dialog_content = "And you, Caelestite, you will become her accomplice!",
  ui_story_5046_50461102_32_dialog_content = "By that time, no one will believe a single thing you say.",
  ui_story_5046_50461102_33_dialog_content = "Do you really think you can cover up the truth!?",
  ui_story_5046_50461102_34_dialog_content = "You actually think you alone can frame us with your lies!?",
  ui_story_5046_50461102_35_dialog_content = "Truth, lies... What does it matter in the end?",
  ui_story_5046_50461102_36_dialog_content = "The important thing is that I continue my life as a knight, safe in Lumopolis, without further incident...",
  ui_story_5046_50461102_37_dialog_content = "As for the truth... it'll be buried with your bones, deep in the earth forever!",
  ui_story_5046_50461102_38_dialog_content = "Sir... How can you say that?",
  ui_story_5046_50461102_39_dialog_content = "Didn't you always teach me to uphold justice and fight for the truth? Why? Why would you say such a thing...?",
  ui_story_5046_50461102_40_dialog_content = "Kristen, do you consider me an important person in your heart?",
  ui_story_5046_50461102_41_dialog_content = "Ahh!",
  ui_story_5046_50461102_42_dialog_content = "Since I mean so much to you, wouldn't you go to any lengths to maintain my reputation and position, even if it meant dying for me?",
  ui_story_5046_50461102_43_dialog_content = "Sir... Sir, what are you saying...?",
  ui_story_5046_50461102_44_dialog_content = "You risked your life to save Kristen all those years ago! How can you be so cruel as to threaten to kill her?!",
  ui_story_5046_50461102_45_dialog_content = "(Hati! I'm talking to you using my psychic ability! We need to find a way to save Kristen!)",
  ui_story_5046_50461102_46_dialog_content = "PlayerName?",
  ui_story_5046_50461102_47_dialog_content = "(I'll distract Zenas, you find an opportunity to sneak up on him!)",
  ui_story_5046_50461102_48_dialog_content = "Got it.",
  ui_story_5046_50461102_49_dialog_content = "I saved her? You mean that fire? I suppose she owes me even more, then. Now she has a chance to repay me.",
  ui_story_5046_50461102_50_dialog_content = "Unless my previous deduction was all wrong, you risked your life to rush into the flames and save Kristen...",
  ui_story_5046_50461102_51_dialog_content = "So how can you even think of hurting her now!?",
  ui_story_5046_50461102_52_dialog_content = "Yes, the little girl I sacrificed my life to save and taught for so many years...",
  ui_story_5046_50461102_53_dialog_content = "How could I bring myself to hurt her?",
  ui_story_5046_50461102_54_dialog_content = "Sir...",
  ui_story_5046_50461102_55_dialog_content = "But Kristen, my young lady...",
  ui_story_5046_50461102_56_dialog_content = "From the very beginning, you were just a pawn to me.",
  ui_story_5046_50461102_57_dialog_content = "And that includes the fire. It was all part of my plan.",
  ui_story_5046_50461102_58_dialog_content = "What!?",
  ui_story_5046_50461102_59_dialog_content = "I had long wanted to climb onto the back of a powerful noble and enter Lumopolis society. Your manor just happened to be nearby.",
  ui_story_5046_50461102_60_dialog_content = "I quickly learned that everyone working at the manor that day was a feeble nincompoop, so I bribed the help and set fire to the place.",
  ui_story_5046_50461102_61_dialog_content = "I pretended to be passing by and made out as though I was desperately risking life and limb to rescue this poor noble lady of Lumopolis.",
  ui_story_5046_50461102_62_dialog_content = "Sure enough, her family was very grateful to me, allowing me to smoothly enter Lumopolis society and live the life I had always dreamt of.",
  ui_story_5046_50461102_63_dialog_content = "It was all thanks to you, my... no, Kristen.",
  ui_story_5046_50461102_X63_dialog_content = "Look, I got my face burned to save you!",
  ui_story_5046_50461102_64_dialog_content = "You... You're abominable! I won't spare you!",
  ui_story_5046_50461102_65_dialog_content = "Was it worth disfiguring yourself just to ingratiate yourself with the Lumopolis nobility?",
  ui_story_5046_50461102_66_dialog_content = "Have you ever tasted power, Caelestite?",
  ui_story_5046_50461102_67_dialog_content = "Power can be traded for money, but money does not necessarily buy power.",
  ui_story_5046_50461102_68_dialog_content = "As long as you have power, nothing is beyond your reach, and no one can stand in your way!",
  ui_story_5046_50461102_69_dialog_content = "Isn't that right, Kristen?",
  ui_story_5046_50461102_70_dialog_content = "You were born a noble of Lumopolis. It must be a wonderful feeling, no?",
  ui_story_5046_50461102_71_dialog_content = "Uneasy lies the head that wears a crown...",
  ui_story_5046_50461102_72_dialog_content = "Nobles should possess a noble character.",
  ui_story_5046_50461102_73_dialog_content = "Those who use their noble status for personal gain are not worthy of being called nobles.",
  ui_story_5046_50461102_74_dialog_content = "Hahahahaha!",
  ui_story_5046_50461102_75_dialog_content = "Kristen, you really believed every little empty cliche I taught you, didn't you?",
  ui_story_5046_50461102_76_dialog_content = "Do you really believe that all nobles are like you, as pure and noble as the lily?",
  ui_story_5046_50461102_77_dialog_content = "Alright, that's enough talk.",
  ui_story_5046_50461102_78_dialog_content = "Hmm? Where's Hati!?",
  ui_story_5046_50461102_79_dialog_content = "...",
  ui_story_5046_50461102_80_dialog_content = "(Now, Hati!)",
  ui_story_5046_50461102_81_dialog_content = "Hyaa—!",
  ui_story_5046_50461102_82_dialog_content = "Ahh!",
  ui_story_5046_50461102_83_dialog_content = "Where did you come from!?",
  ui_story_5046_50461102_84_dialog_content = "Urgh...",
  ui_story_5046_50461102_85_dialog_content = "Kristen, are you okay!?",
  ui_story_5046_50461102_86_dialog_content = "Let me help you... Can you still stand?",
  ui_story_5046_50461102_87_dialog_content = "PlayerName... Boo-hoo...",
  ui_story_5046_50461102_88_dialog_content = "Come over here.",
  ui_story_5046_50461102_89_dialog_content = "No more hostages. Just hand over the pendant.",
  ui_story_5046_50461102_90_dialog_content = "Or do I have to beat some honesty into you?",
  ui_story_5046_50461102_91_dialog_content = "Alright... Here, here you are.",
  ui_story_5046_50461102_92_dialog_content = "You want the pendant...",
  ui_story_5046_50461102_93_dialog_content = "You can trade it for your life!",
  ui_story_5046_50461102_94_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5046_50461102_95_dialog_content = "!!!",
  ui_story_5046_50461102_96_dialog_content = "Ahh!",
  ui_story_5046_50461102_97_dialog_content = "Pretending to hand over the pendant and launching a sneak attack... Hmph!",
  ui_story_5046_50461102_98_dialog_content = "Now that we're without our weapons, who knows who'll win?",
  ui_story_5046_50461102_99_dialog_content = "Kristen and the Caelestite have little combat power to speak of, so now...",
  ui_story_5046_50461102_100_dialog_content = "It's just you and me.",
  ui_story_5046_50461102_101_dialog_content = "After I deal with you, I'll take care of those two...",
  ui_story_5046_50461102_102_dialog_content = "Hahahahaha!",
  ui_story_5046_50461102_103_dialog_content = "...",
  ui_story_5046_50461102_104_dialog_content = "My sword!",
  ui_story_5046_50461102_105_dialog_content = "Hmph! Never mind, this axe will do just fine.",
  ui_story_5046_50461102_106_dialog_content = "You're not worthy of that sword with all the blood on your hands.",
  ui_story_5046_50461102_X106_dialog_content = "A sword represents justice, yet you're evil.",
  ui_story_5046_50461102_107_dialog_content = "Do you think justice will always prevail against evil?",
  ui_story_5046_50461102_108_dialog_content = "Of course.",
  ui_story_5046_50461102_109_dialog_content = "Don't be so sure you'll beat me.",
  ui_story_5046_50461102_110_dialog_content = "<color=#e8d9bb>Clang—</color>",
  ui_story_5046_50461102_111_dialog_content = "Go to hell!!!",
  ui_story_5046_50461102_112_dialog_content = "Hyaa!",
  ui_story_5046_50461102_113_dialog_content = "Aaaaaah!",
  ui_story_5046_50461102_114_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5046_50461102_115_dialog_content = "...",
  ui_story_5046_50461102_116_dialog_content = "Feel that? That's your sword pressed against your neck.",
  ui_story_5046_50461102_117_dialog_content = "I could cut your throat in a split second and avenge my mother.",
  ui_story_5046_50461102_118_dialog_content = "!!!",
  ui_story_5046_50461102_119_dialog_content = "But I won't.",
  ui_story_5046_50461102_120_dialog_content = "Because PlayerName doesn't want me to.",
  ui_story_5046_50461102_121_dialog_content = "Mom and Dad wouldn't want your blood on my hands either.",
  ui_story_5046_50461102_122_dialog_content = "Hey, you. It's Kristen, right?",
  ui_story_5046_50461102_123_dialog_content = "Urgh...",
  ui_story_5046_50461102_124_dialog_content = "Stop crying already. Before you take him away, can I get the pendant?",
  ui_story_5046_50461102_125_dialog_content = "Pendant? What pendant? Are you planning on robbing me?",
  ui_story_5046_50461102_126_dialog_content = "Why are you still unwilling to confess your crimes!?",
  ui_story_5046_50461102_127_dialog_content = "I don't understand what you're talking about.",
  ui_story_5046_50461102_128_dialog_content = "Sir... No, Zenas.",
  ui_story_5046_50461102_129_dialog_content = "According to the results of this investigation, you are connected to a homicide case and two cases of arson from many years ago. Please cooperate with me.",
  ui_story_5046_50461102_130_dialog_content = "(Kristen recovered so quickly. She was crying just now...)",
  ui_story_5046_50461102_131_dialog_content = "Hmph...",
  ui_story_5046_50461102_132_dialog_content = "You're still the stubborn, strong girl you've always been...",
  ui_story_5046_50461102_133_dialog_content = "I don't want to listen to anything more from you right now. If you have anything to say, save it for the Hall of Justice.",
  ui_story_5046_50461102_134_dialog_content = "If you must know, I didn't really want to kill you just now. I rescued you back then, and you've accompanied me for so many years.",
  ui_story_5046_50461102_135_dialog_content = "How could I ever kill you?",
  ui_story_5046_50461102_136_dialog_content = "Why are you still trying to deceive me?",
  ui_story_5046_50461102_137_dialog_content = "With everything I've told you, can you tell what is true and what is false?",
  ui_story_5046_50461102_138_dialog_content = "Stop it!",
  ui_story_5046_50461102_139_dialog_content = "Liar! You no longer have any right to lecture me!",
  ui_story_5046_50461102_140_dialog_content = "From now on, I'll judge who to trust and who not to trust for myself.",
  ui_story_5046_50461102_141_dialog_content = "I've grown up. I am no longer the sheltered little girl in need of your guidance.",
  ui_story_5046_50461102_142_dialog_content = "As for your crime, the Hall of Justice will reach a just verdict.",
  ui_story_5046_50461102_143_dialog_content = "Sorry, PlayerName. Sorry for losing my composure in front of you...",
  ui_story_5046_50461102_144_dialog_content = "I will escort Zenas back to Lumopolis immediately and inform you of the trial's outcome in due course.",
  ui_story_5046_50461102_145_dialog_content = "My pendant.",
  ui_story_5046_50461102_146_dialog_content = "Rest assured, when I find the pendant, I will deliver it to you personally.",
  ui_story_5046_50461201_1_dialog_content = "<color=#e8d9bb>Several days later...</color>",
  ui_story_5046_50461201_2_dialog_content = "Kristen!",
  ui_story_5046_50461201_3_dialog_content = "Good day, PlayerName.",
  ui_story_5046_50461201_4_dialog_content = "It's been a long time, PlayerName.",
  ui_story_5046_50461201_5_dialog_content = "Oh, Pittman!",
  ui_story_5046_50461201_6_dialog_content = "By the way, is Hati here? I heard she came to visit the Colossus.",
  ui_story_5046_50461201_7_dialog_content = "Kristen.",
  ui_story_5046_50461201_8_dialog_content = "Here you go. This is the pendant.",
  ui_story_5046_50461201_9_dialog_content = "Mom's pendant...",
  ui_story_5046_50461201_10_dialog_content = "Zenas has now been handed over to me for further interrogation.",
  ui_story_5046_50461201_11_dialog_content = "Thanks to you, PlayerName, we also found further clues vital to <color=#FFB400>that other case</color>.",
  ui_story_5046_50461201_12_dialog_content = "Haha... I'm glad I could help.",
  ui_story_5046_50461201_13_dialog_content = "Who would have thought me being kidnapped would cause so much drama?",
  ui_story_5046_50461201_14_dialog_content = "Ahem...",
  ui_story_5046_50461201_15_dialog_content = "Oh, yeah. I have a few questions to ask...",
  ui_story_5046_50461201_16_option_content = "Who was the real culprit in those arson cases over the past two months?",
  ui_story_5046_50461201_17_dialog_content = "Our investigation has shown that the arson cases in Umbraton over the past two months all used the same fuel, including the rehearsal at the orphanage.",
  ui_story_5046_50461201_18_dialog_content = "I sent someone to investigate this fuel, and it appears there are only a few stores that sell it.",
  ui_story_5046_50461201_19_dialog_content = "The store owner identified Zenas as having purchased large quantities of this fuel two months ago.",
  ui_story_5046_50461201_20_dialog_content = "Zenas also admitted that he started all these fires with the intention of silencing the victims.",
  ui_story_5046_50461201_21_dialog_content = "But why did he kill those people?",
  ui_story_5046_50461201_22_dialog_content = "It is related to <color=#FFB400>that case</color>.",
  ui_story_5046_50461201_23_dialog_content = "At that time, five employees, including Hamell, used the orphanage as a cover for sending children away to be experimented on.",
  ui_story_5046_50461201_24_dialog_content = "Except for Zenas and Hamell, the three other orphans who survived the fire at the orphanage weren't doing too well.",
  ui_story_5046_50461201_25_dialog_content = "So the three of them used their shared past to blackmail Zenas, and Zenas was forced to pay them for their silence.",
  ui_story_5046_50461201_26_dialog_content = "But they demanded more and more...",
  ui_story_5046_50461201_27_dialog_content = "And then Zenas silenced them permanently.",
  ui_story_5046_50461201_28_dialog_content = "Correct.",
  ui_story_5046_50461201_29_dialog_content = "Who killed Mr. Hamell?",
  ui_story_5046_50461201_30_dialog_content = "Zenas admitted to starting the fires and killing the three former orphanage employees.",
  ui_story_5046_50461201_31_dialog_content = "There were five people working in the orphanage involved in the case, including Zenas.",
  ui_story_5046_50461201_32_dialog_content = "So, Zenas killed Mr. Hamell?",
  ui_story_5046_50461201_33_dialog_content = "It is highly suspected, but there is currently no evidence, and he has not admitted to it.",
  ui_story_5046_50461201_34_dialog_content = "Is he really responsible for so many murders...?",
  ui_story_5046_50461201_35_dialog_content = "(Kristen doesn't look like she's taking this well...)",
  ui_story_5046_50461201_36_dialog_content = "Kristen, are you okay?",
  ui_story_5046_50461201_37_dialog_content = "Do you really see me as being so weak, PlayerName?",
  ui_story_5046_50461201_38_dialog_content = "N-No, that's not what I meant! I just...",
  ui_story_5046_50461201_39_dialog_content = "I'm fine.",
  ui_story_5046_50461201_40_dialog_content = "I remember everything you said to me that day, PlayerName.",
  ui_story_5046_50461201_41_dialog_content = "PlayerName told me I would be a terrific judge in the future.",
  ui_story_5046_50461201_42_dialog_content = "With so many people around me, encouraging and supporting me all the time, there's no way I could ever feel sad about being alone.",
  ui_story_5046_50461201_43_dialog_content = "Although I still have a long way to go before reaching my goal, I will do my utmost to keep moving forward.",
  ui_story_5046_50461201_44_dialog_content = "Because I really am terrific! Aren't I, PlayerName?",
  ui_story_5046_50461201_45_dialog_content = "We're talking about Kristen here, right? Of course you are!",
  ui_story_5046_50461201_46_dialog_content = "I agree.",
  ui_story_5046_50461201_47_dialog_content = "I second that.",
  ui_story_5046_50461201_48_dialog_content = "Oh! I forgot Mr. Pittman was still here...",
  ui_story_5046_50461201_49_dialog_content = "Ahem... I have given Hati her pendant, so unless you have something else to discuss with me, allow me to take my leave.",
  ui_story_5046_50461201_50_dialog_content = "Farewell.",
  ui_story_5046_50461201_51_dialog_content = "...",
  ui_story_5046_50461201_52_dialog_content = "Feeling nervous, Hati?",
  ui_story_5046_50461201_53_dialog_content = "Yeah.",
  ui_story_5046_50461201_54_dialog_content = "These two pendants are a pair. My mom gave me one half back then.",
  ui_story_5046_50461201_55_dialog_content = "Mom said that as long as I put these two halves together, our family will always be together...",
  ui_story_5046_50461201_56_dialog_content = "But Mom and I have been apart for so long... boo-hoo...",
  ui_story_5046_50461201_57_dialog_content = "Mom... *sob*",
  ui_story_5046_50461201_58_dialog_content = "There, there, don't cry...",
  ui_story_5046_50461201_59_dialog_content = "(It's alright Hati, don't cry.)",
  ui_story_5046_50461201_60_dialog_content = "(Let Mom sing you to sleep...)",
  ui_story_5046_50461201_61_dialog_content = "(Lalala ♪ Lalala ♪)",
  ui_story_5046_50461201_62_dialog_content = "(Hati, watching you sleep so soundly, I wish this moment could last for all eternity.)",
  ui_story_5046_50461201_63_dialog_content = "(But I also want to watch you grow up. I bet you end up looking more and more like Fenrir.)",
  ui_story_5046_50461201_64_dialog_content = "(You were just a little fluffy ball when you were born, but now you're almost up to my knee.)",
  ui_story_5046_50461201_65_dialog_content = "(You might be older now, but you still like me to hold you in my arms and put you to bed, and when you wake up, you still ask me to carry you to the table for dinner...)",
  ui_story_5046_50461201_66_dialog_content = "(I can barely lift you now, let alone walk with you!)",
  ui_story_5046_50461201_67_dialog_content = "(When I'm old and can't walk anymore, you'll carry me to bed and put me on my stool...)",
  ui_story_5046_50461201_68_dialog_content = "(Hati... There's so much I want to say to you...)",
  ui_story_5046_50461201_69_dialog_content = "(I hope I can watch you and grow up with you, always...)",
  ui_story_5046_50461201_70_dialog_content = "(...)",
  ui_story_5046_50461201_71_dialog_content = "(...)",
  ui_story_5046_50461201_72_dialog_content = "(...)",
  ui_story_5046_50461201_73_dialog_content = "...",
  ui_story_5046_50461201_74_dialog_content = "I'm not afraid of you anymore, nor will I be afraid of... this power.",
  ui_story_5046_50461201_75_dialog_content = "I can accept myself completely now.",
  ui_story_5046_50461201_76_dialog_content = "Whether it's the Hati who used to fear her power and hate herself.",
  ui_story_5046_50461201_77_dialog_content = "Or the Hati who uses her flames to protect the people important to her.",
  ui_story_5046_50461201_78_dialog_content = "No matter which Hati it is, they're all me.",
  ui_story_5046_50461201_79_dialog_content = "(Am I... ready to accept myself...?)",
  ui_story_5046_50461201_80_dialog_content = "I'm ready.",
  ui_story_5046_50461202_1_dialog_content = "I... won?",
  ui_story_5046_50461202_2_dialog_content = "You're...?",
  ui_story_5046_50461202_3_dialog_content = "(You can accept yourself entirely now.)",
  ui_story_5046_50461202_4_dialog_content = "(You have reached a reconciliation with yourself.)",
  ui_story_5046_50461202_5_dialog_content = "(I'm very happy to see that you can use your power so well.)",
  ui_story_5046_50461202_6_dialog_content = "(I should leave now.)",
  ui_story_5046_50461202_7_dialog_content = "I can feel the power of the flames...",
  ui_story_5046_50461202_8_dialog_content = "This power is constantly flooding into my body...",
  ui_story_5046_50461202_9_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5046_50461202_10_dialog_content = "A flame... A flame created by my thoughts...",
  ui_story_5046_50461202_11_dialog_content = "It's warm.",
  ui_story_5046_50461202_12_dialog_content = "PlayerName?",
  ui_story_5046_50461202_13_dialog_content = "Are you awake? I was just humming a song when you fell asleep.",
  ui_story_5046_50461202_14_dialog_content = "You looked so peaceful, I didn't want to wake you up.",
  ui_story_5046_50461202_15_dialog_content = "I dreamt about when I was a child. I accidentally burned something with my flames, and my mom told me off.",
  ui_story_5046_50461202_16_dialog_content = "She hugged me and sang me a lullaby while rocking me to sleep.",
  ui_story_5046_50461202_17_dialog_content = "After I fell asleep, I saw...",
  ui_story_5046_50461202_18_dialog_content = "My inner demon.",
  ui_story_5046_50461202_19_dialog_content = "I told it that I was no longer afraid of it.",
  ui_story_5046_50461202_20_dialog_content = "And then?",
  ui_story_5046_50461202_21_dialog_content = "I... defeated it.",
  ui_story_5046_50461202_22_dialog_content = "I am no longer afraid of the flames. I can feel their warmth surrounding me.",
  ui_story_5046_50461202_23_dialog_content = "It's like being held by my mom and dad.",
  ui_story_5046_50461202_24_dialog_content = "It must've been a nice dream.",
  ui_story_5046_50461202_25_dialog_content = "I dare to face anything. I got that from my mom and dad.",
  ui_story_5046_50461202_26_dialog_content = "And from you, PlayerName.",
  ui_story_5046_50461202_27_dialog_content = "Thank you for being there for me.",
  ui_story_5046_50461202_28_dialog_content = "You don't need to thank me. We're friends, after all.",
  ui_story_5046_50461202_29_dialog_content = "I want to put the two halves of the pendant together now. PlayerName, will you join me?",
  ui_story_5046_50461202_30_dialog_content = "Sure! Let's do this together!",
  ui_story_5046_50461202_31_dialog_content = "<color=#e8d9bb>Click—</color>",
  ui_story_5046_50461202_32_dialog_content = "Something appears to have popped out at the bottom after putting the two halves together...",
  ui_story_5046_50461202_33_dialog_content = "<color=#e8d9bb>*paper unfolding*</color>",
  ui_story_5046_50461202_34_dialog_content = "Th-This is...",
  ui_story_5046_50461202_35_dialog_content = "So many photos...",
  ui_story_5046_50461202_36_dialog_content = "This is... a picture of my family that I drew when I was small.",
  ui_story_5046_50461202_37_dialog_content = "This is the last thing I expected to find in the pendant.",
  ui_story_5046_50461202_38_dialog_content = "Some of your childhood photos are here too!",
  ui_story_5046_50461202_39_dialog_content = "There are two more photos here...",
  ui_story_5046_50461202_40_dialog_content = "This must be your mother. So, then, this must be...",
  ui_story_5046_50461202_41_dialog_content = "Dad...",
  ui_story_5046_50461202_42_dialog_content = "Huh? Is that your father?",
  ui_story_5046_50461202_43_dialog_content = "It looks like they're in a laboratory...",
  ui_story_5046_50461202_44_dialog_content = "I...",
  ui_story_5046_50461202_45_dialog_content = "I never met my dad.",
  ui_story_5046_50461202_46_dialog_content = "But looking at this photo, I think it must be him...",
  ui_story_5046_50461202_47_dialog_content = "\"As long as you put these two halves together, our family will always be together...\"",
  ui_story_5046_50461202_48_dialog_content = "Now our family will be together forever.",
  ui_story_5046_50461202_49_dialog_content = "<color=#e8d9bb>Somewhere in Umbraton</color>",
  ui_story_5046_50461202_50_dialog_content = "After handing the letter to Zenas, I followed him.",
  ui_story_5046_50461202_51_dialog_content = "You guys stick around and comb every inch of the place.",
  ui_story_5046_50461202_52_dialog_content = "Yes, sir!",
  ui_story_5046_50461202_53_dialog_content = "...",
  ui_story_5046_50461202_54_dialog_content = "(Why's he going this way...? Is he heading to the orphanage?)",
  ui_story_5046_50461202_55_dialog_content = "It's been a long time, old friend.",
  ui_story_5046_50461202_56_dialog_content = "It's you.",
  ui_story_5046_50461202_57_dialog_content = "(Hamell? Could that thing in his hand be what the Shadowlord wants?)",
  ui_story_5046_50461202_58_dialog_content = "Not happy to see your old friend?",
  ui_story_5046_50461202_59_dialog_content = "I'm just afraid you're not here because you wanted to see me but rather because you want something from me.",
  ui_story_5046_50461202_60_dialog_content = "Don't be so cynical. This time I'm here to bring you some news.",
  ui_story_5046_50461202_61_dialog_content = "So, she asked to meet up. What does that have to do with me?",
  ui_story_5046_50461202_62_dialog_content = "Andre and the other two are dead. Sooner or later, it will be our turn.",
  ui_story_5046_50461202_63_dialog_content = "Rather than wait for her to come to our door, let's go out to greet her.",
  ui_story_5046_50461202_64_dialog_content = "(It feels like Hamell keeps looking over there subconsciously.)",
  ui_story_5046_50461202_65_dialog_content = "I know you want to ask why I didn't do anything.",
  ui_story_5046_50461202_66_dialog_content = "In this letter of hers, she calls me out by name. If anyone were to find out the connection between us, it could make things a lot trickier.",
  ui_story_5046_50461202_67_dialog_content = "If that happens, I won't be able to protect you anymore. Who's to say... you might even be found out too.",
  ui_story_5046_50461202_68_dialog_content = "You're threatening me...",
  ui_story_5046_50461202_69_dialog_content = "We all need to look out for ourselves. This is the address.",
  ui_story_5046_50461202_70_dialog_content = "Fine, I can help you with this, but you need to find some people to assist me.",
  ui_story_5046_50461202_71_dialog_content = "After Zenas left, I rummaged around while Hamell was asleep and found it.",
  ui_story_5046_50461202_72_dialog_content = "A record of their transaction dates, prices, and buyer information.",
  ui_story_5046_50461202_73_dialog_content = "Impressive.",
  ui_story_5046_50461202_74_dialog_content = "Many years ago, Umbraton was a chaotic, lawless land. The people of Lumopolis treated it as a dumping ground where they buried their sins.",
  ui_story_5046_50461202_75_dialog_content = "Now that I am the guardian of Umbraton, I won't let it return to the way it was.",
  ui_story_5046_50461202_76_dialog_content = "The shadows know all secrets.",
  ui_story_5046_50461202_77_dialog_content = "Understood, Shadowlord.",
  ui_story_5046_50461202_78_dialog_content = "You've done well these past few days.",
  ui_story_5046_50461202_79_dialog_content = "<color=#e8d9bb>Lumopolis Prison</color>",
  ui_story_5046_50461202_80_dialog_content = "...",
  ui_story_5046_50461202_81_dialog_content = "Here comes my young lady.",
  ui_story_5046_50461202_82_dialog_content = "It's so cold and gloomy here. This is no place for a little lady like you.",
  ui_story_5046_50461202_83_dialog_content = "I came to say goodbye to you, and my past.",
  ui_story_5046_50461202_84_dialog_content = "I always used to follow you blindly, progressing in the direction you wanted me to in both my thoughts and actions.",
  ui_story_5046_50461202_85_dialog_content = "I was your puppet.",
  ui_story_5046_50461202_86_dialog_content = "Young lady, I never forced you to do anything you didn't want to. What's on your mind?",
  ui_story_5046_50461202_87_dialog_content = "It makes me sick to know you were behind all this, yet you persist in affecting this nonchalant attitude!",
  ui_story_5046_50461202_88_dialog_content = "You are complete and utter scum!",
  ui_story_5046_50461202_89_dialog_content = "...",
  ui_story_5046_50461202_90_dialog_content = "Sorry, I forgot myself.",
  ui_story_5046_50461202_91_dialog_content = "The pendant.",
  ui_story_5046_50461202_92_dialog_content = "What is in that pendant?",
  ui_story_5046_50461202_93_dialog_content = "Is that all you wanted to ask?",
  ui_story_5046_50461202_94_dialog_content = "...",
  ui_story_5046_50461202_95_dialog_content = "I paid so much for this pendant.",
  ui_story_5046_50461202_96_dialog_content = "I want to know if there's something hidden inside... The thing I've been looking for.",
  ui_story_5046_50461202_97_dialog_content = "There were only some photos of Hati's family in it.",
  ui_story_5046_50461202_98_dialog_content = "Just some photos?",
  ui_story_5046_50461202_99_dialog_content = "Just some photos.",
  ui_story_5046_50461202_100_dialog_content = "Hahahahahaha!",
  ui_story_5046_50461202_101_dialog_content = "Well, I never...",
  ui_story_5046_50461202_102_dialog_content = "I didn't expect things to turn out like this...",
  ui_story_5046_50461202_103_dialog_content = "If you have nothing else to say...",
  ui_story_5046_50461202_104_dialog_content = "I'll take my leave.",
  ui_story_5046_50461202_105_dialog_content = "...",
  ui_story_5046_50461202_106_dialog_content = "This is the last time we will ever see each other.",
  ui_story_5046_50461202_107_dialog_content = "Goodbye, Sir.",
  ui_story_5046_50461202_108_dialog_content = "(Goodbye... to my past.)",
  ui_story_5046_50461202_109_dialog_content = "<color=#e8d9bb>Umbraton Orphanage Completion Day Ceremony</color>",
  ui_story_5046_50461202_110_dialog_content = "The completion of this orphanage symbolizes the painstaking efforts of countless caring Umbraton citizens. Please allow me to take this opportunity to express my gratitude to these people once more!",
  ui_story_5046_50461202_111_dialog_content = "I hereby declare the Umbraton Orphanage to be officially completed!",
  ui_story_5046_50461202_112_dialog_content = "Congratulations!",
  ui_story_5046_50461202_113_dialog_content = "What a triumph! It's magnificent!",
  ui_story_5046_50461202_114_dialog_content = "I hope this orphanage becomes the source of many happy memories, and that the mistakes of the past will never be repeated.",
  ui_story_5046_50461202_115_dialog_content = "This orphanage is now under the supervision of Umbraton's Shadowlord, so you don't have to worry about that, PlayerName.",
  ui_story_5046_50461202_116_dialog_content = "Grimme!?",
  ui_story_5046_50461202_117_dialog_content = "On the day Zenas was arrested, Hati and I went to the Firefly Bar looking for you, but you weren't there...",
  ui_story_5046_50461202_118_dialog_content = "I had business to take care of.",
  ui_story_5046_50461202_119_dialog_content = "By the way, where's Hati?",
  ui_story_5046_50461202_120_dialog_content = "She's...",
  ui_story_5046_50461202_121_dialog_content = "Now let's warmly welcome our orphanage's fire-fighting hero—Hati!",
  ui_story_5046_50461202_122_dialog_content = "...",
  ui_story_5046_50461202_123_dialog_content = "Hati's heroic fire-fighting abilities have averted disaster across Umbraton over the past two months, putting out big and small fires.",
  ui_story_5046_50461202_124_dialog_content = "A few days ago, a little girl was trapped in a fire at the rehearsal for this ceremony...",
  ui_story_5046_50461202_125_dialog_content = "Hati rushed in without a second thought and rescued her...",
  ui_story_5046_50461202_126_dialog_content = "So, she's not an arsonist...",
  ui_story_5046_50461202_127_dialog_content = "She was actually there saving someone?",
  ui_story_5046_50461202_128_dialog_content = "She's so brave, like a great hero...",
  ui_story_5046_50461202_129_dialog_content = "Miss Bethel is so thoughtful. Now no one in Umbraton will treat Hati like a criminal.",
  ui_story_5046_50461202_130_dialog_content = "She's smart. I couldn't handle everything this well even if I had three brains.",
  ui_story_5046_50461202_131_dialog_content = "Hehe... You have your own strengths, PlayerName. Don't forget, nobody's perfect.",
  ui_story_5046_50461202_132_dialog_content = "This is so annoying.",
  ui_story_5046_50461202_133_dialog_content = "Hey... You ran off the stage so quickly.",
  ui_story_5046_50461202_134_dialog_content = "My hair was standing while I'm up there.",
  ui_story_5046_50461202_135_dialog_content = "You'll get used to it. After all, you haven't been in the outside world that long, and there are still a lot of things for you to learn out here.",
  ui_story_5046_50461202_136_dialog_content = "Hmm...",
  ui_story_5046_50461202_137_dialog_content = "Hati, what are your plans for the future?",
  ui_story_5046_50461202_138_dialog_content = "I...",
  ui_story_5046_50461202_139_dialog_content = "I don't know.",
  ui_story_5046_50461202_140_dialog_content = "Finding my lost memories of my mother used to be my goal.",
  ui_story_5046_50461202_141_dialog_content = "But now that goal has been achieved...",
  ui_story_5046_50461202_142_dialog_content = "I don't know what else I should do.",
  ui_story_5046_50461202_143_dialog_content = "That doesn't matter. Life is essentially just one goal after another!",
  ui_story_5046_50461202_144_dialog_content = "You should always take a break before finding your next goal.",
  ui_story_5046_50461202_145_dialog_content = "After all, you already did so well in achieving your last goal.",
  ui_story_5046_50461202_146_dialog_content = "My next goal?",
  ui_story_5046_50461202_147_dialog_content = "I don't know what my next goal will be.",
  ui_story_5046_50461202_148_dialog_content = "You'll find it.",
  ui_story_5046_50461202_149_dialog_content = "Your life has only just begun!",
  ui_story_5046_50461202_150_dialog_content = "Like I said before, many new and exciting things are waiting for you to discover in this world!",
  ui_story_5046_50461202_151_dialog_content = "For now, just enjoy your leisure time while you can!",
  ui_story_5046_50461202_152_dialog_content = "Yeah.",
  ui_story_5046_50461202_153_dialog_content = "Thank you, PlayerName.",
  ui_story_5046_50461202_154_dialog_content = "I'm more worried about whether you might have another headache heading your way soon...",
  ui_story_5046_50461202_155_dialog_content = "I'm wondering what that big dog who kinda looks like you will say to you next...",
  ui_story_5046_50461202_156_dialog_content = "I don't mind.",
  ui_story_5046_50461202_157_dialog_content = "We've already come to an agreement.",
  ui_story_5046_50461202_158_dialog_content = "Now, we are one.",
  ui_story_5046_50461202_159_dialog_content = "Whoa!",
  ui_story_5046_50461202_160_dialog_content = "You look just like that big dog!",
  ui_story_5046_50461202_161_dialog_content = "Yeah.",
  ui_story_5046_50461202_162_dialog_content = "Don't be afraid.",
  ui_story_5046_50461202_163_dialog_content = "I can now fully harness its power...",
  ui_story_5046_50461202_164_dialog_content = "It's the power of fire.",
  ui_story_5046_50461202_165_dialog_content = "Hi!",
  ui_story_5046_50461202_166_dialog_content = "You're...",
  ui_story_5046_50461202_167_dialog_content = "You're... the little girl from that day.",
  ui_story_5046_50461202_168_dialog_content = "I made a flower ring for the big doggy that saved us!",
  ui_story_5046_50461202_169_dialog_content = "Do you know where the big doggy is?",
  ui_story_5046_50461202_170_dialog_content = "She...",
  ui_story_5046_50461202_171_dialog_content = "She's right here.",
  ui_story_5046_50461202_172_dialog_content = "Wow!",
  ui_story_5046_50461202_173_dialog_content = "Do I really look that scary?",
  ui_story_5046_50461202_174_dialog_content = "What a huge doggy!",
  ui_story_5046_50461202_175_dialog_content = "She's beautiful!",
  ui_story_5046_50461202_176_dialog_content = "...",
  ui_story_5046_50461202_177_dialog_content = "Are you the big doggy who saved me the other day?",
  ui_story_5046_50461202_178_dialog_content = "Yeah.",
  ui_story_5046_50461202_179_dialog_content = "Oh! I know!",
  ui_story_5046_50461202_180_dialog_content = "The big doggy's been working so hard to save people all over town, getting stronger and stronger and more and more awesome!",
  ui_story_5046_50461202_181_dialog_content = "That's why the doggy became a super huge doggy!",
  ui_story_5046_50461202_182_dialog_content = "Ahahahahah...",
  ui_story_5046_50461202_183_dialog_content = "Doggy! Big hero doggy!",
  ui_story_5046_50461202_184_dialog_content = "Hya... Hya...",
  ui_story_5046_50461202_185_dialog_content = "Waah... I can't reach...",
  ui_story_5046_50461202_186_dialog_content = "Are you trying to put this garland on her?",
  ui_story_5046_50461202_187_dialog_content = "Yeah!",
  ui_story_5046_50461202_188_dialog_content = "Let me squat down a little.",
  ui_story_5046_50461202_189_dialog_content = "Perfect!",
  ui_story_5046_50461202_190_dialog_content = "Thank you for saving me!",
  ui_story_5046_50461202_191_dialog_content = "I secretly went outside to pick these flowers without telling the caretaker...",
  ui_story_5046_50461202_192_dialog_content = "You shouldn't sneak out like that!",
  ui_story_5046_50461202_193_dialog_content = "But... But I thought the big doggy saved me...",
  ui_story_5046_50461202_194_dialog_content = "So I should give the big doggy a gift!",
  ui_story_5046_50461202_195_dialog_content = "As long as you're alright.",
  ui_story_5046_50461202_196_dialog_content = "You don't need to give me anything.",
  ui_story_5046_50461202_197_dialog_content = "Nuh-uh!",
  ui_story_5046_50461202_198_dialog_content = "In the orphanage, kids who help people get rewards from the caretaker!",
  ui_story_5046_50461202_199_dialog_content = "The big doggy saved me, so the big doggy deserves a reward!",
  ui_story_5046_50461202_200_dialog_content = "But I don't have anything...",
  ui_story_5046_50461202_201_dialog_content = "...",
  ui_story_5046_50461202_202_dialog_content = "Just saying \"thank you\" is enough.",
  ui_story_5046_50461202_203_dialog_content = "So, I was thinking, \"what would be a good gift for a big doggy...?\"",
  ui_story_5046_50461202_204_dialog_content = "And just as I was thinking that a little flower floated in from outside the window!",
  ui_story_5046_50461202_205_dialog_content = "It was just like the big doggy falling from the sky!",
  ui_story_5046_50461202_206_dialog_content = "So I made this flower ring, hoping the big doggy would be happy to see it...",
  ui_story_5046_50461202_207_dialog_content = "Do you like the flower ring I made?",
  ui_story_5046_50461202_208_dialog_content = "Sure...",
  ui_story_5046_50461202_209_dialog_content = "I like it.",
  ui_story_5046_50461202_210_dialog_content = "Thank you.",
  ui_story_5046_50461202_211_dialog_content = "Thank you, everyone."
}
return config
